QT_ISI(23,{"3733":["(Dan tiadalah) Maa bermakna Nafi (Kami turunkan kepada kaumnya) kaum Habib An Najjar (setelah dia meninggal) sesudah Habib mati karena dirajam oleh mereka (suatu pasukan pun dari langit) yaitu malaikat-malaikat untuk membinasakan mereka (dan tidak layak Kami menurunkannya) menurunkan Malaikat untuk membinasakan seseorang.",[["۞ وَمَآ","Dan tidak"],["أَنزَلْنَا","Kami turunkan"],["عَلَىٰ","ke atas"],["قَوْمِهِۦ","umatnya"],["مِنۢ","selepas dia"],["بَعْدِهِۦ","selepas dia"],["مِن","sebarang"],["جُندٍۢ","tuan rumah"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","syurga itu"],["وَمَا","dan bukan"],["كُنَّا","adalah Kami"],["مُنزِلِينَ","(untuk) menurunkan"]]],"3734":["(Tidak ada siksaan) yakni hukuman atas mereka (melainkan satu teriakan saja) malaikat Jibril berteriak keras kepada mereka (maka tiba-tiba mereka semuanya mati) tak bergerak lagi, mati semuanya.",[["إِن","Tidak"],["كَانَتْ","ia adalah"],["إِلَّا","tetapi"],["صَيْحَةًۭ","teriakan"],["وَٰحِدَةًۭ","satu"],["فَإِذَا","maka lihatlah"],["هُمْ","mereka"],["خَـٰمِدُونَ","(telah) dipadamkan"]]],"3735":["(Alangkah besarnya penyesalan terhadap hamba-hamba itu) terhadap mereka dan orang-orang yang seperti mereka, yaitu orang-orang yang mendustakan rasul-rasul, karena akhirnya mereka dibinasakan. Yang dimaksud dengan penyesalan di sini adalah perasaan sakit yang amat sangat akibat suara malaikat Jibril. Kata Nida atau kata seru pada lafal Yaa hasratan hanyalah merupakan kata kiasan, maknanya sudah saatnya bagimu, maka menghadaplah kamu (tiada datang seorang rasul pun kepada mereka melainkan mereka selalu memperolok-olokkannya) ungkapan-ungkapan ini untuk menjelaskan penyebab dari penyesalan tadi. Di dalamnya terkandung pengertian ejekan mereka yang menyebabkan diri mereka binasa, setelah itu mereka menyesal karenanya.",[["يَـٰحَسْرَةً","Aduhai"],["عَلَى","bagi"],["ٱلْعِبَادِ ۚ","para hamba"],["مَا","Tidak"],["يَأْتِيهِم","datang kepada mereka"],["مِّن","sebarang"],["رَّسُولٍ","Utusan"],["إِلَّا","tetapi"],["كَانُوا۟","mereka lakukan"],["بِهِۦ","mengejek dia"],["يَسْتَهْزِءُونَ","mengejek dia"]]],"3736":["(Tidakkah mereka mengetahui) yakni penduduk Mekah yang mengatakan kepada Nabi saw. sebagaimana yang disitir oleh firman-Nya, \"Kamu bukan seorang yang dijadikan rasul.\" (Q.S. Ar-Ra'd, 43.) Istifham atau kata tanya pada ayat ini mengandung makna Taqrir yakni ketahuilah oleh kalian (berapa banyak) lafal Kam mengandung makna kalimat berita, yakni banyak sekali; maknanya, sesungguhnya Kami (telah Kami binasakan sebelum mereka) amatlah banyak (umat-umat) bangsa-bangsa. (Bahwasanya mereka itu) orang-orang yang telah Kami binasakan (kepada mereka) yaitu orang-orang yang mendustakan Nabi saw. (tiada kembali) apakah mereka tidak mengambil pelajaran darinya. Lafal Annahum dan seterusnya berkedudukan menjadi Badal dari kalimat sebelumnya, dengan memelihara makna yang telah disebutkan.",[["أَلَمْ","Jangan"],["يَرَوْا۟","mereka lihat"],["كَمْ","berapa ramai"],["أَهْلَكْنَا","Kami musnahkan"],["قَبْلَهُم","sebelum mereka"],["مِّنَ","daripada"],["ٱلْقُرُونِ","generasi"],["أَنَّهُمْ","Bahawa mereka"],["إِلَيْهِمْ","kepada mereka"],["لَا","tidak akan kembali"],["يَرْجِعُونَ","tidak akan kembali"]]],"3737":["(Dan tiadalah) bila dianggap sebagai In Nafiyah. Sesungguhnya, bila dianggap sebagai In Mukhaffafah dari Inna (masing-masing) dari semua makhluk, Kullun berkedudukan menjadi Mubtada (melainkan) apabila dibaca Tasydid artinya sama dengan lafal illa. Jika dibaca Takhfif yaitu menjadi Lamaa, maka huruf Lamnya adalah Lam Fariqah dan huruf Ma-nya adalah Zaidah (dikumpulkan) menjadi Khabar dari Mubtada, yakni dihimpunkan (kepada Kami kembali) untuk menjalani penghisaban; lafal ayat ini menjadi Khabar kedua",[["وَإِن","Dan pastinya"],["كُلٌّۭ","semua"],["لَّمَّا","kemudian"],["جَمِيعٌۭ","bersama-sama"],["لَّدَيْنَا","sebelum Kami"],["مُحْضَرُونَ","(akan) dibawa"]]],"3738":["(Dan suatu tanda bagi mereka) yang menunjukkan bahwa mereka akan dibangkitkan kembali, lafal ayat ini berkedudukan menjadi Khabar Muqaddam (adalah bumi yang mati) dapat dibaca Al Maytati atau Al Mayyitati (Kami hidupkan bumi itu) dengan air, menjadi Mubtada Muakhkhar (dan Kami keluarkan daripadanya biji-bijian) seperti gandum (maka daripadanya mereka makan.)",[["وَءَايَةٌۭ","Dan Tanda"],["لَّهُمُ","bagi mereka"],["ٱلْأَرْضُ","(ialah) bumi"],["ٱلْمَيْتَةُ","mati"],["أَحْيَيْنَـٰهَا","Kami memberinya kehidupan"],["وَأَخْرَجْنَا","dan Kami lahirkan"],["مِنْهَا","daripadanya"],["حَبًّۭا","bijirin"],["فَمِنْهُ","dan daripadanya"],["يَأْكُلُونَ","mereka makan"]]],"3739":["(Dan Kami jadikan padanya kebun-kebun) ladang-ladang (kurma dan anggur dan Kami pancarkan padanya beberapa mata air) dari sebagian kebun-kebun itu.",[["وَجَعَلْنَا","Dan Kami letakkan"],["فِيهَا","di dalamnya"],["جَنَّـٰتٍۢ","taman-taman"],["مِّن","daripada"],["نَّخِيلٍۢ","kurma"],["وَأَعْنَـٰبٍۢ","dan anggur"],["وَفَجَّرْنَا","dan Kami memancarkan air"],["فِيهَا","di dalamnya"],["مِنَ","daripada"],["ٱلْعُيُونِ","mata air"]]],"3740":["(Supaya mereka dapat makan dari buahnya) dapat dibaca Tsamarihi atau Tsumurihi, yakni buah pohon yang telah disebutkan tadi, yaitu buah kurma dan buah-buah lainnya (dan dari apa yang diusahakan oleh tangan mereka) bukan dari hasil buah-buahan. (Maka mengapakah mereka tidak bersyukur?) atas nikmat-nikmat Allah yang telah dilimpahkan kepada mereka.",[["لِيَأْكُلُوا۟","Supaya mereka boleh makan"],["مِن","daripada"],["ثَمَرِهِۦ","buahnya"],["وَمَا","Dan tidak"],["عَمِلَتْهُ","berjaya"],["أَيْدِيهِمْ ۖ","tangan mereka"],["أَفَلَا","Jadi tidak akan"],["يَشْكُرُونَ","mereka bersyukur"]]],"3741":["(Maha Suci Allah yang telah menciptakan pasangan-pasangan) yang berjenis-jenis (semuanya, baik dari apa yang ditumbuhkan oleh bumi) berupa biji-bijian dan lain-lainnya (dan dari diri mereka) yaitu jenis pria dan wanita (maupun dari apa yang tidak mereka ketahui) yaitu makhluk-makhluk yang ajaib dan aneh.",[["سُبْحَـٰنَ","Maha Suci"],["ٱلَّذِى","(kepada) Yang Maha Esa"],["خَلَقَ","dicipta"],["ٱلْأَزْوَٰجَ","(dalam) berpasangan"],["كُلَّهَا","semua"],["مِمَّا","tentang apa"],["تُنۢبِتُ","tumbuh"],["ٱلْأَرْضُ","bumi"],["وَمِنْ","dan daripada"],["أَنفُسِهِمْ","diri mereka"],["وَمِمَّا","dan apa"],["لَا","tidak"],["يَعْلَمُونَ","mereka tahu"]]],"3742":["(Dan suatu tanda bagi mereka) yang menunjukkan kekuasaan Allah yang besar (adalah malam; Kami tanggalkan) Kami pisahkan (siang dari malam itu, maka dengan serta merta mereka berada dalam kegelapan) mereka memasuki kegelapan malam hari.",[["وَءَايَةٌۭ","Dan Tanda"],["لَّهُمُ","bagi mereka"],["ٱلَّيْلُ","(ialah) malam"],["نَسْلَخُ","Kita tarik diri"],["مِنْهُ","daripadanya"],["ٱلنَّهَارَ","hari itu"],["فَإِذَا","Kemudian lihatlah"],["هُم","mereka"],["مُّظْلِمُونَ","(ialah) mereka yang berada dalam kegelapan"]]],"3743":["(Dan matahari berjalan) ayat ini dan seterusnya merupakan bagian daripada ayat Wa-aayatul Lahum, atau merupakan ayat yang menyendiri, yakni tidak terikat oleh ayat sebelumnya demikian pula ayat Wal Qamara, pada ayat selanjutnya (di tempat peredarannya) tidak akan menyimpang dari garis edarnya. (Demikianlah) beredarnya matahari itu (ketetapan Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Mengetahui) tentang makhluk-Nya.",[["وَٱلشَّمْسُ","Dan matahari"],["تَجْرِى","berlari"],["لِمُسْتَقَرٍّۢ","kepada tempoh yang ditetapkan"],["لَّهَا ۚ","baginya"],["ذَٰلِكَ","Itu"],["تَقْدِيرُ","(ialah) Dekri"],["ٱلْعَزِيزِ","(dari) Yang Maha Perkasa"],["ٱلْعَلِيمِ","yang Maha Mengetahui"]]],"3744":["(Dan bagi bulan) dapat dibaca Wal Qamaru atau Wal Qamara, bila dibaca nashab yaitu Wal Qamara berarti dinashabkan oleh Fiil sesudahnya yang berfungsi menafsirkannya yaitu (telah Kami tetapkan) bagi peredarannya (manzilah-manzilah) sebanyak dua puluh delapan manzilah selama dua puluh delapan malam untuk setiap bulannya. Kemudian bersembunyi selama dua malam, jika bilangan satu bulan tiga puluh hari, dan satu malam jika bilangan satu bulan dua puluh sembilan hari (sehingga kembalilah ia) setelah sampai ke manzilah yang terakhir, menurut pandangan mata (sebagai bentuk tandan yang tua) bila sudah lanjut masanya bagaikan ketandan, lalu menipis, berbentuk sabit dan berwarna kuning.",[["وَٱلْقَمَرَ","Dan bulan"],["قَدَّرْنَـٰهُ","Kami telah menetapkan untuk itu"],["مَنَازِلَ","fasa"],["حَتَّىٰ","sehingga"],["عَادَ","ia kembali"],["كَٱلْعُرْجُونِ","seperti tangkai kurma"],["ٱلْقَدِيمِ","yang lama"]]],"3745":["(Tidaklah mungkin bagi matahari) tidak akan terjadi (mendapatkan bulan) yaitu matahari dan bulan bersatu di malam hari (dan malam pun tidak dapat mendahului siang) malam hari tidak akan datang sebelum habis waktu siang hari. (Dan masing-masing) matahari, bulan dan bintang-bintang. Tanwin lafal Kullun ini merupakan pergantian dari Mudhaf Ilaih (pada garis edarnya) yang membundar (beredar) pada garis edarnya masing-masing. Di dalam ungkapan ini benda-benda langit diserupakan sebagai makhluk yang berakal, karenanya mereka diungkapkan dengan lafal Yasbahuuna.",[["لَا","Tidak"],["ٱلشَّمْسُ","matahari"],["يَنۢبَغِى","adalah dibenarkan"],["لَهَآ","untuk itu"],["أَن","bahawa"],["تُدْرِكَ","ia memintas"],["ٱلْقَمَرَ","bulan"],["وَلَا","dan bukan"],["ٱلَّيْلُ","malam"],["سَابِقُ","(boleh) mengatasi"],["ٱلنَّهَارِ ۚ","hari itu"],["وَكُلٌّۭ","tetapi semua"],["فِى","dalam"],["فَلَكٍۢ","sebuah orbit"],["يَسْبَحُونَ","mereka terapung"]]],"3746":["(Dan suatu tanda bagi mereka) yang menunjukkan kekuasaan Kami (adalah bahwa Kami angkut keturunan mereka) menurut qiraat yang lain lafal Dzurriyyatahum dibaca dalam bentuk jamak sehingga bacaannya menjadi Dzurriyyaatihim, maksudnya ialah kakek moyang mereka (dalam bahtera) yakni perahu Nabi Nuh (yang penuh muatan) dipadati penumpang.",[["وَءَايَةٌۭ","Dan Tanda"],["لَّهُمْ","bagi mereka"],["أَنَّا","(ialah) itu"],["حَمَلْنَا","Kami membawa"],["ذُرِّيَّتَهُمْ","keturunan mereka"],["فِى","dalam"],["ٱلْفُلْكِ","kapal itu"],["ٱلْمَشْحُونِ","sarat"]]],"3747":["(Dan Kami ciptakan untuk mereka seperti bahtera itu) seperti perahu Nabi Nuh, perahu kecil dan besar yang dibuat oleh mereka sesudahnya, bentuknya sama dengan perahu Nabi Nuh. Ini berkat apa yang telah Allah swt. ajarkan kepada Nabi Nuh (yang akan mereka kendarai) mereka berlayar dengannya.",[["وَخَلَقْنَا","Dan Kami ciptakan"],["لَهُم","bagi mereka"],["مِّن","daripada"],["مِّثْلِهِۦ","(yang) menyukainya"],["مَا","apa"],["يَرْكَبُونَ","mereka menunggang"]]],"3748":["(Dan jika Kami menghendaki niscaya Kami tenggelamkan mereka) sekalipun memakai perahu (maka tiadalah penolong) yakni penyelamat (bagi mereka dan tidak -pula- mereka diselamatkan) ditolong sehingga selamat.",[["وَإِن","Dan jika"],["نَّشَأْ","Kami akan"],["نُغْرِقْهُمْ","Kita boleh menenggelamkan mereka"],["فَلَا","maka tidak"],["صَرِيخَ","(akan menjadi) seorang yang membalas tangisan"],["لَهُمْ","bagi mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يُنقَذُونَ","akan diselamatkan"]]],"3749":["(Tetapi -Kami selamatkan mereka- karena rahmat yang besar dari Kami dan untuk memberikan kesenangan hidup sampai kepada suatu ketika) tiada yang menyelamatkan mereka melainkan rahmat Kami kepada mereka; dan karena Kami hendak memberikan kesenangan hidup kepada mereka sampai batas ajal mereka.",[["إِلَّا","Kecuali"],["رَحْمَةًۭ","(oleh) Rahmat"],["مِّنَّا","daripada Kami"],["وَمَتَـٰعًا","dan rezeki"],["إِلَىٰ","bagi"],["حِينٍۢ","suatu masa"]]],"3750":["(Dan apabila dikatakan kepada mereka, \"Takutlah kalian akan siksa yang di hadapan kalian) berupa azab di dunia sebagaimana apa yang telah menimpa orang-orang selain mereka (dan siksa yang akan datang) yaitu azab di akhirat (supaya kalian mendapat rahmat\") tetapi mereka tetap berpaling.",[["وَإِذَا","Dan apabila"],["قِيلَ","dikatakan"],["لَهُمُ","kepada mereka"],["ٱتَّقُوا۟","Takut"],["مَا","apa"],["بَيْنَ","(ada) sebelum kamu"],["أَيْدِيكُمْ","(ada) sebelum kamu"],["وَمَا","dan apa"],["خَلْفَكُمْ","(ada) di belakang kamu"],["لَعَلَّكُمْ","supaya kamu"],["تُرْحَمُونَ","mendapat rahmat"]]],"3751":["(Dan sekali-kali tiada datang kepada mereka suatu tanda dari tanda-tanda kekuasaan Rabb mereka melainkan mereka selalu berpaling daripadanya.)",[["وَمَا","Dan tidak"],["تَأْتِيهِم","datang kepada mereka"],["مِّنْ","daripada"],["ءَايَةٍۢ","sebuah Tanda"],["مِّنْ","daripada"],["ءَايَـٰتِ","(the) Tanda-tanda"],["رَبِّهِمْ","(dari) Tuhan mereka"],["إِلَّا","tetapi"],["كَانُوا۟","mereka"],["عَنْهَا","daripadanya"],["مُعْرِضِينَ","berpaling"]]],"3752":["(Dan apabila dikatakan) berkata sahabat-sahabat yang miskin (kepada mereka, \"Nafkahkanlah) sedekahkanlah kepada kami (sebagian dari rezeki yang diberikan Allah kepada kalian\") berupa harta benda (maka orang-orang yang kafir itu berkata kepada orang-orang yang beriman,) dengan nada yang sinis sebagai ejekan yang ditujukan kepada mereka, (\"Apakah kami akan memberi makanan kepada orang-orang yang jika Allah menghendaki tentulah Dia akan memberinya makan) sesuai dengan keyakinan kalian itu. (Tiada lain kalian) yaitu apa yang kalian katakan kepada kami, padahal kalian mempunyai keyakinan bahwa Allah pasti memberi makan kalian (melainkan dalam kesesatan yang nyata\") yakni jelas sesatnya. Ditegaskannya lafal Al Ladziina Kafaruu mengandung arti yang mendalam.",[["وَإِذَا","Dan apabila"],["قِيلَ","dikatakan"],["لَهُمْ","kepada mereka"],["أَنفِقُوا۟","Infakkanlah"],["مِمَّا","daripada apa"],["رَزَقَكُمُ","(telah) memberi rezeki kepada kamu"],["ٱللَّهُ","Allah"],["قَالَ","Berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لِلَّذِينَ","kepada mereka yang"],["ءَامَنُوٓا۟","beriman"],["أَنُطْعِمُ","Patutkah kita memberi makan"],["مَن","yang"],["لَّوْ","jika"],["يَشَآءُ","Allah menghendaki"],["ٱللَّهُ","Allah menghendaki"],["أَطْعَمَهُۥٓ","Dia akan memberinya makan"],["إِنْ","Tidak"],["أَنتُمْ","(adakah) kamu"],["إِلَّا","kecuali"],["فِى","dalam"],["ضَلَـٰلٍۢ","satu kesilapan"],["مُّبِينٍۢ","yang nyata"]]],"3753":["(Dan mereka berkata, \"Bilakah terjadinya janji ini?) yakni hari berbangkit (jika kalian orang-orang yang benar?\") mengenai apa yang kalian katakan.",[["وَيَقُولُونَ","Dan mereka berkata"],["مَتَىٰ","Bilakah (adalah)"],["هَـٰذَا","ini"],["ٱلْوَعْدُ","janji"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"3754":["Allah berfirman, (\"Mereka tidak menunggu) menanti-nanti (melainkan satu teriakan saja), yaitu tiupan malaikat Israfil yang pertama (yang akan membinasakan mereka ketika mereka sedang bertengkar\") lafal Yakhishshimuuna pada asalnya adalah Yakhtashimuuna, kemudian harakat Ta dipindahkan kepada Kha, lalu Ta diidgamkan kepada Shad. Maksudnya, mereka dalam keadaan lalai dari kedatangan hari kiamat, disebabkan mereka sibuk dalam pertengkaran mereka, jual beli yang mereka lakukan, makan, dan minum serta kesibukan-kesibukan lainnya. Menurut qiraat yang lain lafal Yakhishshimuuna mempunyai Wazan sama dengan lafal Yadhribuuna, artinya sebagian dari mereka bertengkar dengan sebagian yang lain.",[["مَا","Tidak"],["يَنظُرُونَ","mereka menunggu"],["إِلَّا","kecuali"],["صَيْحَةًۭ","teriakan"],["وَٰحِدَةًۭ","satu"],["تَأْخُذُهُمْ","ia akan merampas mereka"],["وَهُمْ","sedangkan mereka"],["يَخِصِّمُونَ","sedang mempertikaikan"]]],"3755":["(Lalu mereka tidak kuasa membuat suatu wasiat pun) tidak dapat berwasiat (dan tidak pula dapat kembali kepada keluarganya) dari pasar dan dari tempat-tempat kesibukan mereka, semuanya mati di tempatnya masing-masing.",[["فَلَا","Kemudian tidak"],["يَسْتَطِيعُونَ","mereka akan dapat"],["تَوْصِيَةًۭ","(untuk) membuat wasiat"],["وَلَآ","dan bukan"],["إِلَىٰٓ","kepada"],["أَهْلِهِمْ","rakyat mereka"],["يَرْجِعُونَ","mereka (boleh) kembali"]]],"3756":["(Dan ditiuplah sangkakala) yaitu tiupan yang kedua untuk membangkitkan makhluk supaya hidup kembali; jarak antara dua tiupan, yakni tiupan pertama dengan tiupan kedua lamanya empat puluh tahun (maka tiba-tiba mereka) orang-orang yang telah terkubur itu (dari kuburnya) dari tempat mereka dikubur (Keluar dengan segera menuju kepada Rabb mereka) mereka keluar dengan cepat lalu menuju kepada-Nya.",[["وَنُفِخَ","Dan akan ditiup"],["فِى","[dalam]"],["ٱلصُّورِ","sangkakala"],["فَإِذَا","dan lihatlah"],["هُم","mereka"],["مِّنَ","daripada"],["ٱلْأَجْدَاثِ","kubur"],["إِلَىٰ","kepada"],["رَبِّهِمْ","Tuhan mereka"],["يَنسِلُونَ","[mereka] akan bersegera"]]],"3757":["(Mereka berkata) orang-orang kafir di antara manusia, (\"Aduhai!) Ya di sini menunjukkan makna Tanbih (celakalah kami) binasalah kami lafal Wailun adalah Mashdar yang tidak mempunyai Fi'il dari lafalnya. (Siapakah yang membangkitkan kami dari tempat tidur kami -kubur-?\") karena mereka seolah-olah dalam keadaan tidur di antara kedua tiupan itu, maksudnya mereka tidak diazab. (Inilah) kebangkitan ini (yang) telah (dijanjikan yang Maha Pemurah dan benarlah) mengenainya (Rasul-rasul-Nya) mereka mengakui atas kebenaran yang telah dikatakan oleh para rasul, tetapi pengakuan mereka tidak bermanfaat lagi. Menurut pendapat yang lain, bahwa kalimat tersebut dikatakan kepada mereka.",[["قَالُوا۟","Mereka [akan] berkata"],["يَـٰوَيْلَنَا","Wahai celaka kami"],["مَنۢ","Siapa"],["بَعَثَنَا","telah membesarkan kita"],["مِن","daripada"],["مَّرْقَدِنَا ۜ ۗ","tempat tidur kami"],["هَـٰذَا","ini (ialah)"],["مَا","Apa"],["وَعَدَ","(telah) berjanji"],["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"],["وَصَدَقَ","dan mengatakan (yang) kebenaran"],["ٱلْمُرْسَلُونَ","para Rasul"]]],"3758":["(Tiadalah teriakan itu selain sekali teriakan saja, tiba-tiba mereka semua kepada Kami) di hadapan Kami (dikumpulkan.)",[["إِن","Tidak"],["كَانَتْ","ia akan menjadi"],["إِلَّا","tetapi"],["صَيْحَةًۭ","teriakan"],["وَٰحِدَةًۭ","bujang"],["فَإِذَا","jadi lihatlah"],["هُمْ","mereka"],["جَمِيعٌۭ","semua"],["لَّدَيْنَا","sebelum Kami"],["مُحْضَرُونَ","(akan) dibawa"]]],"3759":["(Pada hari itu seseorang tidak akan dirugikan sedikit pun dan kalian tidak dibalasi, kecuali) dengan balasan (apa yang telah kalian kerjakan.)",[["فَٱلْيَوْمَ","Jadi Hari ini"],["لَا","tidak"],["تُظْلَمُ","akan dizalimi"],["نَفْسٌۭ","sebuah jiwa"],["شَيْـًۭٔا","(dalam) apa-apa"],["وَلَا","dan bukan"],["تُجْزَوْنَ","kamu akan mendapat balasan"],["إِلَّا","kecuali"],["مَا","(untuk) apa"],["كُنتُمْ","kamu pernah (untuk)"],["تَعْمَلُونَ","lakukan"]]],"3760":["(Sesungguhnya penghuni surga pada hari itu dalam kesibukan) mereka tidak menghiraukan lagi apa yang dialami oleh ahli neraka, karena mereka sibuk dengan kenikmatan-kenikmatan yang sedang mereka rasakan, seperti memecahkan selaput dara bidadari-bidadari; mereka tidak mempunyai kesibukan yang membuat mereka lelah atau payah, karena di dalam surga tidak ada kelelahan. Lafal Syughulin dapat pula dibaca Syughlin (bersenang-senang) yakni bergelimangan di dalam kenikmatan. Lafal Faakihuuna menjadi Khabar kedua dari Inna, sedangkan Khabar yang pertama adalah Fii Syughulin.",[["إِنَّ","Sesungguhnya"],["أَصْحَـٰبَ","(para) sahabat"],["ٱلْجَنَّةِ","(dari) Syurga"],["ٱلْيَوْمَ","Hari ini"],["فِى","[dalam]"],["شُغُلٍۢ","akan diduduki"],["فَـٰكِهُونَ","(dalam) hiburan"]]],"3761":["(Mereka) lafal Hum menjadi Mubtada (dan istri-istri mereka berada dalam tempat yang teduh) lafal Zhilaalun ini adalah bentuk jamak dari lafal Zhillun atau Zhillatun; menjadi Khabar Mubtada; arti Zhillun adalah tidak terkena panas matahari maksudnya teduh. (Di atas dipan-dipan) lafal Araa-iki adalah bentuk jamak dari lafal Ariikah, adalah ranjang atau permadani yang tebal (mereka bersandaran) bertelekan di atas dipan-dipan; lafal ayat ini menjadi Khabar kedua dan menjadi tempat berta'alluqnya Alal Araaa-iki.",[["هُمْ","mereka"],["وَأَزْوَٰجُهُمْ","dan pasangan mereka"],["فِى","dalam"],["ظِلَـٰلٍ","warna"],["عَلَى","pada"],["ٱلْأَرَآئِكِ","[the] sofa"],["مُتَّكِـُٔونَ","berbaring"]]],"3762":["(Di surga itu mereka memperoleh buah-buahan dan mereka memperoleh pula) di dalamnya (apa yang mereka minta) apa yang mereka dambakan.",[["لَهُمْ","Untuk mereka"],["فِيهَا","di dalamnya"],["فَـٰكِهَةٌۭ","(adalah) buah-buahan"],["وَلَهُم","dan untuk mereka"],["مَّا","(adalah) apa sahaja"],["يَدَّعُونَ","mereka menyeru"]]],"3763":["(Kepada mereka dikatakan, \"Salaam\") kedudukan kalimat ini menjadi Mubtada (sebagai ucapan selamat) yang menjadi Khabarnya ialah (dari Rabb Yang Maha Penyayang) kepada mereka, yakni Dia mengucapkan kepada mereka, \"Kesejahteraan atas kalian.\"",[["سَلَـٰمٌۭ","Damai"],["قَوْلًۭا","Satu perkataan"],["مِّن","daripada"],["رَّبٍّۢ","seorang Tuhan"],["رَّحِيمٍۢ","Maha Mengasihani"]]],"3764":["(Dan) Dia berfirman pula, (\"Berpisahlah kalian dan orang-orang mukmin pada hari ini hai orang-orang yang berbuat jahat) mereka diperintahkan supaya berpisah di kala mereka bercampur dengan orang-orang mukmin.",[["وَٱمْتَـٰزُوا۟","Tetapi berdiri berasingan"],["ٱلْيَوْمَ","hari ini"],["أَيُّهَا","Wahai penjenayah"],["ٱلْمُجْرِمُونَ","Wahai penjenayah"]]],"3765":["(Bukankah Aku telah memerintahkan kepada kalian hai Bani Adam) melalui lisan Rasul-rasul-Ku (supaya kalian tidak menyembah setan) jangan menaatinya. (Sesungguhnya setan itu adalah musuh yang nyata bagi kalian\") yakni jelas permusuhannya.",[["۞ أَلَمْ","tidak"],["أَعْهَدْ","aku suruh"],["إِلَيْكُمْ","ke atas kamu"],["يَـٰبَنِىٓ","Wahai Bani Adam"],["ءَادَمَ","Wahai Bani Adam"],["أَن","Itu"],["لَّا","jangan"],["تَعْبُدُوا۟","ibadah"],["ٱلشَّيْطَـٰنَ ۖ","syaitan"],["إِنَّهُۥ","memang dia"],["لَكُمْ","(adalah) untuk kamu"],["عَدُوٌّۭ","seorang musuh"],["مُّبِينٌۭ","yang nyata"]]],"3766":["(Dan hendaklah kalian menyembah-Ku) yakni esakanlah Aku dan taatilah Aku. (Inilah jalan) maksudnya tuntunan (yang lurus.)",[["وَأَنِ","Dan bahawa"],["ٱعْبُدُونِى ۚ","kamu menyembah Aku"],["هَـٰذَا","Ini"],["صِرَٰطٌۭ","(adalah) Jalan"],["مُّسْتَقِيمٌۭ","Lurus"]]],"3767":["(Sesungguhnya setan itu telah menyesatkan sebagian besar di antara kalian) lafal Jibillan adalah bentuk jamak dari Jabiilun seperti wazan Qadiimun, artinya makhluk. Menurut qiraat yang lain dibaca Jibullan dengan harakat Dhammah pada huruf Ba. (Maka apakah kalian tidak memikirkan?) tentang permusuhan setan dan penyesatannya; atau azab yang bakal menimpa mereka, yang karenanya mereka lalu mau beriman. Dikatakan kepada mereka di akhirat nanti:",[["وَلَقَدْ","Dan sesungguhnya"],["أَضَلَّ","dia menyesatkan"],["مِنكُمْ","daripada kamu"],["جِبِلًّۭا","beramai-ramai"],["كَثِيرًا ۖ","yang besar"],["أَفَلَمْ","Kemudian tidak"],["تَكُونُوا۟","kamu"],["تَعْقِلُونَ","guna akal"]]],"3768":["(Inilah Jahanam yang kalian dahulu diancam) dengannya.",[["هَـٰذِهِۦ","ini (ialah)"],["جَهَنَّمُ","(the) Neraka"],["ٱلَّتِى","yang"],["كُنتُمْ","kamu dahulu"],["تُوعَدُونَ","dijanjikan"]]],"3769":["(Masuklah ke dalamnya pada hari ini disebabkan kalian dahulu mengingkarinya.)",[["ٱصْلَوْهَا","Bakar di dalamnya"],["ٱلْيَوْمَ","hari ini"],["بِمَا","kerana"],["كُنتُمْ","kamu pernah"],["تَكْفُرُونَ","kufur"]]],"3770":["(Pada hari ini Kami tutup mulut mereka) mulut orang-orang kafir, karena mereka mengatakan, yaitu sebagaimana yang disitir oleh firman-Nya, \"Demi Allah, Rabb kami, tiadalah kami mempersekutukan Allah.\" (Q.S. 6 Al An'am, 23) (Dan berkatalah kepada Kami tangan mereka dan kaki mereka memberi kesaksian) juga anggota-anggota mereka lainnya (terhadap apa yang dahulu mereka kerjakan) setiap anggota tubuh mengucapkan apa yang telah diperbuatnya.",[["ٱلْيَوْمَ","Hari ini"],["نَخْتِمُ","Kami akan mengelak"],["عَلَىٰٓ","[pada]"],["أَفْوَٰهِهِمْ","mulut mereka"],["وَتُكَلِّمُنَآ","dan akan bercakap dengan Kami"],["أَيْدِيهِمْ","tangan mereka"],["وَتَشْهَدُ","dan akan menjadi saksi"],["أَرْجُلُهُم","kaki mereka"],["بِمَا","tentang apa"],["كَانُوا۟","mereka dahulu"],["يَكْسِبُونَ","peroleh"]]],"3771":["(Dan jika Kami menghendaki pastilah Kami hapuskan penglihatan mereka) Kami jadikan penglihatan mereka buta sama sekali (lalu mereka berlomba-lomba) bersegera (-mencari- jalan) untuk pergi sebagaimana kebiasaan mereka. (Maka betapakah) bagaimanakah (mereka dapat melihat) jalan itu, jika mereka dalam keadaan buta? Yakni mereka pasti tidak akan dapat melihat jalan itu.",[["وَلَوْ","Dan jika"],["نَشَآءُ","Kami berkehendak"],["لَطَمَسْنَا","Kami (akan) pasti melenyapkan"],["عَلَىٰٓ","[lebih]"],["أَعْيُنِهِمْ","mata mereka"],["فَٱسْتَبَقُوا۟","kemudian mereka (akan) berlumba-lumba"],["ٱلصِّرَٰطَ","(untuk mencari) jalan"],["فَأَنَّىٰ","kemudian bagaimana"],["يُبْصِرُونَ","(boleh) mereka melihat"]]],"3772":["(Dan jika Kami menghendaki pastilah Kami ubah mereka) diubah menjadi kera, babi atau batu (di tempat mereka berada) menurut qiraat yang lain lafal Makanatihim dibaca dalam bentuk jamak, yaitu Makaanaatihim, yaitu di tempat-tempat mereka (maka mereka tidak sanggup berjalan dan tidak pula sanggup kembali) yakni mereka tidak dapat pergi dan tidak dapat pulang kembali.",[["وَلَوْ","Dan jika"],["نَشَآءُ","Kami berkehendak"],["لَمَسَخْنَـٰهُمْ","sesungguhnya Kami (akan) mengubah mereka"],["عَلَىٰ","dalam"],["مَكَانَتِهِمْ","tempat mereka"],["فَمَا","maka tidak"],["ٱسْتَطَـٰعُوا۟","mereka akan dapat"],["مُضِيًّۭا","untuk meneruskan"],["وَلَا","dan bukan"],["يَرْجِعُونَ","kembali"]]],"3773":["(Dan barang siapa yang Kami panjangkan umurnya) yaitu diperpanjang ajalnya (niscaya dia Kami kembalikan) menurut qiraat yang lain tidak dibaca Nunakkis-hu melainkan Nunkis-hu yang berasal dari Mashdar At-Tankiis, yakni mengembalikannya (kepada kejadiannya) sehingga setelah ia kuat dan muda lalu menjadi tua dan lemah kembali. (Maka apakah mereka tidak memikirkan?) bahwasanya Dzat Yang Maha Kuasa memperbuat demikian, berkuasa pula untuk membangkitkan hidup kembali, oleh karenanya mereka lalu mau beriman kepada-Nya. Menurut qiraat yang lain lafal Ya'qiluuna dibaca Ta'qiluuna dengan memakai huruf Ta.",[["وَمَن","Dan (dia) siapa"],["نُّعَمِّرْهُ","Kami panjangkan umurnya"],["نُنَكِّسْهُ","Kita songsang dia"],["فِى","dalam"],["ٱلْخَلْقِ ۖ","penciptaan"],["أَفَلَا","Kemudian tidak akan"],["يَعْقِلُونَ","mereka menggunakan akal"]]],"3774":["(Dan Kami tidak mengajarkan kepadanya) yakni kepada Nabi saw. (tentang syair) ayat ini diturunkan sebagai sanggahan terhadap perkataan orang-orang kafir, karena mereka telah mengatakan, bahwa sesungguhnya Alquran yang didatangkan olehnya adalah syair (dan bersyair itu tidak layak) tidak mudah (baginya.) (Alquran itu tiada lain) apa yang diturunkan kepadanya, tiada lain (hanyalah pelajaran) nasihat (dan Kitab yang memberi penerangan) yang menjelaskan tentang hukum-hukum dan lain-lainnya.",[["وَمَا","Dan tidak"],["عَلَّمْنَـٰهُ","Kami mengajarnya"],["ٱلشِّعْرَ","[the] puisi"],["وَمَا","dan bukan"],["يَنۢبَغِى","memang sesuai"],["لَهُۥٓ ۚ","baginya"],["إِنْ","Tidak"],["هُوَ","ia"],["إِلَّا","(adalah) kecuali"],["ذِكْرٌۭ","satu Peringatan"],["وَقُرْءَانٌۭ","dan Al-Quran"],["مُّبِينٌۭ","yang nyata"]]],"3775":["(Supaya dia memberi peringatan) dengan Alquran itu; lafal Liyundzira dapat pula dibaca Litundzira artinya supaya kamu memberi peringatan dengan Alquran itu (kepada orang-orang yang hidup) hatinya, maksudnya tanggap terhadap apa-apa yang dinasihatkan kepada mereka; mereka adalah orang-orang mukmin (dan supaya pastilah ketetapan) azab (terhadap orang-orang kafir) mereka diserupakan orang mati, karena mereka tidak tanggap terhadap apa-apa yang dinasihatkan kepada mereka.",[["لِّيُنذِرَ","Untuk memberi amaran"],["مَن","(dia) siapa"],["كَانَ","ialah"],["حَيًّۭا","hidup"],["وَيَحِقَّ","dan boleh dibuktikan kebenarannya"],["ٱلْقَوْلُ","Firman"],["عَلَى","terhadap"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"3776":["(Dan apakah mereka tidak melihat) tidak memperhatikan, Istifham di sini mengandung makna Taqrir dan huruf Wau yang masuk kepadanya merupakan huruf 'Athaf (bahwa Kami telah menciptakan untuk mereka) ini ditujukan kepada segolongan manusia (dari apa yang telah Kami ciptakan dengan kekuasaan Kami) dari hasil ciptaan Kami tanpa sekutu dan tanpa pembantu (yaitu berupa binatang ternak) unta, sapi, dan kambing lalu mereka menguasainya?) dapat memeliharanya.",[["أَوَلَمْ","Jangan"],["يَرَوْا۟","mereka lihat"],["أَنَّا","bahawa Kami"],["خَلَقْنَا","[Kami] mencipta"],["لَهُم","bagi mereka"],["مِّمَّا","daripada apa"],["عَمِلَتْ","telah membuat"],["أَيْدِينَآ","tangan kita"],["أَنْعَـٰمًۭا","lembu"],["فَهُمْ","kemudian mereka"],["لَهَا","[untuk mereka]"],["مَـٰلِكُونَ","(adalah) pemilik"]]],"3777":["(Dan Kami tundukkan binatang-binatang itu) Kami jadikan mereka tunduk (untuk mereka; maka sebagiannya menjadi tunggangan mereka) menjadi kendaraan mereka (dan sebagiannya mereka makan.)",[["وَذَلَّلْنَـٰهَا","Dan Kami telah menjinakkan mereka"],["لَهُمْ","bagi mereka"],["فَمِنْهَا","jadi sebahagian daripada mereka"],["رَكُوبُهُمْ","mereka menunggang mereka"],["وَمِنْهَا","dan sebahagian daripada mereka"],["يَأْكُلُونَ","mereka makan"]]],"3778":["(Dan mereka memperoleh padanya manfaat-manfaat) yakni dari bulu unta, kambing, dan dombanya (dan minuman) dari air susunya, lafal Masyaarib adalah bentuk jamak dari lafal Masyrab yang bermakna Asy-Syurb atau minuman, makna yang dimaksud adalah tempat minum. (Maka mengapakah mereka tidak bersyukur?) kepada Allah Yang telah melimpahkan nikmat-nikmat itu kepada mereka, lalu karenanya mereka mau beriman. Makna yang dimaksud ialah mereka tidak mensyukurinya.",[["وَلَهُمْ","Dan untuk mereka"],["فِيهَا","di dalamnya"],["مَنَـٰفِعُ","(adalah) faedah"],["وَمَشَارِبُ ۖ","dan minuman"],["أَفَلَا","jadi (akan) tidak"],["يَشْكُرُونَ","mereka mengucapkan terima kasih"]]],"3779":["(Mereka mengambil selain Allah) selain-Nya (sebagai sesembahan-sesembahan) berhala-berhala yang mereka sembah (agar mereka mendapat pertolongan) terhindar dari azab Allah, karena mendapat syafaat dari tuhan-tuhan sesembahan mereka itu, ini menurut dugaan mereka sendiri.",[["وَٱتَّخَذُوا۟","Tetapi mereka telah mengambil"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["ءَالِهَةًۭ","tuhan"],["لَّعَلَّهُمْ","supaya mereka boleh"],["يُنصَرُونَ","dibantu"]]],"3780":["(Berhala-berhala itu tidak akan dapat) yakni sesembahan-sesembahan mereka itu tidak dapat menolong. Ungkapan kata berhala memakai jamak untuk orang yang berakal hanyalah sebagai kata kiasan saja, yakni mereka dianggap sebagai makhluk yang berakal (menolong mereka padahal berhala-berhala itu) sesembahan-sesembahan mereka itu (menjadi tentara mereka) menurut dugaan mereka, yaitu tentara yang siap menolong mereka (yang disiapkan) di dalam neraka bersama mereka.",[["لَا","Tidak"],["يَسْتَطِيعُونَ","mereka mampu"],["نَصْرَهُمْ","untuk membantu mereka"],["وَهُمْ","tetapi mereka"],["لَهُمْ","bagi mereka"],["جُندٌۭ","(adalah) tuan rumah"],["مُّحْضَرُونَ","(yang akan) dibawa"]]],"3781":["(Maka janganlah ucapan mereka menyedihkan kamu) seperti ucapan, bahwa kamu bukanlah seseorang yang diutus oleh Allah dan ucapan-ucapan lainnya. (Sesungguhnya Kami mengetahui apa yang mereka rahasiakan dan apa yang mereka nyatakan) dari perkataan-perkataan semacam itu dan yang lainnya, kelak Kami akan membalasnya kepada mereka.",[["فَلَا","Jadi (biar) jangan"],["يَحْزُنكَ","menyedihkan kamu"],["قَوْلُهُمْ ۘ","ucapan mereka"],["إِنَّا","Sesungguhnya Kami"],["نَعْلَمُ","[Kami] tahu"],["مَا","apa"],["يُسِرُّونَ","mereka sembunyikan"],["وَمَا","dan apa"],["يُعْلِنُونَ","mereka mengisytiharkan"]]],"3782":["(Apakah manusia tidak memperhatikan) apakah ia tidak mengetahui, orang yang dimaksud adalah Ashi bin Wail (bahwa Kami menciptakannya dari setitik air) yakni air mani, hingga Kami jadikan ia besar dan kuat (maka tiba-tiba ia menjadi penentang) yakni sangat memusuhi Kami (yang nyata) jelas menentangnya, tidak mau percaya kepada adanya hari berbangkit.",[["أَوَلَمْ","tidak"],["يَرَ","lihat"],["ٱلْإِنسَـٰنُ","lelaki itu"],["أَنَّا","bahawa Kami"],["خَلَقْنَـٰهُ","[Kami] menciptakan dia"],["مِن","daripada"],["نُّطْفَةٍۢ","titisan air mani"],["فَإِذَا","Kemudian lihatlah"],["هُوَ","Dia"],["خَصِيمٌۭ","(adalah) lawan"],["مُّبِينٌۭ","yang nyata"]]],"3783":["(Dia membuat perumpamaan bagi Kami) mengenai hal tersebut (dan dia lupa kepada kejadiannya) berasal dari air mani, dan terlebih lagi ia lupa kepada hal-hal yang selain itu (ia berkata, \"Siapakah yang dapat menghidupkan tulang-belulang yang telah hancur luluh?\") hancur berantakan, di dalam ungkapan ini tidak dikatakan Ramiimatun, karena isim bukan sifat. Menurut suatu riwayat dikisahkan bahwa Ashi bin Wail mengambil sebuah tulang yang telah hancur, kemudian ia cerai-beraikan tulang itu di hadapan Nabi saw. seraya berkata, \"Apakah kamu berpendapat, bahwa Allah nanti akan menghidupkan kembali tulang ini sesudah hancur luluh dan berantakan ini?\" Maka Nabi saw. menjawab, \"Ya, Dia akan memasukkanmu ke neraka.\"",[["وَضَرَبَ","Dan dia menetapkan"],["لَنَا","untuk Kami"],["مَثَلًۭا","satu contoh"],["وَنَسِىَ","dan lupa"],["خَلْقَهُۥ ۖ","ciptaannya (sendiri)."],["قَالَ","Dia berkata"],["مَن","Siapa"],["يُحْىِ","akan memberi kehidupan"],["ٱلْعِظَـٰمَ","(kepada) tulang"],["وَهِىَ","sedangkan mereka"],["رَمِيمٌۭ","(sedang) reput"]]],"3784":["(Katakanlah! \"Ia akan dihidupkan oleh Tuhan yang menciptakannya yang pertama kali. Dan Dia tentang segala makhluk) semua yang diciptakan-Nya (Maha Mengetahui) secara global dan rinci, baik sebelum mereka diciptakan maupun sesudahnya.",[["قُلْ","Katakanlah"],["يُحْيِيهَا","Dia akan memberi mereka kehidupan"],["ٱلَّذِىٓ","Siapa"],["أَنشَأَهَآ","menghasilkan mereka"],["أَوَّلَ","(yang) pertama"],["مَرَّةٍۢ ۖ","masa"],["وَهُوَ","dan Dia"],["بِكُلِّ","(adalah) setiap"],["خَلْقٍ","ciptaan"],["عَلِيمٌ","Maha Mengetahui"]]],"3785":["(Yaitu Tuhan yang menjadikan untuk kalian) yakni segolongan umat manusia (dari kayu yang hijau) yakni kayu pohon Marakh dan Affar atau semua jenis pohon selain pohon anggur (api, maka tiba-tiba kalian nyalakan -api- dari kayu itu.\") kalian membuat api daripadanya. Hal ini menunjukkan kekuasaan Allah swt. yang mampu untuk menghidupkan kembali manusia yang mati. Karena sesungguhnya di dalam kayu yang hijau itu terhimpun antara air, api, dan kayu; maka air tidak dapat memadamkan api, dan pula api tidak dapat membakar kayu.",[["ٱلَّذِى","Dia yang"],["جَعَلَ","dibuat"],["لَكُم","bagi kamu"],["مِّنَ","daripada"],["ٱلشَّجَرِ","pokok itu"],["ٱلْأَخْضَرِ","[yang] hijau"],["نَارًۭا","kebakaran"],["فَإِذَآ","dan lihatlah"],["أَنتُم","kamu"],["مِّنْهُ","daripadanya"],["تُوقِدُونَ","menyala"]]],"3786":["(Dan tidakkah Tuhan yang menciptakan langit dan bumi itu) padahal langit dan bumi itu sangat besar (berkuasa menciptakan yang serupa dengan itu) yaitu manusia yang kecil bentuknya itu. (Benar) Dia berkuasa untuk menciptakannya, di sini Allah swt. menjawab diri-Nya sendiri. (Dan Dialah Maha Pencipta) banyak ciptaan-Nya (lagi Maha Mengetahui) segala sesuatu.",[["أَوَلَيْسَ","Bukankah"],["ٱلَّذِى","(Dia) Siapa"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["بِقَـٰدِرٍ","mampu"],["عَلَىٰٓ","kepada"],["أَن","[bahawa]"],["يَخْلُقَ","cipta"],["مِثْلَهُم ۚ","(yang) seperti mereka"],["بَلَىٰ","Ya, memang"],["وَهُوَ","dan Dia"],["ٱلْخَلَّـٰقُ","(ialah) Maha Pencipta"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"3787":["(Sesungguhnya perkara-Nya) keadaan-Nya (apabila Dia menghendaki sesuatu) yakni berkehendak menciptakan sesuatu (hanyalah berkata kepadanya, \"Jadilah,\" maka terjadilah ia) berujudlah sesuatu itu. Menurut qiraat yang lain lafal Fayakuunu dibaca Fayakuna karena diathafkan kepada lafal Yaquula.",[["إِنَّمَآ","Hanya"],["أَمْرُهُۥٓ","PerintahNya"],["إِذَآ","apabila"],["أَرَادَ","Dia berniat"],["شَيْـًٔا","sesuatu perkara"],["أَن","bahawa"],["يَقُولَ","Dia berkata"],["لَهُۥ","kepadanya"],["كُن","Jadilah"],["فَيَكُونُ","dan ia adalah"]]],"3788":["(Maka Maha Suci Allah Yang dalam genggaman-Nya kekuasaan) lafal Malakuutu pada asalnya adalah Mulki kemudian ditambahkan huruf Wawu dan Ta untuk menunjukkan makna mubalaghah, artinya kekuasaan atas (segala sesuatu dan kepada-Nyalah kalian dikembalikan) kelak di akhirat.",[["فَسُبْحَـٰنَ","Jadi kemuliaan"],["ٱلَّذِى","(kepada) Dia yang"],["بِيَدِهِۦ","di tangan Siapa"],["مَلَكُوتُ","adalah (kekuasaan)."],["كُلِّ","(dari) semua"],["شَىْءٍۢ","benda"],["وَإِلَيْهِ","dan kepada-Nya"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"3789":["(Demi yang bersaf-saf dengan sebenar-benarnya) yaitu para malaikat yang berbaris membentuk saf-saf dalam menyembah Allah, atau para malaikat yang sayap-sayapnya bersaf-saf membentuk barisan di udara sambil menunggu apa yang diperintahkan kepada mereka.",[["وَٱلصَّـٰٓفَّـٰتِ","Oleh mereka yang berbaris"],["صَفًّۭا","(dalam) baris"]]],"3790":["(Dan demi rombongan yang menggiring dengan sebenar-benarnya) demi para malaikat yang menggiring atau mengarak awan.",[["فَٱلزَّٰجِرَٰتِ","Dan mereka yang memandu"],["زَجْرًۭا","dengan kuat"]]],"3791":["(Dan demi rombongan yang membacakan) maksudnya para pembaca Alquran yang sedang membacakannya sebagai (peringatan) lafal Dzikran menjadi Mashdar dari makna Fi'il At-Taaliyaat. Maksudnya, demi para qari yang membacakan peringatan atau Alquran.",[["فَٱلتَّـٰلِيَـٰتِ","Dan mereka yang mengaji"],["ذِكْرًا","(the) Mesej"]]],"3792":["(Sesungguhnya Tuhan kalian) hai penduduk Mekah (benar-benar Esa.)",[["إِنَّ","Sesungguhnya"],["إِلَـٰهَكُمْ","Tuhanmu"],["لَوَٰحِدٌۭ","(adalah) pasti Satu"]]],"3793":["(Tuhan langit dan bumi dan apa yang berada di antara keduanya dan Tuhan tempat-tempat terbit matahari) dan tempat-tempat terbenamnya pada setiap harinya, yaitu arah Timur dan arah Barat.",[["رَّبُّ","Tuhan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَمَا","dan apa"],["بَيْنَهُمَا","(adalah) antara keduanya"],["وَرَبُّ","dan Tuhan"],["ٱلْمَشَـٰرِقِ","(dari) setiap titik matahari terbit"]]],"3794":["(Sesungguhnya Kami telah menghias langit yang terdekat dengan hiasan, yaitu bintang-bintang) dengan cahayanya, atau hiasan itu berupa bintang-bintang itu sendiri. Pengertian Idhafah di sini mengandung makna bayan atau menjelaskan, perihalnya sama dengan makna qiraat yang menanwinkannya.",[["إِنَّا","Sesungguhnya Kami"],["زَيَّنَّا","[Kami] berhias"],["ٱلسَّمَآءَ","langit"],["ٱلدُّنْيَا","[dunia]"],["بِزِينَةٍ","dengan perhiasan"],["ٱلْكَوَاكِبِ","(dari) bintang"]]],"3795":["(Dan sebagai pemelihara) lafal Hifzhan dinashabkan oleh Fi'il yang diperkirakan keberadaannya pada sebelumnya, yakni Kami memelihara langit dengan bintang-bintang atau meteor-meteor (dari setiap) lafal ayat ini berta'alluq kepada Fi'il yang diperkirakan keberadaannya (setan yang durhaka) setan yang membangkang atau tidak mau taat.",[["وَحِفْظًۭا","Dan (untuk) menjaga"],["مِّن","terhadap"],["كُلِّ","setiap"],["شَيْطَـٰنٍۢ","syaitan"],["مَّارِدٍۢ","memberontak"]]],"3796":["(Mereka tidak dapat mendengar-dengarkan) maksudnya setan-setan itu tidak dapat mendengar-dengarkan apa yang telah dipelihara oleh-Nya. Lafal ayat ini merupakan jumlah Isti'naf (pembicaraan para malaikat) yang berada di langit. Lafal Yasma'uuna dimuta'addikan dengan huruf Ilaa karena pengertiannya mengandung makna seperti apa yang terdapat di dalam lafal Al-Ishghaa. Menurut suatu qiraat dibaca La Yassamma'uuna dengan memakai Tasydid pada huruf Mim dan Sin-nya, berasal dari lafal Yatasamma'uuna, kemudian huruf Ta diidgamkan kepada huruf Sin, sehingga jadilah Yassamma'uuna (Dan mereka dilempari) yakni setan-setan itu dengan meteor-meteor (dari segala penjuru) langit.",[["لَّا","Tidak"],["يَسَّمَّعُونَ","mereka mungkin mendengar"],["إِلَى","kepada"],["ٱلْمَلَإِ","perhimpunan itu"],["ٱلْأَعْلَىٰ","[yang] ditinggikan"],["وَيُقْذَفُونَ","dibaling"],["مِن","daripada"],["كُلِّ","setiap"],["جَانِبٍۢ","sebelah"]]],"3797":["(Untuk mengusir mereka) lafal Duhuuran bentuk Mashdar dari lafal Daharahu, artinya dia mengusir mereka dan menjauhkan mereka, juga menjadi Maf'ul Lah (dan bagi mereka) di akhirat kelak (azab yang kekal) yang abadi.",[["دُحُورًۭا ۖ","Ditolak"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌۭ","(ialah) azab"],["وَاصِبٌ","berkekalan"]]],"3798":["(Terkecuali setan yang mencuri-curi -pembicaraan malaikat- dengan sekali curi) lafal Al-Khathfah adalah Mashdar Marrah dan yang diistitsnakan atau yang dikecualikan adalah dhamir yang terkandung di dalam lafal Laa Yasma'uuna. Maksudnya, tiada yang dapat mendengarkan pembicaraan para malaikat kecuali hanya setan yang dapat mencuri-curinya dengan cepat (maka ia dikejar oleh meteor) yakni bintang yang bercahaya (yang melubanginya) yang menembus tubuh setan-setan itu, atau membakarnya, atau membuatnya cacat.",[["إِلَّا","Kecuali"],["مَنْ","(dia) siapa"],["خَطِفَ","ragut"],["ٱلْخَطْفَةَ","(oleh) kecurian"],["فَأَتْبَعَهُۥ","tetapi mengikut dia"],["شِهَابٌۭ","api yang menyala"],["ثَاقِبٌۭ","menindik"]]],"3799":["(Maka tanyakanlah kepada mereka) kepada orang-orang kafir Mekah, kalimat ayat ini mengandung makna Taqrir atau Taubikh, yakni mengandung nada menetapkan atau celaan, (\"Apakah mereka yang lebih kukuh kejadiannya ataukah yang telah Kami ciptakan itu?\") yakni para malaikat, langit, bumi dan semua apa yang ada di antara keduanya. Didatangkannya lafal Man mengandung pengertian memprioritaskan makhluk yang berakal. (Sesungguhnya Kami telah menciptakan mereka) asal mereka, yaitu Nabi Adam (dan tanah liat) tanah yang melekat di tangan bilamana dipegang. Maksudnya, kejadian mereka adalah dari sesuatu yang lemah, karena itu janganlah mereka bersikap takabur dan sombong, yakni mengingkari Nabi saw. dan Alquran, yang hal ini dengan mudah dapat mengakibatkan mereka terjerumus ke dalam jurang kebinasaan.",[["فَٱسْتَفْتِهِمْ","Kemudian tanya mereka"],["أَهُمْ","Adakah mereka"],["أَشَدُّ","yang lebih kuat"],["خَلْقًا","ciptaan"],["أَم","atau"],["مَّنْ","(mereka) siapa"],["خَلَقْنَآ ۚ","Kami telah mencipta"],["إِنَّا","Sesungguhnya Kami"],["خَلَقْنَـٰهُم","mencipta mereka"],["مِّن","daripada"],["طِينٍۢ","tanah liat"],["لَّازِبٍۭ","melekit"]]],"3800":["(Bahkan) lafal Bal di sini menunjukkan arti Intiqal, yakni perpindahan dari suatu topik pembicaraan kepada pembicaraan yang lain, yaitu pembahasan mengenai keadaan Nabi Muhammad dan orang-orang kafir Mekah (kamu heran) pembicaraan ayat ini ditujukan kepada Nabi saw. yakni kamu heran akan keingkaran mereka terhadapmu (dan) mereka (menghinakan kamu) karena keherananmu itu.",[["بَلْ","Bahkan"],["عَجِبْتَ","kamu tertanya-tanya"],["وَيَسْخَرُونَ","sambil mereka mengejek"]]],"3801":["(Dan apabila mereka diberi pelajaran) maksudnya, dinasihati dengan ayat-ayat Alquran (mereka tiada mengingatinya) mereka tidak menjadikannya sebagai pelajaran.",[["وَإِذَا","Dan apabila"],["ذُكِّرُوا۟","mereka diingatkan"],["لَا","tidak"],["يَذْكُرُونَ","mereka menerima teguran"]]],"3802":["(Dan apabila mereka melihat sesuatu tanda kebesaran Allah) seperti terbelahnya bulan (mereka sangat menghinakan) mereka menghina dan mengejeknya.",[["وَإِذَا","Dan apabila"],["رَأَوْا۟","mereka lihat"],["ءَايَةًۭ","sebuah Tanda"],["يَسْتَسْخِرُونَ","mereka mengejek"]]],"3803":["(Dan mereka berkata) sehubungan dengan adanya tanda kebesaran Allah itu, (\"Tiada lain) tidak lain (ini hanyalah sihir yang nyata\") jelas sihirnya. Kemudian mereka berkata seraya mengingkari adanya hari berbangkit:",[["وَقَالُوٓا۟","Dan mereka berkata"],["إِنْ","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّا","kecuali"],["سِحْرٌۭ","sihir"],["مُّبِينٌ","yang nyata"]]],"3804":["(Apakah apabila kami telah mati dan telah menjadi tanah serta menjadi tulang-belulang, apakah benar-benar kami akan dibangkitkan?) lafal A-idzaa dan A-innaa dapat pula dibaca Tas-hil, sehingga bacaannya menjadi Ayidzaa dan Ayinnaa.",[["أَءِذَا","Adakah apabila"],["مِتْنَا","kita mati"],["وَكُنَّا","dan telah menjadi"],["تُرَابًۭا","habuk"],["وَعِظَـٰمًا","dan tulang"],["أَءِنَّا","adakah kita kemudian"],["لَمَبْعُوثُونَ","pasti dibangkitkan"]]],"3805":["(Dan apakah bapak-bapak kami yang telah dahulu) kalau dibaca Au berarti huruf 'Athaf, jika dibaca Awa, berarti huruf Istifham, Wawu-nya adalah huruf 'Athaf, sedangkan Ma'thuf 'Alaihnya adalah Inna dan Isimnya secara Mahall, atau di'athafkan kepada Dhamir yang terkandung di dalam lafal Lamab'uutsuuna, Hamzah Istifham sebagai pemisahnya. Maksudnya, apakah bapak-bapak kami yang telah dahulu akan dibangkitkan pula?",[["أَوَءَابَآؤُنَا","Atau bapa kita"],["ٱلْأَوَّلُونَ","bekas"]]],"3806":["(Katakanlah kepada mereka, \"Ya) mereka pasti dibangkitkan hidup kembali (dan kalian akan terhina\") kalian akan menjadi orang-orang yang terhina karenanya.",[["قُلْ","Katakanlah"],["نَعَمْ","ya"],["وَأَنتُمْ","dan kamu"],["دَٰخِرُونَ","(akan) dihina"]]],"3807":["(Maka sesungguhnya kebangkitan itu hanyalah dengan) dhamir pada ayat ini bersifat Mubham, kurang jelas, lalu ditafsirkan oleh ayat selanjutnya (suatu teriakan) atau satu hardikan saja (maka tiba-tiba mereka) yakni makhluk semuanya, menjadi hidup kembali seraya (melihat) apa yang dilakukan terhadap diri mereka.",[["فَإِنَّمَا","Kemudian sahaja"],["هِىَ","ia"],["زَجْرَةٌۭ","(akan menjadi) tangisan"],["وَٰحِدَةٌۭ","bujang"],["فَإِذَا","kemudian, lihatlah"],["هُمْ","mereka"],["يَنظُرُونَ","akan melihat"]]],"3808":["(Dan mereka berkata) yakni orang-orang kafir, (\"Aduhai!) lafal Ya di sini menunjukkan makna Tanbih (celakalah kita\") binasalah kita. Lafal Al-Wail merupakan bentuk Mashdar yang tidak mempunyai kata kerja dari lafalnya sendiri. Kemudian para malaikat berkata kepada orang-orang kafir itu. (Inilah hari pembalasan) hari penghisaban amal perbuatan dan pembalasannya.",[["وَقَالُوا۟","Dan mereka akan berkata"],["يَـٰوَيْلَنَا","Wahai celaka kami"],["هَـٰذَا","Ini"],["يَوْمُ","(ialah) Hari"],["ٱلدِّينِ","(dari) Balasan"]]],"3809":["(Inilah hari keputusan) di antara para makhluk semuanya (yang kalian selalu mendustakannya.)",[["هَـٰذَا","Ini"],["يَوْمُ","(ialah) Hari"],["ٱلْفَصْلِ","(dari) Penghakiman"],["ٱلَّذِى","yang"],["كُنتُم","kamu pernah"],["بِهِۦ","[daripadanya]"],["تُكَذِّبُونَ","menafikan"]]],"3810":["Kemudian diperintahkan kepada para malaikat itu, (\"Kumpulkanlah orang-rang yang zalim) yaitu orang-orang yang berbuat aniaya terhadap diri mereka sendiri karena mereka telah berbuat kemusyrikan (beserta teman sejawat mereka) teman-teman karib mereka, yaitu setan-setan (dan sesembahan-sesembahan yang selalu mereka sembah.)",[["۞ ٱحْشُرُوا۟","berkumpul"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","dizalimi"],["وَأَزْوَٰجَهُمْ","dan jenis mereka"],["وَمَا","dan apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَعْبُدُونَ","ibadah"]]],"3811":["(Selain Allah) yaitu berhala-berhala (maka tunjukkanlah kepada mereka) dan giringlah mereka (ke jalan jahim) atau jalan ke neraka.",[["مِن","Selain itu"],["دُونِ","Selain itu"],["ٱللَّهِ","Allah"],["فَٱهْدُوهُمْ","kemudian pimpin mereka"],["إِلَىٰ","kepada"],["صِرَٰطِ","(the) Jalan"],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"3812":["(Dan tahanlah mereka) di tempat perhentian atau Ash-Shirat (karena sesungguhnya mereka akan ditanya\") mengenai semua perkataan dan perbuatan mereka.",[["وَقِفُوهُمْ ۖ","Dan hentikan mereka"],["إِنَّهُم","sesungguhnya, mereka"],["مَّسْـُٔولُونَ","(ada) untuk disoal siasat"]]],"3813":["Dikatakan kepada mereka dengan nada yang mengandung penghinaan dan cemoohan, (\"Kenapa kalian tidak tolong-menolong\") maksudnya mengapa sebagian di antara kalian tidak menolong kepada sebagian yang lain sebagaimana keadaan kalian waktu di dunia? Dan dikatakan pula kepada mereka:",[["مَا","Apa"],["لَكُمْ","(adalah) untuk kamu"],["لَا","(Kenapa) tidak"],["تَنَاصَرُونَ","kamu membantu antara satu sama lain"]]],"3814":["(\"Bahkan mereka pada hari itu menyerah diri) atau mereka itu tunduk dalam keadaan penuh kehinaan.",[["بَلْ","Bahkan"],["هُمُ","mereka"],["ٱلْيَوْمَ","(pada) hari itu"],["مُسْتَسْلِمُونَ","(akan) menyerah diri"]]],"3815":["(Sebagian dari mereka menghadap kepada sebagian yang lain berbantah-bantahan\") saling cela-mencela dan saling bantah-membantah.",[["وَأَقْبَلَ","Dan akan mendekati"],["بَعْضُهُمْ","sebahagian mereka"],["عَلَىٰ","kepada"],["بَعْضٍۢ","yang lain"],["يَتَسَآءَلُونَ","mempersoalkan antara satu sama lain"]]],"3816":["(Mereka berkata) yaitu sebagian dari pengikut-pengikut mereka berkata kepada para pemimpin mereka, (\"Sesungguhnya kalianlah yang datang kepada kami dari kanan\") maksudnya, dari segi yang kami merasa percaya kepada kalian karena kalian telah bersumpah kepada kami, bahwa kalian adalah orang-orang yang benar, karenanya kami percaya kepada kalian, dan kami mengikuti kalian. Maksudnya sesungguhnya kalian telah menyesatkan kami.",[["قَالُوٓا۟","Mereka akan berkata"],["إِنَّكُمْ","Sesungguhnya kamu"],["كُنتُمْ","[kamu] pernah (untuk)"],["تَأْتُونَنَا","datanglah (kepada) kami"],["عَنِ","daripada"],["ٱلْيَمِينِ","yang betul"]]],"3817":["(Mereka berkata) yakni pemimpin-pemimpin yang diikuti oleh mereka (\"Sebenarnya kalianlah yang tidak beriman\") dan sesungguhnya tidak akan percaya penyesatan yang kami lakukan seandainya kalian adalah orang-orang yang beriman, niscaya kalian akan ingkar terhadap kami.",[["قَالُوا۟","Mereka akan berkata"],["بَل","Bahkan"],["لَّمْ","tidak"],["تَكُونُوا۟","kamu dahulu"],["مُؤْمِنِينَ","orang yang beriman"]]],"3818":["(Dan sekali-kali kami tidak berkuasa terhadap kalian) kami tidak mempunyai kemampuan untuk memaksa kalian mengikuti kami (bahkan kalianlah kaum yang melampaui batas) maksudnya, orang-orang yang sesat seperti kami.",[["وَمَا","Dan tidak"],["كَانَ","adalah"],["لَنَا","bagi kami"],["عَلَيْكُم","atas kamu"],["مِّن","sebarang"],["سُلْطَـٰنٍۭ ۖ","pihak berkuasa"],["بَلْ","Bahkan"],["كُنتُمْ","kamu dahulu"],["قَوْمًۭا","suatu kaum"],["طَـٰغِينَ","melanggar"]]],"3819":["(Maka pastilah) atau tetaplah (atas kita) semua (putusan Rabb kita) yakni azab-Nya, yaitu sebagaimana yang telah diungkapkan-Nya pada ayat yang lain, \"Sesungguhnya Aku akan penuhi neraka Jahanam dengan jin dan manusia bersama-sama.\" (Q.S. As-Sajdah, 13). (sesungguhnya kita) semua (akan merasakan) azab dengan adanya keputusan itu, yang akhirnya membuat mereka berkata:",[["فَحَقَّ","Jadi telah terbukti benar"],["عَلَيْنَا","terhadap kita"],["قَوْلُ","(the) Firman"],["رَبِّنَآ ۖ","(dari) Tuhan kami"],["إِنَّا","sesungguhnya, kita"],["لَذَآئِقُونَ","(akan) pasti rasa"]]],"3820":["(Maka kami telah menyesatkan kalian) sebagai penjelasan dari perkataan mereka yang disitir oleh firman-Nya (sesungguhnya kami adalah orang-orang yang sesat.)",[["فَأَغْوَيْنَـٰكُمْ","Jadi kami menyesatkan kamu"],["إِنَّا","sesungguhnya, kita"],["كُنَّا","adalah"],["غَـٰوِينَ","sesat"]]],"3821":["Allah swt. berfirman, (Maka sesungguhnya mereka pada hari itu) pada hari kiamat (bersama-sama dalam azab) karena mereka bersekutu dalam kesesatan.",[["فَإِنَّهُمْ","Kemudian sesungguhnya, mereka"],["يَوْمَئِذٍۢ","hari itu"],["فِى","dalam"],["ٱلْعَذَابِ","azab"],["مُشْتَرِكُونَ","(akan menjadi) pekongsi"]]],"3822":["(Sesungguhnya demikianlah) artinya, sebagaimana Kami memperlakukan mereka (Kami berbuat terhadap orang-orang yang jahat) selain mereka. Yakni Kami pasti akan mengazab orang yang sesat beserta pengikut-pengikutnya.",[["إِنَّا","Sesungguhnya Kami"],["كَذَٰلِكَ","dengan demikian"],["نَفْعَلُ","Kita berurusan"],["بِٱلْمُجْرِمِينَ","dengan penjenayah"]]],"3823":["(Sesungguhnya mereka) yaitu orang-orang tersebut; dialamatkan kepada mereka karena berdasarkan penjelasan selanjutnya yaitu (dahulu apabila dikatakan kepada mereka, \"Laa Ilaaha Illallaah\") Tiada Tuhan melainkan Allah, (mereka menyombongkan diri.)",[["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوٓا۟","adalah"],["إِذَا","apabila"],["قِيلَ","ia dikatakan"],["لَهُمْ","kepada mereka"],["لَآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["ٱللَّهُ","Allah"],["يَسْتَكْبِرُونَ","adalah sombong"]]],"3824":["(Dan mereka berkata, \"Apakah sesungguhnya kami) lafal A-innaa dapat pula dibaca Ayinnaa (harus meninggalkan sesembahan-sesembahan kami karena seorang penyair gila?\") yakni demi karena Muhammad.",[["وَيَقُولُونَ","Dan mereka berkata"],["أَئِنَّا","adakah kita"],["لَتَارِكُوٓا۟","untuk pergi"],["ءَالِهَتِنَا","tuhan kita"],["لِشَاعِرٍۢ","untuk seorang penyair"],["مَّجْنُونٍۭ","gila"]]],"3825":["Allah swt. berfirman: (Sebenarnya dia Muhammad telah datang membawa kebenaran dan membenarkan rasul-rasul) yang juga datang membawa kebenaran, yaitu kalimat Laa Ilaaha Illallaah/tidak ada Tuhan selain Allah.",[["بَلْ","Bahkan"],["جَآءَ","dia telah membawa"],["بِٱلْحَقِّ","kebenaran"],["وَصَدَّقَ","dan disahkan"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"3826":["(Sesungguhnya kalian) di dalam ungkapan ini terkandung Iltifat karena seharusnya Innahum (pasti akan merasakan azab yang pedih.)",[["إِنَّكُمْ","Sesungguhnya kamu"],["لَذَآئِقُوا۟","(akan) pasti rasa"],["ٱلْعَذَابِ","azab"],["ٱلْأَلِيمِ","yang pedih"]]],"3827":["(Dan kalian tidak diberi pembalasan melainkan) pembalasan (apa yang telah kalian kerjakan.)",[["وَمَا","Dan tidak"],["تُجْزَوْنَ","kamu akan mendapat balasan"],["إِلَّا","kecuali"],["مَا","apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"3828":["(Tetapi hamba-hamba Allah yang dibersihkan) yakni hamba-hamba Allah yang beriman, Istitsna di sini bersifat Munqathi', dan pembalasannya disebutkan pada firman selanjutnya, yaitu:",[["إِلَّا","Kecuali"],["عِبَادَ","(para) hamba"],["ٱللَّهِ","(milik) Allah"],["ٱلْمُخْلَصِينَ","yang terpilih"]]],"3829":["(Mereka itu memperoleh) di dalam surga (rezeki yang tertentu) setiap pagi dan sorenya.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["لَهُمْ","bagi mereka"],["رِزْقٌۭ","(akan menjadi) rezeki"],["مَّعْلُومٌۭ","ditentukan"]]],"3830":["(Yaitu buah-buahan) menjadi Badal atau 'Athaf Bayan dari lafal Rizqun; yaitu bermacam-macam rezeki yang dimakan hanya untuk dinikmati, bukan untuk memelihara kesehatan, karena penduduk surga tidak perlu lagi memelihara kesehatan sebab mereka telah diciptakan untuk hidup abadi dan sehat selama-lamanya. (Dan mereka adalah orang-orang yang dimuliakan) dengan pahala yang berlimpah dari Allah swt.",[["فَوَٰكِهُ ۖ","buah-buahan"],["وَهُم","dan mereka"],["مُّكْرَمُونَ","(akan) dihormati"]]],"3831":["(Di dalam surga-surga yang penuh nikmat.)",[["فِى","Dalam"],["جَنَّـٰتِ","Taman-taman"],["ٱلنَّعِيمِ","(dari) Kegembiraan"]]],"3832":["(Di atas takhta-takhta kebesaran berhadap-hadapan) artinya, sebagian dari mereka duduk menghadap kepada sebagian yang lain, sehingga sebagian dari mereka tidak melihat tengkuk sebagian yang lainnya.",[["عَلَىٰ","hidup"],["سُرُرٍۢ","takhta"],["مُّتَقَـٰبِلِينَ","berdepan antara satu sama lain"]]],"3833":["(Diedarkan kepada mereka) maksudnya, kepada masing-masing di antara mereka diedarkan (gelas) yaitu tempat untuk minum berikut minumannya (yang berisikan khamar dari sungai khamar) yang mengalir bagaikan sungai di bumi.",[["يُطَافُ","Akan diedarkan"],["عَلَيْهِم","antara mereka"],["بِكَأْسٍۢ","secawan"],["مِّن","daripada"],["مَّعِينٍۭ","mata air yang mengalir"]]],"3834":["(Warnanya putih) lebih putih daripada air susu (sedap rasanya) sangat lezat rasanya (bagi orang-orang yang minum) berbeda dengan khamar di dunia yang apabila diminum rasanya tidak enak.",[["بَيْضَآءَ","putih"],["لَذَّةٍۢ","sedap"],["لِّلشَّـٰرِبِينَ","untuk peminum"]]],"3835":["(Tidak ada di dalam khamar itu alkohol) yakni zat yang membuat akal mereka mabuk (dan mereka tiada mabuk karenanya) dapat dibaca Yunzafuuna atau yanzifuuna, yang berasal dari kalimat, Nazafasy Syaaribu, dan Anzafa, artinya memabukkan; maksudnya khamar surga itu tidak memabukkan berbeda halnya dengan khamar di dunia.",[["لَا","Tidak"],["فِيهَا","di dalamnya"],["غَوْلٌۭ","(adalah) kesan buruk"],["وَلَا","dan bukan"],["هُمْ","mereka"],["عَنْهَا","daripadanya"],["يُنزَفُونَ","akan mabuk"]]],"3836":["(Di sisi mereka ada bidadari-bidadari yang tidak liar pandangannya) yaitu bidadari-bidadari yang selalu menundukkan pandangan matanya, atau dengan kata lain mereka hanya memandang suami-suami mereka saja dan tidak memandang orang lain, karena menurut mereka suami-suami mereka adalah orang-orang yang paling cakap (dan jelita matanya) artinya mata bidadari-bidadari itu sangat jelita.",[["وَعِندَهُمْ","Dan dengan mereka"],["قَـٰصِرَٰتُ","(akan menjadi) teman yang memandang rendah"],["ٱلطَّرْفِ","(akan menjadi) teman yang memandang rendah"],["عِينٌۭ","(mempunyai) mata yang cantik"]]],"3837":["(Seakan-akan mereka) yakni warna kulit mereka (adalah telur) burung unta (yang tersimpan dengan baik) bagaikan telur burung unta yang terlindungi oleh bulu induknya, sehingga tidak ada suatu debu pun yang menempel padanya, demikian pula warnanya, putih kekuning-kuningan, warna kulit seperti itu adalah warna kulit wanita yang paling cantik.",[["كَأَنَّهُنَّ","Seolah-olah mereka"],["بَيْضٌۭ","telur"],["مَّكْنُونٌۭ","dilindungi dengan baik"]]],"3838":["(Lalu sebagian mereka menghadap) yakni sebagian penduduk surga (kepada sebagian yang lain sambil bercakap-cakap) mengenai apa yang telah mereka lakukan di dunia.",[["فَأَقْبَلَ","Dan (akan) mendekati"],["بَعْضُهُمْ","sebahagian mereka"],["عَلَىٰ","kepada"],["بَعْضٍۢ","yang lain"],["يَتَسَآءَلُونَ","mempersoalkan antara satu sama lain"]]],"3839":["(Berkatalah salah seorang di antara mereka, \"Sesungguhnya aku dahulu di dunia mempunyai seorang teman) yakni teman yang ingkar kepada adanya hari berbangkit.",[["قَالَ","Akan berkata"],["قَآئِلٌۭ","seorang penceramah"],["مِّنْهُمْ","antara mereka"],["إِنِّى","Sesungguhnya aku"],["كَانَ","telah"],["لِى","untuk aku"],["قَرِينٌۭ","seorang peneman"]]],"3840":["(Yang berkata,) kepadaku dengan nada yang mengejek, ('Apakah kamu sungguh-sungguh termasuk orang-orang yang membenarkan) adanya hari berbangkit?",[["يَقُولُ","Siapa (akan) berkata"],["أَءِنَّكَ","Adakah kamu memang"],["لَمِنَ","pasti daripada"],["ٱلْمُصَدِّقِينَ","mereka yang beriman"]]],"3841":["(Apakah apabila kita telah mati dan kita telah menjadi tanah dan tulang-belulang, apakah sesungguhnya kita) kedua huruf Hamzah pada ketiga tempat yang disebutkan di atas, yaitu A-innaka, A-idzaa dan A-innaa boleh dibaca Tahqiq dan boleh pula dibaca Tas-hil (benar-benar akan dibangkitkan untuk diberi pembalasan?') maksudnya akan dibalas dan dihisab? Ia ternyata ingkar kepada hal tersebut.",[["أَءِذَا","Adakah (ia) apabila"],["مِتْنَا","kita telah mati"],["وَكُنَّا","dan menjadi"],["تُرَابًۭا","habuk"],["وَعِظَـٰمًا","dan tulang"],["أَءِنَّا","akan kita"],["لَمَدِينُونَ","pasti dibawa ke pengadilan"]]],"3842":["(Berkata pulalah ia) yaitu penghuni surga yang mengatakan demikian kepada temannya ('Maukah kamu melihat keadaan temanku itu?'\") maksudnya bersama-sama untuk melihat apa yang dialami temannya di dalam neraka? Temannya menjawab, \"Tidak mau.\"",[["قَالَ","Dia (akan) berkata"],["هَلْ","akan"],["أَنتُم","kamu"],["مُّطَّلِعُونَ","sedang mencari"]]],"3843":["(Maka ia meninjaunya) yakni orang yang mengatakan demikian itu dari sebagian jendela surga (lalu ia melihat temannya itu) yaitu temannya yang ingkar kepada adanya hari berbangkit itu (di tengah-tengah neraka menyala-nyala) berada di tengah-tengah neraka Jahim.",[["فَٱطَّلَعَ","Kemudian dia (akan) melihat"],["فَرَءَاهُ","dan jumpa dia"],["فِى","dalam"],["سَوَآءِ","(the) tengah"],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"3844":["(Ia berkata pula) dengan nada mengejek, (\"Demi Allah, sesungguhnya) lafal In di sini adalah bentuk Takhfif dari Inna (kamu benar-benar hampir) kamu hampir saja (mencelakakanku) membinasakan aku melalui penyesatanmu itu.",[["قَالَ","Dia (akan) berkata"],["تَٱللَّهِ","Demi Allah"],["إِن","sesungguhnya"],["كِدتَّ","kamu hampir"],["لَتُرْدِينِ","merosakkan aku"]]],"3845":["(Jika tidak karena nikmat Rabbku) atas diriku yaitu berupa iman (pastilah aku termasuk orang-orang yang diseret) bersamamu ke dalam neraka. Dan penduduk surga berkata,",[["وَلَوْلَا","Dan jika tidak"],["نِعْمَةُ","(untuk) Rahmat"],["رَبِّى","(dari) Tuhanku"],["لَكُنتُ","sudah tentu, aku (akan) telah"],["مِنَ","antara"],["ٱلْمُحْضَرِينَ","yang dibawa"]]],"3846":["(Maka apakah kita tidak akan mati.)",[["أَفَمَا","Kemudian tidak"],["نَحْنُ","kita"],["بِمَيِّتِينَ","(untuk) mati"]]],"3847":["(Melainkan hanya kematian kita yang pertama) yakni kematian kita di dunia (dan kita tidak akan disiksa di akhirat ini?\") Istifham atau kata tanya di sini mengandung makna menetapkan kenikmatan yang mereka rasakan dan sebagai ungkapan rasa syukur mereka atas nikmat yang telah dilimpahkan Allah kepada diri mereka, yaitu mereka dijadikan hidup abadi dengan penuh kenikmatan dan tidak disiksa untuk selama-lamanya.",[["إِلَّا","Kecuali"],["مَوْتَتَنَا","kematian kita"],["ٱلْأُولَىٰ","yang pertama"],["وَمَا","dan bukan"],["نَحْنُ","kita"],["بِمُعَذَّبِينَ","akan dihukum"]]],"3848":["(Sesungguhnya ini) yakni apa yang Aku jelaskan mengenai keadaan penduduk surga (benar-benar kemenangan yang besar.)",[["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["لَهُوَ","pasti"],["ٱلْفَوْزُ","(ialah) pencapaian"],["ٱلْعَظِيمُ","yang besar"]]],"3849":["(Untuk kemenangan serupa ini hendaklah berusaha orang-orang yang beramal) menurut suatu pendapat, bahwa perkataan ini ditujukan kepada mereka. Dan menurut pendapat yang lain disebutkan, bahwa merekalah yang mengatakan demikian.",[["لِمِثْلِ","Untuk (yang) seperti"],["هَـٰذَا","(dari) ini"],["فَلْيَعْمَلِ","biarkan kerja"],["ٱلْعَـٰمِلُونَ","para pekerja"]]],"3850":["(Apakah yang demikian itu) hal-hal yang telah disebutkan bagi ahli surga itu (merupakan hidangan yang lebih baik) suguhan atau hidangan yang diperuntukkan menjamu tamu atau orang yang menginap (ataukah pohon zaqqum) yang disediakan buat ahli neraka; pohon zaqqum adalah pohon yang paling buruk dan sangat pahit rasanya, tempat asalnya adalah Tihamah. Allah menumbuhkan pohon itu di dalam neraka Jahim, sebagaimana yang akan diterangkan nanti.",[["أَذَٰلِكَ","Adakah itu"],["خَيْرٌۭ","lebih baik"],["نُّزُلًا","(sebagai) perhotelan"],["أَمْ","atau"],["شَجَرَةُ","(the) pokok"],["ٱلزَّقُّومِ","(dari) Zaqqum"]]],"3851":["(Sesungguhnya Kami menjadikan pohon zaqqum itu) artinya ditumbuhkannya pohon tersebut di dalam neraka (sebagai fitnah bagi orang-orang yang lalim) yakni orang-orang kafir Mekah, karena mereka telah mengatakan, bahwa api itu membakar pohon, mana mungkin di dalam neraka dapat ditumbuhkan pohon.",[["إِنَّا","Sesungguhnya Kami"],["جَعَلْنَـٰهَا","[Kami] telah berjaya"],["فِتْنَةًۭ","perbicaraan"],["لِّلظَّـٰلِمِينَ","bagi orang-orang yang zalim"]]],"3852":["(Sesungguhnya dia adalah sebatang pohon yang keluar dari dasar neraka yang menyala) yakni dari dasar neraka Jahanam, dan ranting-rantingnya mencuat sampai ke relung-relungnya.",[["إِنَّهَا","Sesungguhnya, ia"],["شَجَرَةٌۭ","(adalah) pokok"],["تَخْرُجُ","yang tumbuh"],["فِىٓ","dalam"],["أَصْلِ","(bahagian bawah)."],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"3853":["(Mayangnya) diserupakan dengan mayang pohon kurma (seperti kepala setan-setan) maksudnya, seperti ular-ular yang sangat buruk dan menjijikkan tampangnya.",[["طَلْعُهَا","Buahnya yang baru muncul"],["كَأَنَّهُۥ","(adalah) seolah-olah ia"],["رُءُوسُ","(adalah) kepala"],["ٱلشَّيَـٰطِينِ","(dari) syaitan"]]],"3854":["(Maka sesungguhnya mereka) yakni orang-orang kafir (benar-benar memakan sebagian dari pohon itu) sekalipun rasanya sangat memuakkan, karena mereka dalam keadaan sangat lapar (maka mereka memenuhi perutnya dengan buah zaqqum itu.)",[["فَإِنَّهُمْ","Dan sesungguhnya, mereka"],["لَـَٔاكِلُونَ","(akan) pasti makan"],["مِنْهَا","daripadanya"],["فَمَالِـُٔونَ","dan isi"],["مِنْهَا","dengannya"],["ٱلْبُطُونَ","perut (mereka)."]]],"3855":["(Kemudian sesudah makan buah pohon zaqqum itu pasti mereka mendapat minuman yang bercampur dengan air yang sangat panas) yang mereka minum, hingga bercampur di dalam perut mereka apa yang mereka makan dan apa yang mereka minum itu.",[["ثُمَّ","Kemudian"],["إِنَّ","sesungguhnya"],["لَهُمْ","bagi mereka"],["عَلَيْهَا","di dalamnya"],["لَشَوْبًۭا","(adalah) campuran"],["مِّنْ","daripada"],["حَمِيمٍۢ","air mendidih"]]],"3856":["(Kemudian sesungguhnya tempat kembali mereka benar-benar ke neraka Jahim) ayat ini memberikan pengertian, bahwa mereka keluar dahulu dari dalam neraka untuk meminum air hamim atau air yang sangat panas itu, dan bahwasanya air yang sangat panas itu adanya di luar neraka.",[["ثُمَّ","Kemudian"],["إِنَّ","sesungguhnya"],["مَرْجِعَهُمْ","kepulangan mereka"],["لَإِلَى","(akan) pasti menjadi"],["ٱلْجَحِيمِ","api Neraka"]]],"3857":["(Karena sesungguhnya mereka mendapati) menemukan (bapak-bapak mereka dalam keadaan sesat.)",[["إِنَّهُمْ","Sesungguhnya mereka"],["أَلْفَوْا۟","dijumpai"],["ءَابَآءَهُمْ","bapa mereka"],["ضَآلِّينَ","sesat"]]],"3858":["(Lalu mereka sangat tergesa-gesa mengikuti jejak orang-orang tua mereka itu) atau terburu-buru mengikutinya, oleh karenanya mereka tergesa-gesa mengikuti kesesatan bapak-bapak mereka, tanpa berpikir lebih jauh lagi.",[["فَهُمْ","Jadi mereka"],["عَلَىٰٓ","pada"],["ءَاثَـٰرِهِمْ","jejak kaki mereka"],["يُهْرَعُونَ","mereka bersegera"]]],"3859":["(Dan sesungguhnya telah sesat sebelum mereka sebagian besar dari orang-orang yang dahulu) umat-umat yang terdahulu.",[["وَلَقَدْ","Dan sesungguhnya"],["ضَلَّ","sesat"],["قَبْلَهُمْ","sebelum mereka"],["أَكْثَرُ","kebanyakannya"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"]]],"3860":["(Dan sesungguhnya telah Kami utus pemberi-pemberi peringatan di kalangan mereka) yakni rasul-rasul yang memberi peringatan kepada mereka.",[["وَلَقَدْ","Dan sesungguhnya"],["أَرْسَلْنَا","Kami utus"],["فِيهِم","antara mereka"],["مُّنذِرِينَ","pemberi amaran"]]],"3861":["(Maka perhatikanlah bagaimana kesudahan orang-orang yang diberi peringatan itu) yakni orang-orang kafir itu, kesudahan mereka mendapat azab.",[["فَٱنظُرْ","Kemudian lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلْمُنذَرِينَ","(dari) orang-orang yang diberi peringatan"]]],"3862":["(Kecuali hamba-hamba Allah yang dibersihkan -dari dosa-dosa-) yakni kaum mukminin, sesungguhnya mereka selamat dari azab, karena keikhlasan mereka dalam beribadah kepada Allah. Atau karena Allah telah membersihkan mereka dari dosa-dosanya, makna ini berdasar qiraat yang membacanya Mukhlashiina.",[["إِلَّا","Kecuali"],["عِبَادَ","(para) hamba"],["ٱللَّهِ","(milik) Allah"],["ٱلْمُخْلَصِينَ","yang terpilih"]]],"3863":["(Sesungguhnya Nuh telah menyeru Kami) melalui doanya, sebagaimana yang disitir oleh ayat lain, yaitu firman-Nya, \"Sesungguhnya aku ini adalah orang yang dikalahkan, oleh sebab itu menangkanlah (aku).\" (Q.S. Al-Qamar, 10). (maka sesungguhnya sebaik-baik yang memperkenankan) doanya adalah Kami. Maksudnya, Nuh berdoa kepada Allah untuk dimenangkan atas kaumnya, lalu Allah binasakan mereka melalui banjir besar hingga mereka tenggelam semuanya.",[["وَلَقَدْ","Dan sesungguhnya"],["نَادَىٰنَا","dipanggil Kami"],["نُوحٌۭ","Nuh"],["فَلَنِعْمَ","dan Terbaik"],["ٱلْمُجِيبُونَ","(adakah Kami sebagai) Responder"]]],"3864":["(Dan Kami telah menyelamatkannya beserta keluarganya dari bencana yang besar) yakni dari banjir yang besar itu.",[["وَنَجَّيْنَـٰهُ","Dan Kami selamatkan dia"],["وَأَهْلَهُۥ","dan keluarganya"],["مِنَ","daripada"],["ٱلْكَرْبِ","kesusahan itu"],["ٱلْعَظِيمِ","yang hebat"]]],"3865":["(Dan Kami jadikan anak cucunya orang-orang yang melanjutkan keturunan) dengan demikian maka manusia semuanya adalah anak cucu dari Nabi Nuh a.s. Nabi Nuh mempunyai tiga orang anak, yaitu Sam adalah bapak moyang bangsa Arab, bangsa Persia dan bangsa Romawi; Ham adalah bapak moyang bangsa yang berkulit hitam; Yafits adalah bapak moyang bangsa Turki, bangsa Khazr, Ya'juj dan Ma'juj dan lain-lainnya.",[["وَجَعَلْنَا","Dan Kami jadikan"],["ذُرِّيَّتَهُۥ","keturunannya"],["هُمُ","[mereka]"],["ٱلْبَاقِينَ","yang terselamat"]]],"3866":["(Dan Kami abadikan) Kami lestarikan (untuk Nuh itu) pujian yang baik (di kalangan orang-orang yang datang kemudian) yakni para nabi dan semua umat manusia hingga hari kiamat.",[["وَتَرَكْنَا","Dan Kami pergi"],["عَلَيْهِ","baginya"],["فِى","antara"],["ٱلْـَٔاخِرِينَ","generasi terkemudian"]]],"3867":["(Kesejahteraan) dari Kami dilimpahkan atas Nuh di seluruh alam.)",[["سَلَـٰمٌ","Salam sejahtera"],["عَلَىٰ","ke atas"],["نُوحٍۢ","Nuh"],["فِى","antara"],["ٱلْعَـٰلَمِينَ","dunia"]]],"3868":["(Sesungguhnya demikianlah Kami,) artinya sebagaimana Kami memberikan balasan kepada mereka (Kami memberi balasan kepada orang-orang yang berbuat baik.)",[["إِنَّا","Sesungguhnya Kami"],["كَذَٰلِكَ","dengan demikian"],["نَجْزِى","[Kami] memberi ganjaran"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"3869":["(Sesungguhnya dia termasuk di antara hamba-hamba Kami yang beriman.)",[["إِنَّهُۥ","Sesungguhnya dia"],["مِنْ","(adalah) daripada"],["عِبَادِنَا","hamba kita"],["ٱلْمُؤْمِنِينَ","beriman"]]],"3870":["(Kemudian Kami tenggelamkan orang-orang yang lain) yakni orang-orang kafir dari kaum Nabi Nuh.",[["ثُمَّ","Kemudian"],["أَغْرَقْنَا","Kami lemas"],["ٱلْـَٔاخَرِينَ","yang lain"]]],"3871":["(Dan sesungguhnya di antara golongan Nuh) yang mengikutinya dalam masalah pokok agama, yaitu masalah tauhid (adalah Ibrahim) sekalipun jarak zaman di antara keduanya sangat jauh, yaitu dua ribu enam ratus empat puluh tahun; dan adalah di antara keduanya terdapat Nabi Hud dan Nabi Saleh.",[["۞ وَإِنَّ","Dan sesungguhnya"],["مِن","antara"],["شِيعَتِهِۦ","jenis dia"],["لَإِبْرَٰهِيمَ","sesungguhnya Ibrahim"]]],"3872":["(Ingatlah ketika ia datang kepada Rabbnya) maksudnya, ia mengikuti-Nya sewaktu datang kepada kaumnya (dengan hati yang suci) dari keraguan dan hal-hal lainnya.",[["إِذْ","Apabila"],["جَآءَ","dia datang"],["رَبَّهُۥ","(kepada) Tuhannya"],["بِقَلْبٍۢ","dengan hati"],["سَلِيمٍ","bunyi"]]],"3873":["(Ingatlah ketika ia berkata) sedangkan ia dalam keadaan demikian, yakni bersih dari keraguan terhadap Rabbnya (kepada bapaknya dan kaumnya) dengan nada yang mencela. (\"Apakah) yang (kalian sembah itu?)",[["إِذْ","Apabila"],["قَالَ","dia berkata"],["لِأَبِيهِ","kepada bapanya"],["وَقَوْمِهِۦ","dan umatnya"],["مَاذَا","Apa itu"],["تَعْبُدُونَ","kamu menyembah"]]],"3874":["(Apakah dengan jalan berbohong) kedua huruf Hamzah pada ayat ini dapat dibaca Tahqiq atau Tas-hil (kalian menghendaki sesembahan-sesembahan selain Allah?) lafal Ifkan adalah Maf'ul Lah, dan lafal Aalihah adalah Maf'ul Bih bagi lafal Turiduuna. Al-Ifku artinya dusta yang paling buruk; makna yang dimaksud adalah, apakah kalian menyembah selain Allah?",[["أَئِفْكًا","Adakah ia kepalsuan"],["ءَالِهَةًۭ","tuhan"],["دُونَ","selain daripada"],["ٱللَّهِ","Allah"],["تُرِيدُونَ","(yang) kamu kehendaki"]]],"3875":["(Maka apakah anggapanmu terhadap Rabb semesta alam?\") jika kalian menyembah selain-Nya; apakah kalian menganggap bahwa Dia akan membiarkan kalian tanpa mengazab kalian? Tentu saja tidak, Dia pasti mengazab kalian. Mereka adalah orang-orang ahli perbintangan. Lalu mereka keluar pada hari raya mereka dan meletakkan makanan mereka di depan latar berhala-berhala mereka, mereka menduga bahwa hal itu dapat membawa berkah pada makanan mereka. Apabila mereka kembali, maka mereka memakan makanan tersebut. Mereka mengatakan kepada Nabi Ibrahim, \"Marilah kita keluar.\"",[["فَمَا","Kemudian apa"],["ظَنُّكُم","(adakah) kamu fikir"],["بِرَبِّ","tentang (Tuhan)."],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"3876":["(Lalu ia memandang sekali pandang ke bintang-bintang) untuk mengelabui mereka, bahwasanya dia percaya kepada bintang-bintang itu, supaya mereka tidak menaruh rasa curiga terhadap dirinya.",[["فَنَظَرَ","Kemudian dia mengerling"],["نَظْرَةًۭ","sepintas lalu"],["فِى","di"],["ٱلنُّجُومِ","bintang"]]],"3877":["(Kemudian ia berkata, \"Sesungguhnya aku sakit\") maksudnya, aku akan mengalami sakit.",[["فَقَالَ","Dan dia berkata"],["إِنِّى","Memang aku"],["سَقِيمٌۭ","sakit"]]],"3878":["(Lalu mereka berpaling daripadanya) menuju ke tempat perayaan mereka (dengan membelakangi)",[["فَتَوَلَّوْا۟","Jadi mereka berpaling"],["عَنْهُ","daripada dia"],["مُدْبِرِينَ","berlepas"]]],"3879":["(Kemudian ia pergi dengan diam-diam) atau Nabi Ibrahim berangkat dengan diam-diam menuju (kepada berhala-berhala mereka) yang pada saat itu di hadapannya terdapat banyak hidangan makanan (lalu ia berkata) dengan nada yang sinis ditujukan kepada berhala-berhala mereka itu, (\"Apakah kalian tidak makan?\") tetapi berhala-berhala itu diam saja.",[["فَرَاغَ","Kemudian dia berpaling"],["إِلَىٰٓ","kepada"],["ءَالِهَتِهِمْ","tuhan mereka"],["فَقَالَ","dan berkata"],["أَلَا","Jangan"],["تَأْكُلُونَ","kamu makan"]]],"3880":["Maka Ibrahim berkata, (\"Kenapa kalian tidak menjawab?\") ternyata berhala-berhala itu tidak juga menjawab.",[["مَا","Apakah (ada)"],["لَكُمْ","bagi kamu"],["لَا","tidak"],["تَنطِقُونَ","kamu bercakap"]]],"3881":["(Lalu dihadapinya berhala-berhala itu sambil memukulnya dengan tangan kanannya) artinya, dengan sekuat-kuatnya hingga berhala-berhala itu pecah berantakan. Berita penghancuran berhala-berhala itu sampai kepada kaumnya melalui orang-orang yang melihat Nabi Ibrahim sedang menghancurkannya.",[["فَرَاغَ","Kemudian dia berpaling"],["عَلَيْهِمْ","ke atas mereka"],["ضَرْبًۢا","menarik perhatian"],["بِٱلْيَمِينِ","dengan tangan kanan"]]],"3882":["(Kemudian kaumnya datang kepadanya dengan bergegas) mereka berjalan dengan terburu-buru, lalu mereka berkata kepada Nabi Ibrahim, \"Kami menyembahnya sedangkan kamu memecahkannya.\"",[["فَأَقْبَلُوٓا۟","Kemudian mereka maju"],["إِلَيْهِ","terhadapnya"],["يَزِفُّونَ","menyegerakan"]]],"3883":["(Ibrahim berkata) kepada mereka dengan nada sinis, (\"Apakah kalian menyembah patung-patung yang kalian pahat itu?) dari batu dan dari bahan-bahan lainnya sebagai berhala-berhala yang kalian sembah.",[["قَالَ","Dia berkata"],["أَتَعْبُدُونَ","Adakah kamu menyembah"],["مَا","apa"],["تَنْحِتُونَ","kamu mengukir"]]],"3884":["(Padahal Allahlah yang telah menciptakan kalian dan apa yang kalian perbuat itu\") yakni tentang apa yang kalian pahat dan hasil pahatan kalian itu, karenanya sembahlah Dia dan esakanlah Dia. Huruf Maa di sini menurut suatu pendapat adalah Maa Mashdariyah, menurut pendapat lainnya adalah Maa Maushulah, dan menurut pendapat lainnya lagi adalah Maa Maushufah.",[["وَٱللَّهُ","Sedangkan Allah"],["خَلَقَكُمْ","mencipta kamu"],["وَمَا","dan apa"],["تَعْمَلُونَ","kamu buat"]]],"3885":["(Mereka berkata) di antara sesama mereka (\"Dirikanlah suatu bangunan untuknya) lalu kumpulkanlah kayu-kayu bakar di bawahnya, dan nyalakanlah api padanya, maka apabila ia telah menyala (lemparkanlah dia ke dalam api yang menyala-nyala itu\") yakni ke dalam api yang telah membesar nyalanya itu.",[["قَالُوا۟","Mereka berkata"],["ٱبْنُوا۟","bina"],["لَهُۥ","baginya"],["بُنْيَـٰنًۭا","sesuatu struktur"],["فَأَلْقُوهُ","dan buang dia"],["فِى","ke dalam"],["ٱلْجَحِيمِ","Api yang menyala-nyala"]]],"3886":["(Mereka hendak melakukan tipu muslihat kepadanya) dengan melemparkannya ke dalam api yang menyala-nyala untuk membinasakannya (maka Kami jadikan mereka orang-orang yang hina) orang-orang yang dikalahkan; karena ternyata Nabi Ibrahim keluar dari dalam api itu dalam keadaan selamat tidak apa-apa.",[["فَأَرَادُوا۟","Dan mereka berniat"],["بِهِۦ","baginya"],["كَيْدًۭا","plot"],["فَجَعَلْنَـٰهُمُ","tetapi Kami jadikan mereka"],["ٱلْأَسْفَلِينَ","paling rendah"]]],"3887":["(Dan Ibrahim berkata, \"Sesungguhnya aku pergi menghadap kepada Rabbku) artinya berhijrah demi karena-Nya meninggalkan negeri orang-orang kafir (dan Dia akan memberi petunjuk kepadaku) ke tempat yang aku diperintahkan-Nya berangkat ke sana, yaitu negeri Syam. Tatkala ia sampai di tanah suci yaitu Baitulmakdis, berkatalah ia dalam doanya,",[["وَقَالَ","Dan dia berkata"],["إِنِّى","Memang aku"],["ذَاهِبٌ","pergi"],["إِلَىٰ","kepada"],["رَبِّى","Tuhanku"],["سَيَهْدِينِ","Dia akan membimbing aku"]]],"3888":["('Ya Rabbku! Anugerahkanlah kepadaku) seorang anak (yang termasuk orang-orang yang saleh.')",[["رَبِّ","Tuhanku"],["هَبْ","pemberian"],["لِى","aku"],["مِنَ","daripada"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"3889":["(Maka Kami beri dia kabar gembira dengan seorang anak yang amat sabar) yakni yang banyak memiliki kesabaran.",[["فَبَشَّرْنَـٰهُ","Maka Kami beri dia berita gembira"],["بِغُلَـٰمٍ","seorang budak lelaki"],["حَلِيمٍۢ","penyabar"]]],"3890":["(Maka tatkala anak itu sampai pada umur sanggup berusaha bersama-sama Ibrahim) yaitu telah mencapai usia sehingga dapat membantunya bekerja; menurut suatu pendapat bahwa umur anak itu telah mencapai tujuh tahun. Menurut pendapat yang lain bahwa pada saat itu anak Nabi Ibrahim berusia tiga belas tahun (Ibrahim berkata, \"Hai anakku! Sesungguhnya aku melihat) maksudnya, telah melihat (dalam mimpi bahwa aku menyembelihmu!) mimpi para nabi adalah mimpi yang benar, dan semua pekerjaan mereka berdasarkan perintah dari Allah swt. (maka pikirkanlah apa pendapatmu!\") tentang impianku itu; Nabi Ibrahim bermusyawarah dengannya supaya ia menurut, mau disembelih, dan taat kepada perintah-Nya. (Ia menjawab, \"Hai bapakku) huruf Ta pada lafal Abati ini merupakan pergantian dari Ya Idhafah (kerjakanlah apa yang diperintahkan kepadamu) untuk melakukannya (Insya Allah engkau akan mendapatiku termasuk orang-orang yang sabar\") menghadapi hal tersebut.",[["فَلَمَّا","Kemudian apabila"],["بَلَغَ","dia sampai"],["مَعَهُ","(umur) bekerja dengannya"],["ٱلسَّعْىَ","(umur) bekerja dengannya"],["قَالَ","dia berkata"],["يَـٰبُنَىَّ","Wahai anakku"],["إِنِّىٓ","Sesungguhnya aku"],["أَرَىٰ","dah nampak"],["فِى","dalam"],["ٱلْمَنَامِ","mimpi itu"],["أَنِّىٓ","bahawa aku"],["أَذْبَحُكَ","mengorbankan kamu"],["فَٱنظُرْ","jadi tengok"],["مَاذَا","apa"],["تَرَىٰ ۚ","kamu lihat"],["قَالَ","Dia berkata"],["يَـٰٓأَبَتِ","Wahai ayahku"],["ٱفْعَلْ","buat"],["مَا","apa"],["تُؤْمَرُ ۖ","kamu diperintahkan"],["سَتَجِدُنِىٓ","kamu akan jumpa aku"],["إِن","jika"],["شَآءَ","Allah berkehendak"],["ٱللَّهُ","Allah berkehendak"],["مِنَ","daripada"],["ٱلصَّـٰبِرِينَ","yang sabar"]]],"3891":["(Tatkala keduanya telah berserah diri) artinya, tunduk dan patuh kepada perintah Allah swt. (dan Ibrahim membaringkan anaknya atas pelipisnya) Nabi Ismail dibaringkan pada salah satu pelipisnya; setiap manusia memiliki dua pelipis dan di antara keduanya terdapat jidat. Kejadian ini di Mina; kemudian Nabi Ibrahim menggorokkan pisau besarnya ke leher Nabi Ismail, akan tetapi berkat kekuasaan Allah pisau itu tidak mempan sedikit pun.",[["فَلَمَّآ","Kemudian apabila"],["أَسْلَمَا","kedua-duanya telah menyerahkan"],["وَتَلَّهُۥ","dan dia meletakkannya"],["لِلْجَبِينِ","atas dahinya"]]],"3892":["(Dan Kami panggil dia, \"Hai Ibrahim!)",[["وَنَـٰدَيْنَـٰهُ","Dan Kami menyerunya"],["أَن","bahawa"],["يَـٰٓإِبْرَٰهِيمُ","Wahai Ibrahim"]]],"3893":["(Sesungguhnya kamu telah membenarkan mimpimu itu\") melalui apa yang telah kamu kerjakan, yaitu melaksanakan penyembelihan yang diperintahkan itu atau dengan kata lain, cukuplah bagimu hal itu. Jumlah kalimat Naadainaahu merupakan jawab dari lafal Lammaa, hanya ditambahi Wau (sesungguhnya demikianlah) maksudnya, sebagaimana Kami memberikan pahala kepadamu (Kami memberi balasan kepada orang-orang yang berbuat baik) terhadap diri mereka sendiri dengan melaksanakan apa yang diperintahkan kepada mereka, yaitu Kami akan melepaskan mereka dari kesulitan.",[["قَدْ","Sesungguhnya"],["صَدَّقْتَ","kamu telah memenuhi"],["ٱلرُّءْيَآ ۚ","penglihatan itu"],["إِنَّا","Sesungguhnya Kami"],["كَذَٰلِكَ","dengan demikian"],["نَجْزِى","[Kami] memberi ganjaran"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"3894":["(Sesungguhnya ini) penyembelihan yang diperintahkan ini (benar-benar suatu ujian yang nyata) atau cobaan yang jelas.",[["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["لَهُوَ","(adalah) pasti [ia]"],["ٱلْبَلَـٰٓؤُا۟","perbicaraan"],["ٱلْمُبِينُ","yang nyata"]]],"3895":["(Dan Kami tebus anak itu) maksudnya, anak yang diperintahkan untuk disembelih (Nabi Ismail). Menurut suatu pendapat bahwa anak yang disembelih itu adalah Nabi Ishak (dengan seekor sembelihan) yakni dengan domba (yang besar) dari surga, yaitu domba yang sama dengan domba yang dijadikan kurban oleh Habil. Domba itu dibawa oleh malaikat Jibril, lalu Nabi Ibrahim menyembelihnya seraya membaca takbir.",[["وَفَدَيْنَـٰهُ","Dan Kami tebus dia"],["بِذِبْحٍ","dengan pengorbanan"],["عَظِيمٍۢ","yang besar"]]],"3896":["(Kami abadikan) Kami lestarikan (untuk Ibrahim itu di kalangan orang-orang yang datang kemudian) pujian yang baik.",[["وَتَرَكْنَا","Dan Kami pergi"],["عَلَيْهِ","baginya"],["فِى","antara"],["ٱلْـَٔاخِرِينَ","generasi terkemudian"]]],"3897":["(\"Kesejahteraan) dari Kami (dilimpahkan atas Ibrahim.\")",[["سَلَـٰمٌ","Salam sejahtera"],["عَلَىٰٓ","pada"],["إِبْرَٰهِيمَ","Ibrahim"]]],"3898":["(Demikianlah) sebagaimana Kami memberikan imbalan pahala kepada Ibrahim (kami memberi balasan kepada orang-orang yang berbuat baik) terhadap diri mereka sendiri.",[["كَذَٰلِكَ","Demikianlah"],["نَجْزِى","Kami memberi ganjaran"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"3899":["(Sesungguhnya ia termasuk hamba-hamba Kami yang beriman.)",[["إِنَّهُۥ","Sesungguhnya dia (adalah)"],["مِنْ","daripada"],["عِبَادِنَا","hamba kita"],["ٱلْمُؤْمِنِينَ","beriman"]]],"3900":["(Dan Kami beri dia kabar gembira dengan kelahiran Ishak) dengan adanya ayat ini dapat disimpulkan, bahwa anak yang disembelih itu bukanlah Nabi Ishak tetapi anak Nabi Ibrahim yang lainnya, yaitu Nabi Ismail (seorang nabi) menjadi Hal dari lafal yang diperkirakan keberadaannya, artinya kelak ia akan menjadi seorang nabi (yang termasuk orang-orang yang saleh.)",[["وَبَشَّرْنَـٰهُ","Dan Kami beri dia berita gembira"],["بِإِسْحَـٰقَ","daripada Ishak"],["نَبِيًّۭا","seorang Nabi"],["مِّنَ","antara"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"3901":["(Kami limpahkan keberkatan atasnya) dengan diperbanyak anak cucunya (dan atas Ishak) anak Nabi Ibrahim, yaitu Kami menjadikan kebanyakan para nabi dari keturunannya. (Dan di antara anak cucunya ada yang berbuat baik) maksudnya, yang beriman (dan ada pula yang lalim terhadap dirinya sendiri) yang kafir (dengan nyata) nyata kekafirannya.",[["وَبَـٰرَكْنَا","Dan Kami memberkati"],["عَلَيْهِ","dia"],["وَعَلَىٰٓ","dan [pada]"],["إِسْحَـٰقَ ۚ","Ishak"],["وَمِن","Dan daripada"],["ذُرِّيَّتِهِمَا","keturunan mereka"],["مُحْسِنٌۭ","(adalah) orang yang berbuat baik"],["وَظَالِمٌۭ","dan tidak adil"],["لِّنَفْسِهِۦ","kepada dirinya sendiri"],["مُبِينٌۭ","yang nyata"]]],"3902":["(Dan sesungguhnya Kami telah melimpahkan nikmat atas Musa dan Harun) yakni nikmat kenabian.",[["وَلَقَدْ","Dan sesungguhnya"],["مَنَنَّا","Kami menganugerahkan Nikmat"],["عَلَىٰ","ke atas"],["مُوسَىٰ","Musa"],["وَهَـٰرُونَ","dan Harun"]]],"3903":["(Dan Kami selamatkan keduanya dan kaumnya) yaitu kaum Bani Israel (dari bencana yang besar) dari perbudakan Firaun atas mereka.",[["وَنَجَّيْنَـٰهُمَا","Dan Kami selamatkan keduanya"],["وَقَوْمَهُمَا","dan rakyat mereka"],["مِنَ","daripada"],["ٱلْكَرْبِ","kesusahan itu"],["ٱلْعَظِيمِ","yang hebat"]]],"3904":["(Dan Kami tolong mereka) dari cengkeraman bangsa Koptik (maka jadilah mereka orang-orang yang menang.)",[["وَنَصَرْنَـٰهُمْ","Dan Kami menolong mereka"],["فَكَانُوا۟","jadi mereka menjadi"],["هُمُ","jadi mereka menjadi"],["ٱلْغَـٰلِبِينَ","para pemenang"]]],"3905":["(Dan Kami berikan kepada keduanya kitab yang sangat jelas) yang di dalamnya terkandung hukum-hukum dan batasan-batasan serta hal-hal lainnya, yang kesemuanya itu diterangkan dengan jelas dan gamblang di dalamnya; Kitab yang dimaksud adalah Kitab Taurat.",[["وَءَاتَيْنَـٰهُمَا","Dan Kami berikan keduanya"],["ٱلْكِتَـٰبَ","Kitab"],["ٱلْمُسْتَبِينَ","yang jelas"]]],"3906":["(Dan kami tunjuki keduanya ke jalan) yakni kepada tuntunan (yang lurus.)",[["وَهَدَيْنَـٰهُمَا","Dan Kami beri petunjuk kepada keduanya"],["ٱلصِّرَٰطَ","(ke) Jalan"],["ٱلْمُسْتَقِيمَ","yang Lurus"]]],"3907":["(Dan Kami abadikan) Kami lestarikan (untuk keduanya di kalangan orang-orang yang datang kemudian) pujian yang baik.",[["وَتَرَكْنَا","Dan Kami pergi"],["عَلَيْهِمَا","untuk mereka berdua"],["فِى","antara"],["ٱلْـَٔاخِرِينَ","generasi terkemudian"]]],"3908":["(Yaitu \"Kesejahteraan) dari Kami (dilimpahkan atas Musa dan Harun\".')",[["سَلَـٰمٌ","Salam sejahtera"],["عَلَىٰ","ke atas"],["مُوسَىٰ","Musa"],["وَهَـٰرُونَ","dan Harun"]]],"3909":["(Sesungguhnya demikianlah) maksudnya, sebagaimana Kami memberikan balasan pahala kepada keduanya (Kami memberi balasan kepada orang-orang yang berbuat baik.)",[["إِنَّا","Sesungguhnya Kami"],["كَذَٰلِكَ","dengan demikian"],["نَجْزِى","pahala"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"3910":["(Sesungguhnya keduanya termasuk hamba-hamba Kami yang beriman.)",[["إِنَّهُمَا","Memang mereka berdua"],["مِنْ","(adalah) daripada"],["عِبَادِنَا","hamba kita"],["ٱلْمُؤْمِنِينَ","beriman"]]],"3911":["(Dan sesungguhnya Ilyas) dapat dibaca Ilyaas atau Alyaas (benar-benar termasuk salah seorang rasul-rasul) menurut suatu pendapat bahwa Nabi Ilyas itu adalah anak saudara lelaki Nabi Harun dan Nabi Musa. Menurut pendapat yang lain bukan; ia diutus oleh Allah kepada kaum yang tinggal di kota Ba'albak dan sekitarnya.",[["وَإِنَّ","Dan sesungguhnya"],["إِلْيَاسَ","Elia"],["لَمِنَ","(adalah) pasti daripada"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"3912":["(Ingatlah ketika) lafal Idz di sini dinashabkan oleh lafal Udzkur yang diperkirakan keberadaannya (ia berkata kepada kaumnya, \"Mengapa kalian tidak bertakwa) kepada Allah?",[["إِذْ","Apabila"],["قَالَ","dia berkata"],["لِقَوْمِهِۦٓ","kepada umatnya"],["أَلَا","tidak akan"],["تَتَّقُونَ","kamu takut"]]],"3913":["(Patutkah kalian menyembah Ba'l) Ba'l adalah nama berhala yang terbuat dari emas, dan dengan nama berhala itu pula negeri mereka diberi nama, lalu dimudhafkan kepada lafal Bik, sehingga jadilah Ba'alabak. Maksud ayat ini ialah mengapa kalian menyembahnya (dan kalian tinggalkan) artinya kalian tidak menyembah (sebaik-baik pencipta) yakni Allah; maksudnya mengapa kalian tidak menyembah Allah?",[["أَتَدْعُونَ","Adakah kamu memanggil"],["بَعْلًۭا","Baal"],["وَتَذَرُونَ","dan kamu tinggalkan"],["أَحْسَنَ","(yang) Terbaik"],["ٱلْخَـٰلِقِينَ","(daripada) Pencipta"]]],"3914":["(Yaitu Allah Rabb kalian dan Rabb bapak-bapak kalian yang terdahulu?\") kalau dibaca Allaahu Rabbukum Warabbu Aabaa-ikum, berarti sebelumnya diperkirakan adanya lafal Huwa. Kalau dibaca Allaaha Rabbakum warabba Aabaa-ikum berarti menjadi Badal dari lafal Ahsanal Khaaliqiina.",[["ٱللَّهَ","Allah"],["رَبَّكُمْ","Tuhanmu"],["وَرَبَّ","dan (yang) Tuhan"],["ءَابَآئِكُمُ","(dari) nenek moyang kamu"],["ٱلْأَوَّلِينَ","(dari) nenek moyang kamu"]]],"3915":["(Maka mereka mendustakannya, karena itu mereka akan diseret) ke dalam neraka.",[["فَكَذَّبُوهُ","Tetapi mereka menafikannya"],["فَإِنَّهُمْ","jadi sesungguhnya, mereka"],["لَمُحْضَرُونَ","(akan) pasti dibawa"]]],"3916":["(Kecuali hamba-hamba Allah yang dibersihkan dari dosa) yaitu hamba-hamba Allah yang beriman, mereka diselamatkan dari neraka.",[["إِلَّا","Kecuali"],["عِبَادَ","(para) hamba"],["ٱللَّهِ","(milik) Allah"],["ٱلْمُخْلَصِينَ","yang terpilih"]]],"3917":["(Dan Kami abadikan untuk Ilyas di kalangan orang-orang yang datang kemudian) pujian yang baik.",[["وَتَرَكْنَا","Dan Kami pergi"],["عَلَيْهِ","baginya"],["فِى","antara"],["ٱلْـَٔاخِرِينَ","generasi terkemudian"]]],"3918":["(Yaitu \"Kesejahteraan) dari Kami (dilimpahkan atas Ilyasin) yang dimaksud adalah Nabi Ilyas yang tadi, ia dinamakan demikian secara Taghlib, perihalnya sama dengan ucapan orang-orang Arab jika menamakan Muhallab dan kaumnya, mereka menamakannya Al-Muhallabuun. Dan menurut qiraat yang membacakannya menjadi Aali Yasiina dengan dipanjangkan harakat Hamzahnya, berarti keluarga Nabi Ilyas, dan makna yang dimaksud adalah Nabi Ilyas pula.",[["سَلَـٰمٌ","Salam sejahtera"],["عَلَىٰٓ","ke atas"],["إِلْ يَاسِينَ","Elia"]]],"3919":["(Sesungguhnya demikianlah) sebagaimana Kami memberikan balasan pahala kepadanya (Kami memberikan balasan kepada orang-orang yang berbuat baik.)",[["إِنَّا","Sesungguhnya Kami"],["كَذَٰلِكَ","dengan demikian"],["نَجْزِى","pahala"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"3920":["(Sesungguhnya dia termasuk hamba-hamba Kami yang beriman.)",[["إِنَّهُۥ","Sesungguhnya dia (adalah)"],["مِنْ","daripada"],["عِبَادِنَا","hamba kita"],["ٱلْمُؤْمِنِينَ","beriman"]]],"3921":["(Dan sesungguhnya Luth benar-benar adalah seorang rasul.)",[["وَإِنَّ","Dan sesungguhnya"],["لُوطًۭا","Lut"],["لَّمِنَ","(adalah) daripada"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"3922":["(Ingatlah ketika Kami selamatkan dia dan keluarganya pengikut-pengikutnya semua.)",[["إِذْ","Apabila"],["نَجَّيْنَـٰهُ","Kami menyelamatkannya"],["وَأَهْلَهُۥٓ","dan keluarganya"],["أَجْمَعِينَ","semua"]]],"3923":["(Kecuali seorang perempuan tua istrinya yang berada bersama-sama orang yang ditinggal) orang-orang yang ditinggal tertimpa azab.",[["إِلَّا","Kecuali"],["عَجُوزًۭا","seorang wanita tua"],["فِى","(adalah) antara"],["ٱلْغَـٰبِرِينَ","mereka yang tinggal di belakang"]]],"3924":["(Kemudian Kami binasakan) Kami hancurkan (orang-orang yang lain) yaitu orang-orang yang kafir dari kaumnya.",[["ثُمَّ","Kemudian"],["دَمَّرْنَا","Kami musnahkan"],["ٱلْـَٔاخَرِينَ","yang lain"]]],"3925":["(Dan sesungguhnya kalian hai penduduk Mekah benar-benar akan melalui mereka) melalui bekas-bekas dan tempat-tempat tinggal mereka bila kalian mengadakan perjalanan (di waktu pagi) maksudnya di waktu siang hari.",[["وَإِنَّكُمْ","Dan sesungguhnya, kamu"],["لَتَمُرُّونَ","pasti lulus"],["عَلَيْهِم","oleh mereka"],["مُّصْبِحِينَ","(pada) pagi"]]],"3926":["(Dan di waktu malam hari. Maka apakah kalian tidak memikirkan?) hai penduduk Mekah, mengenai apa yang telah menimpa mereka berupa azab, oleh karena kalian lalu mengambil pelajaran darinya.",[["وَبِٱلَّيْلِ ۗ","Dan pada waktu malam"],["أَفَلَا","Kemudian tidak akan"],["تَعْقِلُونَ","kamu menggunakan alasan"]]],"3927":["(Sesungguhnya Yunus benar-benar salah seorang rasul.)",[["وَإِنَّ","Dan sesungguhnya"],["يُونُسَ","Yunus"],["لَمِنَ","(adalah) pasti daripada"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"3928":["(Ingatlah ketika ia lari) maksudnya, minggat (ke kapal yang penuh muatan) hal ini terjadi sewaktu ia bersitegang dengan kaumnya, karena ternyata azab yang diancamkan olehnya kepada kaumnya tidak turun-turun juga, akhirnya ia melarikan diri naik kapal. Dan kapal yang dinaikinya itu berhenti di tengah laut yang besar ombaknya. Juru mudi kapal mengatakan, bahwa di dalam kapal ini terdapat seorang hamba yang melarikan diri dari tuannya, hal ini akan tampak jelas melalui undian.",[["إِذْ","Apabila"],["أَبَقَ","dia lari"],["إِلَى","kepada"],["ٱلْفُلْكِ","kapal itu"],["ٱلْمَشْحُونِ","sarat"]]],"3929":["(Kemudian ia ikut berundi) para penumpang kapal itu semuanya diundi (lalu dia termasuk orang-orang yang kalah dalam undian itu) akibatnya ia dilemparkan ke laut.",[["فَسَاهَمَ","Kemudian dia membuat undian"],["فَكَانَ","dan adalah"],["مِنَ","daripada"],["ٱلْمُدْحَضِينَ","yang rugi"]]],"3930":["(Maka ia ditelan oleh ikan besar) ditelan bulat-bulat (dalam keadaan tercela) karena ia melakukan perbuatan yang tercela, yaitu pergi dengan memakai jalan laut kemudian naik kapal meninggalkan kaumnya, tanpa izin terlebih dahulu dari Rabbnya.",[["فَٱلْتَقَمَهُ","Kemudian menelannya"],["ٱلْحُوتُ","ikan itu"],["وَهُوَ","sedangkan dia"],["مُلِيمٌۭ","(adalah) patut dipersalahkan"]]],"3931":["(Maka kalau sekiranya dia tidak termasuk orang-orang yang bertasbih) yakni selalu ingat kepada Allah, melalui zikirnya di dalam perut ikan seraya mengatakan, \"Laa Ilaaha Illaa Anta Subhaanaka Innii Kuntu Minazh Zhaalimiina\", artinya, \"Tidak ada Tuhan selain Engkau, Maha Suci Engkau, sesungguhnya aku termasuk orang-orang yang aniaya.\"",[["فَلَوْلَآ","Dan jika tidak"],["أَنَّهُۥ","bahawa dia"],["كَانَ","adalah"],["مِنَ","daripada"],["ٱلْمُسَبِّحِينَ","mereka yang bertasbih"]]],"3932":["(Niscaya ia akan tetap tinggal di perut ikan itu sampai hari berbangkit) artinya, niscaya perut ikan besar itu akan menjadi kuburnya hingga hari kiamat nanti.",[["لَلَبِثَ","Sudah tentu, dia (akan) kekal"],["فِى","dalam"],["بَطْنِهِۦٓ","perutnya"],["إِلَىٰ","sehingga"],["يَوْمِ","Hari itu"],["يُبْعَثُونَ","mereka dibangkitkan"]]],"3933":["(Kemudian Kami lemparkan dia) Kami campakkan dia dari dalam perut ikan besar itu (ke daerah yang tandus) di permukaan bumi yang tandus, yakni ke tepi pantai pada hari itu juga, setelah tiga hari, tujuh hari, dua puluh hari atau setelah empat puluh hari sejak ia ditelan ikan besar itu (sedangkan ia dalam keadaan sakit) yakni kurus kering dan sakit bagaikan anak ayam yang terserang penyakit kok.",[["۞ فَنَبَذْنَـٰهُ","Tetapi Kami lemparkan dia"],["بِٱلْعَرَآءِ","ke pantai terbuka"],["وَهُوَ","sedangkan dia"],["سَقِيمٌۭ","(sedang) sakit"]]],"3934":["(Dan Kami tumbuhkan untuk dia sebatang pohon dari jenis labu) pohon itu dapat menaunginya dengan batangnya, berbeda keadaannya dengan pohon labu yang biasanya. Hal ini merupakan suatu mukjizat baginya, setiap pagi dan petang datang kepadanya kambing hutan, ia meminum air susu dari teteknya hingga ia kuat kembali.",[["وَأَنۢبَتْنَا","Dan Kami tumbuhkan"],["عَلَيْهِ","atas dia"],["شَجَرَةًۭ","tumbuhan"],["مِّن","daripada"],["يَقْطِينٍۢ","labu"]]],"3935":["(Dan Kami utus dia) sesudah itu, sebagaimana status sebelumnya, kepada kaum Bunainawiy yang tinggal di daerah Maushul (kepada seratus ribu orang atau) bahkan (lebih dari itu) yakni lebih dua puluh atau tiga puluh atau tujuh puluh ribu orang.",[["وَأَرْسَلْنَـٰهُ","Dan Kami telah mengutusnya"],["إِلَىٰ","kepada"],["مِا۟ئَةِ","seratus"],["أَلْفٍ","ribu"],["أَوْ","atau"],["يَزِيدُونَ","lebih"]]],"3936":["(Lalu mereka beriman) sewaktu mereka menyaksikan azab yang telah dijanjikan kepada mereka (karena itu Kami anugerahkan kenikmatan hidup kepada mereka) artinya, kami biarkan mereka menikmati harta yang ada pada mereka (hingga waktu yang tertentu) hingga ajal mereka datang.",[["فَـَٔامَنُوا۟","Dan mereka beriman"],["فَمَتَّعْنَـٰهُمْ","maka Kami berikan mereka kesenangan"],["إِلَىٰ","bagi"],["حِينٍۢ","seketika"]]],"3937":["(Tanyakanlah kepada mereka) kepada orang-orang kafir Mekah; ungkapan ini dimaksud sebagai ejekan terhadap mereka, (\"Apakah untuk Rabb kamu anak-anak perempuan) sesuai dengan dugaan mereka bahwa para malaikat itu adalah anak-anak perempuan Allah (dan untuk mereka anak laki-laki) mereka memilih yang lebih kuat dan yang lebih baik.",[["فَٱسْتَفْتِهِمْ","Kemudian tanya mereka"],["أَلِرَبِّكَ","Adakah Tuhanmu"],["ٱلْبَنَاتُ","(mempunyai) anak perempuan"],["وَلَهُمُ","manakala bagi mereka"],["ٱلْبَنُونَ","(adalah) anak lelaki"]]],"3938":["(Atau apakah Kami menciptakan malaikat-malaikat berupa perempuan dan mereka menyaksikannya\") yakni mereka menyaksikan penciptaan Kami itu, yang karenanya mereka mengatakan demikian?",[["أَمْ","Atau"],["خَلَقْنَا","adakah Kami cipta"],["ٱلْمَلَـٰٓئِكَةَ","para Malaikat"],["إِنَـٰثًۭا","perempuan"],["وَهُمْ","sedangkan mereka"],["شَـٰهِدُونَ","(adalah) saksi"]]],"3939":["(Ketahuilah bahwa sesungguhnya mereka dengan kebohongannya) dengan kedustaan mereka itu (benar-benar mengatakan,)",[["أَلَآ","Tidak syak lagi"],["إِنَّهُم","sesungguhnya, mereka"],["مِّنْ","daripada"],["إِفْكِهِمْ","kepalsuan mereka"],["لَيَقُولُونَ","[mereka] berkata"]]],"3940":["(\"Allah beranak\") melalui perkataan mereka yang menyatakan bahwa malaikat-malaikat itu adalah anak-anak perempuan Allah. (Dan sesungguhnya mereka benar-benar orang yang berdusta) dalam hal ini.",[["وَلَدَ","Allah telah beranak"],["ٱللَّهُ","Allah telah beranak"],["وَإِنَّهُمْ","dan sesungguhnya, mereka"],["لَكَـٰذِبُونَ","sesungguhnya (adalah) pendusta"]]],"3941":["(Apakah Tuhan memilih) lafal Ashthafaa Hamzahnya adalah Hamzah Istifham yang berharakat Fatah, oleh karenanya Hamzah Washal tidak dibutuhkan lagi, sebab itu dibuang. Yakni apakah Allah mengutamakan (anak-anak perempuan daripada anak laki-laki?)",[["أَصْطَفَى","Adakah Dia telah memilih"],["ٱلْبَنَاتِ","[the] anak perempuan"],["عَلَى","atas"],["ٱلْبَنِينَ","anak lelaki"]]],"3942":["(Apakah yang terjadi pada kalian? Bagaimanakah caranya kalian menetapkan?) kesimpulan yang rusak ini.",[["مَا","Ada apa dengan kamu"],["لَكُمْ","Ada apa dengan kamu"],["كَيْفَ","Bagaimana"],["تَحْكُمُونَ","kamu menilai"]]],"3943":["(Maka apakah kalian tidak memikirkan?) bahwasanya Allah swt. itu Maha Tinggi lagi Maha Suci dari mempunyai anak?",[["أَفَلَا","Kemudian tidak akan"],["تَذَكَّرُونَ","kamu perhatikan"]]],"3944":["(Atau apakah kalian mempunyai bukti yang nyata?) artinya hujah yang jelas menyatakan bahwa Allah mempunyai anak.",[["أَمْ","Atau"],["لَكُمْ","(adalah) untuk kamu"],["سُلْطَـٰنٌۭ","sebuah pihak berkuasa"],["مُّبِينٌۭ","yang nyata"]]],"3945":["(Maka bawalah kitab kalian) kitab Taurat kalian, kemudian perlihatkanlah kepadaku mengenai hal itu di dalamnya (jika kalian memang orang-orang yang benar) di dalam perkataan dan dugaan kalian itu.",[["فَأْتُوا۟","Kemudian bawa"],["بِكِتَـٰبِكُمْ","buku kamu"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"3946":["(Dan mereka adakan) orang-orang musyrik itu (antara Dia) yakni Allah swt. (dan antara jin) yakni malaikat dinamakan Al-Jinnah karena mereka tidak dapat dilihat oleh mata (hubungan nasab) melalui perkataan mereka yang menyatakan bahwasanya malaikat-malaikat itu adalah anak-anak perempuan Allah. (Dan sesungguhnya jin mengetahui bahwa mereka) yakni orang-orang yang mengatakan demikian (benar-benar akan diseret) ke dalam neraka dan mereka akan diazab di dalamnya.",[["وَجَعَلُوا۟","Dan mereka telah membuat"],["بَيْنَهُۥ","antara Dia"],["وَبَيْنَ","dan antara"],["ٱلْجِنَّةِ","jin"],["نَسَبًۭا ۚ","sebuah perhubungan"],["وَلَقَدْ","tetapi yang pasti"],["عَلِمَتِ","mengetahui"],["ٱلْجِنَّةُ","jin"],["إِنَّهُمْ","bahawa mereka"],["لَمُحْضَرُونَ","(akan) pasti dibawa"]]],"3947":["(Maha Suci Allah) kalimat ini memahasucikan Dia (dari apa yang mereka sifatkan) yaitu bahwasanya Allah mempunyai anak.",[["سُبْحَـٰنَ","Maha Suci"],["ٱللَّهِ","(kepada) Allah"],["عَمَّا","atas apa"],["يَصِفُونَ","mereka sifatkan"]]],"3948":["(Kecuali hamba-hamba Allah yang dibersihkan dari dosa) yakni kecuali orang-orang yang beriman. Istitsna di sini adalah bersifat Munqathi'. Maksudnya bahwa mereka yang beriman itu memahasucikan Allah swt. dari apa yang telah disifatkan oleh mereka kepada-Nya.",[["إِلَّا","Kecuali"],["عِبَادَ","(para) hamba"],["ٱللَّهِ","(milik) Allah"],["ٱلْمُخْلَصِينَ","yang terpilih"]]],"3949":["(Maka sesungguhnya kalian dan apa-apa yang kalian sembah itu) yakni berhala-berhala sesembahan-sesembahan kalian itu.",[["فَإِنَّكُمْ","Jadi sesungguhnya, kamu"],["وَمَا","dan apa"],["تَعْبُدُونَ","kamu menyembah"]]],"3950":["(Sekali-kali kalian dengannya tidak akan dapat) dengan melalui sesembahan kalian itu; lafal 'Alaihi berta'alluq kepada firman selanjutnya, yaitu (menyesatkan) seorang pun.",[["مَآ","Tidak"],["أَنتُمْ","kamu"],["عَلَيْهِ","daripadaNya"],["بِفَـٰتِنِينَ","boleh menggoda (sesiapa sahaja)"]]],"3951":["(Kecuali orang-orang yang akan masuk neraka yang menyala-nyala) menurut ilmu Allah swt.",[["إِلَّا","Kecuali"],["مَنْ","yang"],["هُوَ","dia"],["صَالِ","(adalah) untuk dibakar"],["ٱلْجَحِيمِ","(dalam) api Neraka"]]],"3952":["Malaikat Jibril berkata kepada Nabi saw., (\"Tiada seorang pun di antara kami) para malaikat (melainkan mempunyai kedudukan yang tertentu) di langit, di tempat itu ia beribadah kepada Allah dan tidak melampaui tempat atau kedudukan yang lain.",[["وَمَا","Dan tidak"],["مِنَّآ","antara kita"],["إِلَّا","kecuali"],["لَهُۥ","baginya"],["مَقَامٌۭ","(adalah) jawatan"],["مَّعْلُومٌۭ","diketahui"]]],"3953":["(Dan sesungguhnya kami benar-benar bersaf-saf) artinya meluruskan telapak kaki kami dalam salat.",[["وَإِنَّا","Dan sesungguhnya, kita"],["لَنَحْنُ","pasti, [kami]"],["ٱلصَّآفُّونَ","berdiri dalam barisan"]]],"3954":["(Dan sesungguhnya kami benar-benar bertasbih.\") menyucikan Allah dari hal-hal yang tidak layak bagi-Nya.",[["وَإِنَّا","Dan sesungguhnya, kita"],["لَنَحْنُ","pasti, [kami]"],["ٱلْمُسَبِّحُونَ","bertasbih (Allah)"]]],"3955":["(Sesungguhnya) lafal In di sini adalah bentuk Takhfif dari lafal Inna (mereka) yakni orang-orang kafir Mekah (akan berkata,)",[["وَإِن","Dan sesungguhnya"],["كَانُوا۟","mereka dahulu"],["لَيَقُولُونَ","berkata"]]],"3956":["(\"Kalau sekiranya di sisi kami ada sebuah peringatan) maksudnya, sebuah kitab (dari orang-orang yang dahulu) yakni dari kitab-kitab yang diturunkan kepada orang-orang yang dahulu.",[["لَوْ","Jika"],["أَنَّ","bahawa"],["عِندَنَا","kami ada"],["ذِكْرًۭا","peringatan"],["مِّنَ","daripada"],["ٱلْأَوَّلِينَ","bekas (orang)"]]],"3957":["(Benar-benar kami akan jadi hamba Allah yang mukhlis\") maksudnya beribadah kepada-Nya semata.",[["لَكُنَّا","Sudah tentu, kami (akan) telah"],["عِبَادَ","hamba"],["ٱللَّهِ","(milik) Allah"],["ٱلْمُخْلَصِينَ","yang terpilih"]]],"3958":["Allah berfirman, (\"Tetapi mereka mengingkarinya) mengingkari Kitab yang diturunkan kepada mereka, yaitu Alquran kitab yang lebih mulia daripada kitab-kitab yang diturunkan sebelumnya (kelak mereka akan mengetahui) akibat dari kekafiran dan keingkaran mereka itu.",[["فَكَفَرُوا۟","Tetapi mereka tidak beriman"],["بِهِۦ ۖ","di dalamnya"],["فَسَوْفَ","tidak lama lagi"],["يَعْلَمُونَ","mereka akan tahu"]]],"3959":["(Dan sesungguhnya telah tetap janji Kami) pertolongan Kami (kepada hamba-hamba Kami yang menjadi rasul) yaitu sebagaimana yang telah diungkapkan oleh firman-Nya yang lain, \"Aku dan rasul-rasul-Ku pasti menang.\" (Q.S. Al-Mujadilah, 21).",[["وَلَقَدْ","Dan sesungguhnya"],["سَبَقَتْ","telah mendahului"],["كَلِمَتُنَا","Firman Kami"],["لِعِبَادِنَا","untuk hamba-hamba Kami"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"3960":["Atau janji tersebut sebagaimana yang diungkapkan-Nya pada ayat berikut ini, yaitu, (yaitu, 'Sesungguhnya mereka itulah yang pasti mendapat pertolongan.')",[["إِنَّهُمْ","Sesungguhnya mereka"],["لَهُمُ","pasti mereka"],["ٱلْمَنصُورُونَ","(akan menjadi) orang yang menang"]]],"3961":["(Dan sesungguhnya tentara Kami) yakni orang-orang mukmin (itulah yang pasti menang) atas orang-orang kafir melalui hujah, dan mendapat kemenangan atas mereka di dunia ini. Dan jika sebagian dari orang-orang yang beriman itu tidak mendapat kemenangan atas orang-orang kafir di dunia ini, maka mereka pasti mendapat kemenangan di akhirat nanti.",[["وَإِنَّ","Dan sesungguhnya"],["جُندَنَا","Tuan rumah kami"],["لَهُمُ","pasti, mereka"],["ٱلْغَـٰلِبُونَ","(iaitu) orang-orang yang menang"]]],"3962":["(Maka berpalinglah kamu dari mereka) yaitu dari orang-orang kafir Mekah (sampai suatu ketika\") sampai Dia memerintahkannya untuk memerangi mereka.",[["فَتَوَلَّ","Jadi berpalinglah"],["عَنْهُمْ","daripada mereka"],["حَتَّىٰ","sehingga"],["حِينٍۢ","suatu masa"]]],"3963":["(Dan terangkanlah kepada mereka) apabila azab turun kepada mereka (maka kelak mereka akan mengetahui) akibat dari kekafiran mereka.",[["وَأَبْصِرْهُمْ","Dan lihat mereka"],["فَسَوْفَ","tidak lama lagi"],["يُبْصِرُونَ","mereka akan melihat"]]],"3964":["Maka mereka mengatakan dengan nada yang mengejek, \"Kapankah turunnya azab itu?\" Lalu Allah berfirman mengancam mereka yang mengatakan demikian: (Maka apakah mereka meminta supaya siksa Kami disegerakan.)",[["أَفَبِعَذَابِنَا","Kemudian adalah untuk azab Kami"],["يَسْتَعْجِلُونَ","mereka bersegera"]]],"3965":["(Maka apabila siksaan itu turun di halaman mereka) maksudnya, di tengah-tengah mereka. Sehubungan dengan makna lafal As-Saahah ini Imam Al-Farra mengatakan, bahwa orang-orang Arab bila menyebutkan suatu kaum cukup hanya dengan menyebutkan halaman tempat mereka tinggal (maka amat buruklah) yakni seburuk-buruk pagi hari adalah (pagi hari yang dialami oleh orang-orang yang diperingatkan itu) di dalam ungkapan ayat ini terdapat Isim Zahir yang menduduki tempatnya Isim Mudhmar.",[["فَإِذَا","Tetapi apabila"],["نَزَلَ","ia turun"],["بِسَاحَتِهِمْ","di wilayah mereka"],["فَسَآءَ","maka kejahatan (akan)"],["صَبَاحُ","(pada) pagi"],["ٱلْمُنذَرِينَ","(bagi) orang-orang yang diberi peringatan"]]],"3966":["(Dan berpalinglah kamu dari mereka hingga suatu ketika.)",[["وَتَوَلَّ","Jadi berpalinglah"],["عَنْهُمْ","daripada mereka"],["حَتَّىٰ","bagi"],["حِينٍۢ","suatu masa"]]],"3967":["(Dan lihatlah, karena mereka juga akan melihat) ayat ini diulangi penyebutannya dengan maksud untuk mengukuhkan ancaman yang ditujukan kepada mereka, dan sekaligus sebagai penenang hati bagi Nabi saw.",[["وَأَبْصِرْ","Dan lihat"],["فَسَوْفَ","tidak lama lagi"],["يُبْصِرُونَ","mereka akan melihat"]]],"3968":["(Maha Suci Rabbmu Yang mempunyai keperkasaan) yakni kemenangan (dari apa yang mereka katakan) yaitu, bahwa Dia memiliki anak.",[["سُبْحَـٰنَ","kemuliaan"],["رَبِّكَ","(untuk) Tuhanmu"],["رَبِّ","(yang) Tuhan"],["ٱلْعِزَّةِ","(dari) Kehormatan"],["عَمَّا","atas apa"],["يَصِفُونَ","mereka sifatkan"]]],"3969":["(Dan kesejahteraan dilimpahkan atas para rasul) yang menyampaikan ajaran tauhid dan syariat-syariat dari Allah swt.",[["وَسَلَـٰمٌ","Dan selamat sejahtera"],["عَلَى","ke atas"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"3970":["(Dan segala puji bagi Allah Tuhan seru sekalian alam) Yang menolong mereka dan yang membinasakan orang-orang yang kafir.",[["وَٱلْحَمْدُ","Dan semua pujian"],["لِلَّهِ","bagi Allah"],["رَبِّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"3971":["(Shaad) hanya Allahlah yang mengetahui artinya (demi Alquran yang mempunyai keagungan) yakni penjelasan atau kemuliaan. Jawab dari qasamnya tidak disebutkan, yaitu, bahwa perkaranya tidak seperti apa yang dikatakan oleh orang-orang kafir Mekah, tuhan itu bermacam-macam.",[["صٓ ۚ","Saad"],["وَٱلْقُرْءَانِ","Oleh al-Quran"],["ذِى","penuh (dengan) peringatan"],["ٱلذِّكْرِ","penuh (dengan) peringatan"]]],"3972":["(Sebenarnya orang-orang kafir itu) yakni penduduk Mekah yang kafir (berada dalam kesombongan) hamiyyah dan takabbur tidak mau beriman (dan permusuhan yang sengit) selalu menentang dan memusuhi Nabi saw.",[["بَلِ","Bahkan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["فِى","(ada) dalam"],["عِزَّةٍۢ","kemuliaan diri"],["وَشِقَاقٍۢ","dan pembangkang"]]],"3973":["(Berapa banyak) sudah berapa banyak (umat sebelum mereka yang telah Kami binasakan) yaitu dari kalangan umat-umat yang terdahulu, (lalu mereka meminta tolong) sewaktu azab menimpa mereka (padahal waktu itu bukanlah saat untuk lari melepaskan diri) artinya, untuk melarikan diri dari azab, karena segalanya sudah terlambat. Huruf Ta pada lafal Laata merupakan huruf Zaidah, dan jumlah kalimat ayat ini berkedudukan menjadi Hal atau kata keterangan keadaan dari Fa'ilnya lafal Naadau. Maksudnya, mereka meminta tolong padahal sudah tidak ada lagi jalan untuk melarikan diri, dan pula tidak ada lagi jalan untuk selamat dari azab. Akan tetapi penduduk Mekah yang kafir tidaklah mengambil pelajaran dari mereka yang telah dibinasakan itu.",[["كَمْ","berapa banyak"],["أَهْلَكْنَا","Kami musnahkan"],["مِن","sebelum mereka"],["قَبْلِهِم","sebelum mereka"],["مِّن","daripada"],["قَرْنٍۢ","satu generasi"],["فَنَادَوا۟","kemudian mereka memanggil"],["وَّلَاتَ","apabila tidak ada lagi"],["حِينَ","masa"],["مَنَاصٍۢ","(untuk) melarikan diri"]]],"3974":["(Dan mereka heran karena mereka kedatangan seorang pemberi peringatan dari kalangan mereka sendiri) yakni seorang Rasul dari kalangan mereka yang memberi peringatan dan mempertakuti mereka dengan azab neraka sesudah dibangkitkan nanti. Orang yang dimaksud adalah Nabi saw. (dan orang-orang kafir berkata,) di dalam ungkapan ini Isim Zhahir menduduki tempat Isim Mudhmar (\"Ini adalah seorang ahli sihir yang banyak berdusta.)",[["وَعَجِبُوٓا۟","Dan mereka tertanya-tanya"],["أَن","bahawa"],["جَآءَهُم","telah datang kepada mereka"],["مُّنذِرٌۭ","seorang pemberi amaran"],["مِّنْهُمْ ۖ","daripada diri mereka sendiri"],["وَقَالَ","Dan berkata"],["ٱلْكَـٰفِرُونَ","orang kafir"],["هَـٰذَا","Ini"],["سَـٰحِرٌۭ","(adalah) ahli sihir"],["كَذَّابٌ","pembohong"]]],"3975":["(Mengapa ia menjadikan tuhan-tuhan itu Tuhan yang satu saja?\") demikian itu karena Nabi saw. pernah bersabda kepada mereka, \"Katakanlah, 'Laa Ilaaha Illallaah', artinya tiada Tuhan selain Allah. Mereka menjawab, 'Mana mungkin makhluk yang sedemikian banyak itu, semuanya dapat ditangani oleh Tuhan Yang Satu itu.' (Sesungguhnya itu benar-benar suatu hal yang sangat mengherankan\") sangat aneh.",[["أَجَعَلَ","Adakah dia telah membuat"],["ٱلْـَٔالِهَةَ","tuhan-tuhan"],["إِلَـٰهًۭا","(menjadi) tuhan yang satu"],["وَٰحِدًا ۖ","(menjadi) tuhan yang satu"],["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["لَشَىْءٌ","(adalah) pasti sesuatu"],["عُجَابٌۭ","ingin tahu"]]],"3976":["(Dan pergilah pemimpin-pemimpin mereka) dari majelis tempat mereka berkumpul, yaitu tempat Abu Thalib; di tempat itulah mereka mendengar dari Nabi saw. yang mengatakan, \"Katakanlah oleh kalian, 'Laa Ilaaha Illallaah', artinya tiada Tuhan selain Allah (seraya mengatakan, 'Pergilah kalian') maksudnya, sebagian dari mereka berkata kepada sebagian yang lain 'pergilah kalian' (dan tetaplah menyembah tuhan-tuhan kalian) artinya bertahanlah kalian di dalam menyembah tuhan-tuhan kalian itu (sesungguhnya ini) ajaran tauhid yang disampaikan Nabi itu (benar-benar suatu hal yang dikehendaki\") olehnya supaya kita melakukannya.",[["وَٱنطَلَقَ","Dan pergi"],["ٱلْمَلَأُ","ketua-ketua"],["مِنْهُمْ","antara mereka"],["أَنِ","bahawa"],["ٱمْشُوا۟","Teruskan"],["وَٱصْبِرُوا۟","dan bersabarlah"],["عَلَىٰٓ","atas"],["ءَالِهَتِكُمْ ۖ","tuhan-tuhan kamu"],["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["لَشَىْءٌۭ","(adalah) pasti sesuatu"],["يُرَادُ","dimaksudkan"]]],"3977":["(Kami tidak pernah mendengar hal ini dalam agama yang terakhir) maksudnya, agama Nabi Isa. (Tiada lain) tidak lain (ini hanyalah dusta yang diada-adakan) hal yang dibuat-buat saja.",[["مَا","Tidak"],["سَمِعْنَا","kami dengar"],["بِهَـٰذَا","ini"],["فِى","dalam"],["ٱلْمِلَّةِ","agama itu"],["ٱلْـَٔاخِرَةِ","yang terakhir"],["إِنْ","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّا","tetapi"],["ٱخْتِلَـٰقٌ","suatu rekaan"]]],"3978":["(Mengapa telah diturunkan) dapat dibaca Tahqiq dapat pula dibaca Tas-hil (kepadanya) kepada Muhammad (peringatan) yakni kitab Alquran (di antara kita?) bukan diturunkan kepada orang yang tertua di antara kita atau orang yang paling terhormat di antara kita. Maksudnya, mengapa Alquran itu tidak diturunkan kepada orang yang paling tua atau orang yang paling terhormat di antara mereka. Lalu Allah berfirman, (\"Sebenarnya mereka ragu terhadap Alquran-Ku) atau ragu terhadap wahyu-Ku, yaitu Alquran, karena mereka mendustakan rasul yang mendatangkannya (dan sebenarnya belumlah) artinya, belum lagi (mereka merasakan azab-Ku\") seandainya mereka telah merasakannya niscaya mereka mau beriman kepada Nabi saw. tentang apa yang disampaikan olehnya dari sisi-Ku. Akan tetapi pada saat itu, yakni saat mereka merasakan azab-Ku, tidak ada gunanya lagi iman.",[["أَءُنزِلَ","Telah didedahkan"],["عَلَيْهِ","kepadanya"],["ٱلذِّكْرُ","Mesej"],["مِنۢ","daripada"],["بَيْنِنَا ۚ","antara kita"],["بَلْ","Bahkan"],["هُمْ","mereka"],["فِى","(ada) dalam"],["شَكٍّۢ","keraguan"],["مِّن","tentang"],["ذِكْرِى ۖ","Mesej Aku"],["بَل","Bahkan"],["لَّمَّا","belum lagi"],["يَذُوقُوا۟","mereka telah rasa"],["عَذَابِ","hukuman aku"]]],"3979":["(Atau apakah mereka itu mempunyai perbendaharaan rahmat Rabbmu Yang Maha Perkasa) yakni Maha Menang (lagi Maha Pemberi?) termasuk derajat kenabian dan hal-hal lainnya, karenanya mereka dapat memberikannya kepada siapa yang mereka kehendaki.",[["أَمْ","Atau"],["عِندَهُمْ","mempunyai mereka"],["خَزَآئِنُ","(the) khazanah"],["رَحْمَةِ","(dari) Rahmat"],["رَبِّكَ","Tuhanmu"],["ٱلْعَزِيزِ","Yang Maha Perkasa"],["ٱلْوَهَّابِ","yang Maha Pemberi"]]],"3980":["(Atau apakah bagi mereka kerajaan langit dan bumi dan yang ada di antara keduanya?) jika mereka menduga hal tersebut (maka hendaklah mereka menaiki tangga-tangga) yang dapat mengantarkan mereka ke langit, lalu mereka mengambil wahyu dan mendatangkannya, kemudian mereka memberikannya secara khusus kepada orang-orang yang mereka kehendaki. Istifham atau kata tanya pada kedua tempat itu mengandung makna ingkar.",[["أَمْ","Atau"],["لَهُم","bagi mereka"],["مُّلْكُ","(ialah) kekuasaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَمَا","dan apa sahaja"],["بَيْنَهُمَا ۖ","(adalah) di antara mereka"],["فَلْيَرْتَقُوا۟","Kemudian biarkan mereka naik"],["فِى","oleh"],["ٱلْأَسْبَـٰبِ","cara"]]],"3981":["(Suatu tentara) maksudnya, suatu pasukan yang hina (di sana) yang telah mendustakanmu (pasti dikalahkan) menjadi sifat bagi lafal Jundun, sekalipun mereka terdiri (dari golongan-golongan yang bersekutu) lafal ayat ini menjadi sifat pula bagi lafal Jundun. Yakni suatu pasukan yang sama dengan pasukan-pasukan yang berserikat sebelum kamu yang memerangi para nabi. Pasukan-pasukan dahulu itu dapat dikalahkan dan dibinasakan, maka demikian pula mereka yang bersekutu untuk menghancurkanmu akan Kami binasakan pula.",[["جُندٌۭ","askar"],["مَّا","di sana"],["هُنَالِكَ","di sana"],["مَهْزُومٌۭ","(mereka akan) dikalahkan"],["مِّنَ","antara"],["ٱلْأَحْزَابِ","syarikat-syarikat tersebut"]]],"3982":["(Telah mendustakan pula sebelum mereka itu kaum Nuh) lafal Qaum dianggap sebagai muannats karena ditinjau dari segi maknanya (Ad dan Firaun yang mempunyai patok yang banyak) disebutkan bahwa Firaun selalu mematok atau memasung setiap orang yang menentangnya, lalu kedua kaki dan tangan orang yang menentangnya itu diikatkan pada empat patok, kemudian disiksa. Oleh karenanya ia dijuluki sebagai Dzul Autaad.",[["كَذَّبَتْ","dinafikan"],["قَبْلَهُمْ","sebelum mereka"],["قَوْمُ","kaum"],["نُوحٍۢ","(daripada) Nuh"],["وَعَادٌۭ","dan Aad"],["وَفِرْعَوْنُ","dan Firaun"],["ذُو","(pemilik)."],["ٱلْأَوْتَادِ","(dari) pertaruhan"]]],"3983":["(Dan Tsamud, kaum Luth dan penduduk Aikah) yakni penduduk kota Al-Ghidhah, mereka adalah kaum Nabi Syuaib a.s. (Mereka itulah golongan-golongan yang bersekutu menentang rasul-rasul).",[["وَثَمُودُ","Dan Thamud"],["وَقَوْمُ","dan (orang-orang) itu"],["لُوطٍۢ","(dari) Lut"],["وَأَصْحَـٰبُ","dan (para) sahabat"],["لْـَٔيْكَةِ ۚ","(dari) kayu itu"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلْأَحْزَابُ","(adalah) syarikat-syarikat itu"]]],"3984":["(Tidak lain) tiada lain (semuanya) artinya masing-masing dari golongan-golongan yang bersekutu itu (hanyalah mendustakan rasul-rasul) karena mereka telah mendustakan salah seorang dari rasul-rasul itu, ini berarti sama saja dengan mendustakan semua rasul-rasul, karena sesungguhnya seruan dan ajaran mereka satu, yaitu menyeru kepada ajaran tauhid (maka pastilah) wajiblah bagi mereka (azab-Ku).",[["إِن","Tidak"],["كُلٌّ","semua (mereka)"],["إِلَّا","tetapi"],["كَذَّبَ","dinafikan"],["ٱلرُّسُلَ","para Rasul"],["فَحَقَّ","begitu (adalah) adil"],["عِقَابِ","Penalti aku"]]],"3985":["(Tiadalah yang ditunggu-tunggu) yang dinantikan (oleh mereka) oleh orang-orang kafir Mekah. (melainkan hanya satu teriakan) yaitu tiupan sangkakala untuk kiamat yang saat itu mereka ditimpa oleh azab (yang tidak ada bagi mereka saat berselang) maksudnya, sesudah itu tidak akan ada saat hidup kembali seperti di dunia. Lafal Fawaaqin dapat pula dibaca Fuwaaqin.",[["وَمَا","Dan tidak"],["يَنظُرُ","tunggu"],["هَـٰٓؤُلَآءِ","ini"],["إِلَّا","tetapi"],["صَيْحَةًۭ","teriakan"],["وَٰحِدَةًۭ","satu"],["مَّا","tidak"],["لَهَا","baginya"],["مِن","sebarang"],["فَوَاقٍۢ","kelewatan"]]],"3986":["(Dan mereka berkata) sewaktu Allah menurunkan firman-Nya, \"Adapun orang-orang yang diberikan kepadanya kitabnya dari sebelah kanannya...\" (Q.S. Al-Haqqah, 19) (\"Ya Rabb kami! Segerakanlah untuk kami catatan amal kami) yakni kitab catatan amal kami (sebelum hari berhisab\") mereka mengatakan hal ini dengan nada yang sinis dan mengejek.",[["وَقَالُوا۟","Dan mereka berkata"],["رَبَّنَا","Wahai Tuhan kami"],["عَجِّل","cepatkan"],["لَّنَا","bagi kami"],["قِطَّنَا","bahagian kami"],["قَبْلَ","sebelum"],["يَوْمِ","(the) Hari"],["ٱلْحِسَابِ","(daripada) Akaun"]]],"3987":["Allah swt. berfirman, (\"Bersabarlah atas segala apa yang mereka katakan; ingatlah hamba Kami Daud yang mempunyai kekuatan) dalam beribadah; tersebutlah bahwa dia sepanjang tahun selalu berpuasa sehari dan berbuka sehari; bangun pada tengah malam untuk melakukan salat, kemudian tidur selama sepertiga malam dan seperenam malam harinya lagi ia gunakan untuk salat (sesungguhnya dia amat taat) yakni selalu mengerjakan hal-hal yang menjadi keridaan Allah swt.",[["ٱصْبِرْ","Bersabarlah"],["عَلَىٰ","atas"],["مَا","apa"],["يَقُولُونَ","mereka berkata"],["وَٱذْكُرْ","dan ingat"],["عَبْدَنَا","hamba kita"],["دَاوُۥدَ","Dawood"],["ذَا","pemilik kekuatan"],["ٱلْأَيْدِ ۖ","pemilik kekuatan"],["إِنَّهُۥٓ","Sesungguhnya dia (adalah)"],["أَوَّابٌ","berulang kali berpusing"]]],"3988":["(Sesungguhnya Kami menundukkan gunung-gunung untuk bertasbih bersama dia di waktu petang) di waktu salat Isyak (dan pagi) di waktu salat Duha, yaitu di waktu matahari mencapai sepenggalah.",[["إِنَّا","Sesungguhnya Kami"],["سَخَّرْنَا","tertakluk"],["ٱلْجِبَالَ","pergunungan"],["مَعَهُۥ","dengan dia"],["يُسَبِّحْنَ","bertasbih"],["بِٱلْعَشِىِّ","pada waktu petang"],["وَٱلْإِشْرَاقِ","dan matahari terbit"]]],"3989":["(Dan) Kami tundukkan pula (burung-burung dalam keadaan berkumpul) berkumpul untuk bertasbih bersama dengan dia. (Masing-masing) dari gunung-gunung dan burung-burung itu (amat taat kepada-Nya) taat bertasbih kepada-Nya.",[["وَٱلطَّيْرَ","Dan burung"],["مَحْشُورَةًۭ ۖ","berhimpun"],["كُلٌّۭ","semua"],["لَّهُۥٓ","dengan dia"],["أَوَّابٌۭ","berulang kali berpusing"]]],"3990":["(Dan Kami kuatkan kerajaannya) Kami kuatkan kerajaannya itu dengan para penjaga dan bala tentara; dan setiap malam mihrab Nabi Daud selalu dijaga oleh tiga puluh ribu pasukan (dan Kami berikan, kepadanya hikmah) yakni, kenabian dan ketepatan dalam berbagai perkara (dan kebijaksanaan dalam menyelesaikan perselisihan\") yaitu penjelasan yang memuaskan dalam semua urusan.",[["وَشَدَدْنَا","Dan Kami kuatkan"],["مُلْكَهُۥ","kerajaannya"],["وَءَاتَيْنَـٰهُ","dan Kami berikan kepadanya"],["ٱلْحِكْمَةَ","[kebijaksanaan]"],["وَفَصْلَ","dan tegas"],["ٱلْخِطَابِ","ucapan"]]],"3991":["(Dan adakah) Istifham atau kata tanya di sini mengandung makna Ta'ajjub dan Tasywiq, atau dengan kata lain mengandung makna yang mendorong dan merangsang pendengar untuk mendengarkan kalimat-kalimat selanjutnya (sampai kepadamu) hai Muhammad (berita orang-orang yang berperkara ketika mereka memanjat pagar mihrab?) yaitu mihrab Nabi Daud, yang dimaksud adalah mesjidnya; demikian itu terjadi karena mereka dilarang masuk, sebab Nabi Daud sedang beribadah. Akhirnya mereka masuk dengan memanjat pagar mihrabnya. Makna ayat ialah apakah kamu telah mendengar berita dan kisah mereka?",[["۞ وَهَلْ","Dan telah (ada)"],["أَتَىٰكَ","datang kepada kamu"],["نَبَؤُا۟","(the) berita"],["ٱلْخَصْمِ","(daripada) pihak yang berperkara"],["إِذْ","apabila"],["تَسَوَّرُوا۟","mereka memanjat dinding"],["ٱلْمِحْرَابَ","(dari) bilik itu"]]],"3992":["(Ketika mereka masuk menemui Daud lalu ia terkejut karena kedatangan mereka. Mereka berkata, \"Janganlah kamu merasa takut) kami (adalah dua orang yang bersengketa) menurut suatu pendapat dikatakan, bahwa yang bersengketa itu adalah dua golongan, demikian itu supaya sesuai dengan dhamir jamak yang sebelumnya. Menurut pendapat yang lain disebutkan bahwa orang yang bersengketa itu dua orang, sedangkan dhamir jamak diartikan dengannya. Lafal Al-Khashmu dapat diartikan untuk satu orang atau lebih. Kedua orang itu adalah dua malaikat yang menjelma menjadi dua orang yang sedang bersengketa. Persengketaan yang terjadi di antara keduanya hanyalah sebagai perumpamaan, dimaksud untuk mengingatkan Nabi Daud a.s. atas apa yang telah dilakukannya. Karena ia mempunyai istri sebanyak sembilan puluh sembilan orang wanita. Tetapi sekalipun demikian ia melamar istri orang lain yang hanya mempunyai seorang istri kemudian ia mengawininya dan menggaulinya (salah seorang dari kami berbuat zalim kepada yang lain, maka berilah keputusan antara kami dengan adil dan janganlah kamu menyimpang dari kebenaran) janganlah kamu berlaku berat sebelah (dan tunjukilah kami) bimbinglah kami (ke jalan yang lurus) yakni keputusan yang pertengahan dan adil.",[["إِذْ","Apabila"],["دَخَلُوا۟","mereka masuk"],["عَلَىٰ","ke atas"],["دَاوُۥدَ","Dawood"],["فَفَزِعَ","dan dia takut"],["مِنْهُمْ ۖ","daripada mereka"],["قَالُوا۟","mereka berkata"],["لَا","Jangan"],["تَخَفْ ۖ","bertakwa"],["خَصْمَانِ","(Kami adalah) dua orang yang berperkara"],["بَغَىٰ","telah melakukan kesalahan"],["بَعْضُنَا","salah seorang daripada kami"],["عَلَىٰ","kepada"],["بَعْضٍۢ","yang lain"],["فَٱحْكُم","jadi hakim"],["بَيْنَنَا","antara kita"],["بِٱلْحَقِّ","dalam kebenaran"],["وَلَا","dan jangan"],["تُشْطِطْ","bersikap tidak adil"],["وَٱهْدِنَآ","dan membimbing kami"],["إِلَىٰ","kepada"],["سَوَآءِ","genap"],["ٱلصِّرَٰطِ","[the] jalan"]]],"3993":["(Sesungguhnya saudaraku ini) maksudnya, saudara seagamaku ini (mempunyai sembilan puluh sembilan ekor kambing) ini sebagai kata kiasan dari istri (dan aku mempunyai seekor saja. Maka dia berkata, 'Serahkanlah kambing itu kepadaku) yakni jadikanlah aku sebagai suaminya (dan dia mengalahkan aku) atau dia menang atas diriku (dalam perdebatan'\") yakni dalam sengketa ini, dan lawannya pun mengalah.",[["إِنَّ","Sesungguhnya"],["هَـٰذَآ","ini"],["أَخِى","(ialah) saudara aku"],["لَهُۥ","dia ada"],["تِسْعٌۭ","sembilan puluh sembilan"],["وَتِسْعُونَ","sembilan puluh sembilan"],["نَعْجَةًۭ","kambing betina"],["وَلِىَ","sedangkan aku ada"],["نَعْجَةٌۭ","betina"],["وَٰحِدَةٌۭ","satu"],["فَقَالَ","jadi katanya"],["أَكْفِلْنِيهَا","Percayakan dia kepada aku"],["وَعَزَّنِى","dan dia mengalahkan aku"],["فِى","dalam"],["ٱلْخِطَابِ","[the] ucapan"]]],"3994":["(Daud berkata, \"Sesungguhnya dia telah berbuat lalim kepadamu dengan meminta kambingmu itu) dengan maksud untuk menggabungkannya (untuk ditambahkan kepada kambingnya. Sesungguhnya kebanyakan dari orang-orang yang berserikat itu) yakni orang-orang yang terlibat dalam satu perserikatan (sebagian mereka berbuat lalim kepada sebagian yang lain, kecuali orang-orang yang beriman dan mengerjakan amal yang saleh; dan amat sedikitlah mereka ini\") huruf Ma di sini untuk mengukuhkan makna sedikit. Lalu kedua malaikat itu naik ke langit dalam keadaan berubah menjadi ujud aslinya seraya berkata, \"Lelaki ini telah memutuskan perkara terhadap dirinya sendiri.\" Sehingga sadarlah Nabi Daud atas kekeliruannya itu. Lalu Allah berfirman, (Dan Daud yakin) yakni merasa yakin (bahwa Kami mengujinya) Kami menimpakan ujian kepadanya, berupa cobaan dalam bentuk cinta kepada perempuan itu (maka ia meminta ampun kepada Rabbnya lalu menyungkur rukuk) maksudnya bersujud (dan bertobat.)",[["قَالَ","Dia berkata"],["لَقَدْ","Sungguh"],["ظَلَمَكَ","dia telah menzalimi kamu"],["بِسُؤَالِ","dengan menuntut"],["نَعْجَتِكَ","kambing betina kamu"],["إِلَىٰ","kepada"],["نِعَاجِهِۦ ۖ","kambing betinanya"],["وَإِنَّ","Dan sesungguhnya"],["كَثِيرًۭا","ramai"],["مِّنَ","daripada"],["ٱلْخُلَطَآءِ","rakan kongsi"],["لَيَبْغِى","sudah tentu menindas"],["بَعْضُهُمْ","sebahagian mereka"],["عَلَىٰ","[pada]"],["بَعْضٍ","yang lain"],["إِلَّا","kecuali"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["وَقَلِيلٌۭ","dan sedikit"],["مَّا","(adalah) mereka"],["هُمْ ۗ","(adalah) mereka"],["وَظَنَّ","Dan menjadi pasti"],["دَاوُۥدُ","Dawood"],["أَنَّمَا","bahawa"],["فَتَنَّـٰهُ","Kami (telah) mencubanya"],["فَٱسْتَغْفَرَ","dan dia meminta ampun"],["رَبَّهُۥ","(dari) Tuhannya"],["وَخَرَّ","dan jatuh"],["رَاكِعًۭا","tunduk"],["وَأَنَابَ ۩","dan bertaubat"]]],"3995":["(Maka Kami ampuni baginya kesalahannya itu. Dan sesungguhnya dia mempunyai kedudukan dekat pada sisi Kami) yakni dengan ditambahkan kebaikan baginya di dunia (dan tempat kembali yang baik) kelak di akhirat.",[["فَغَفَرْنَا","Maka Kami ampunkan"],["لَهُۥ","baginya"],["ذَٰلِكَ ۖ","bahawa"],["وَإِنَّ","Dan sesungguhnya"],["لَهُۥ","baginya"],["عِندَنَا","dengan Kami"],["لَزُلْفَىٰ","pastinya adalah akses yang dekat"],["وَحُسْنَ","dan yang baik"],["مَـَٔابٍۢ","tempat pulang"]]],"3996":["(Hai Daud, sesungguhnya Kami menjadikan kamu khalifah penguasa di muka bumi) yaitu sebagai penguasa yang mengatur perkara manusia (maka berilah keputusan perkara di antara manusia dengan adil dan janganlah kamu mengikuti hawa nafsu) kemauan hawa nafsu (karena ia akan menyesatkan kamu dari jalan Allah) dari bukti-bukti yang menunjukkan keesaan-Nya. (Sesungguhnya orang-orang yang sesat dari jalan Allah) dari iman kepada Allah (mereka akan mendapat siksa yang berat karena mereka melupakan) artinya, disebabkan mereka lupa akan (hari perhitungan) hal ini ditunjukkan oleh sikap mereka yang tidak mau beriman, seandainya mereka beriman dengan adanya hari perhitungan itu, niscaya mereka akan beriman kepada Allah sewaktu mereka di dunia.",[["يَـٰدَاوُۥدُ","Wahai Daud"],["إِنَّا","Sesungguhnya Kami"],["جَعَلْنَـٰكَ","[Kami] telah menjadikan kamu"],["خَلِيفَةًۭ","seorang naib"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَٱحْكُم","jadi hakim"],["بَيْنَ","antara"],["ٱلنَّاسِ","[the] lelaki"],["بِٱلْحَقِّ","dalam kebenaran"],["وَلَا","dan jangan"],["تَتَّبِعِ","ikut"],["ٱلْهَوَىٰ","keinginan itu"],["فَيُضِلَّكَ","kerana ia akan menyesatkan kamu"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ ۚ","(milik) Allah"],["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَضِلُّونَ","sesat"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["لَهُمْ","bagi mereka"],["عَذَابٌۭ","(ialah) azab"],["شَدِيدٌۢ","teruk"],["بِمَا","kerana"],["نَسُوا۟","mereka lupa"],["يَوْمَ","(the) Hari"],["ٱلْحِسَابِ","(daripada) Akaun"]]],"3997":["(Dan Kami tidak menciptakan langit dan bumi dan apa yang ada di antara keduanya dengan batil) dengan main-main. (Yang demikian itu) yakni penciptaan hal tersebut tanpa hikmah (adalah anggapan orang-orang kafir) dari penduduk Mekah (maka neraka Waillah) Wail adalah nama sebuah lembah di neraka (bagi orang-orang yang kafir karena mereka akan masuk neraka.)",[["وَمَا","Dan tidak"],["خَلَقْنَا","Kami mencipta"],["ٱلسَّمَآءَ","syurga itu"],["وَٱلْأَرْضَ","dan bumi"],["وَمَا","dan apa sahaja"],["بَيْنَهُمَا","(adalah) di antara mereka"],["بَـٰطِلًۭا ۚ","tanpa tujuan"],["ذَٰلِكَ","Itu"],["ظَنُّ","(adalah) andaian"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟ ۚ","kufur"],["فَوَيْلٌۭ","jadi celaka"],["لِّلَّذِينَ","kepada mereka"],["كَفَرُوا۟","yang kufur"],["مِنَ","daripada"],["ٱلنَّارِ","neraka"]]],"3998":["(Patutkah Kami menganggap orang-orang yang beriman dan mengerjakan amal yang saleh sama dengan orang-orang yang berbuat kerusakan di muka bumi? Patutkah pula Kami menganggap orang-orang yang bertakwa sama dengan orang-orang yang berbuat maksiat?) Ayat ini diturunkan sewaktu orang-orang kafir Mekah berkata kepada orang-orang yang beriman, \"Sesungguhnya kami kelak di hari kemudian akan diberi seperti apa yang diberikan kepada kalian.\" Lafal Am di sini untuk menunjukkan makna sanggahan, yakni jelas tidak sama.",[["أَمْ","Atau"],["نَجْعَلُ","patutkah Kita layan"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["كَٱلْمُفْسِدِينَ","seperti mereka yang menyebarkan rasuah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["أَمْ","Atau"],["نَجْعَلُ","patutkah Kita layan"],["ٱلْمُتَّقِينَ","yang soleh"],["كَٱلْفُجَّارِ","seperti orang jahat"]]],"3999":["(Ini adalah sebuah Kitab) menjadi Khabar dari Mubtada yang tidak disebutkan, yakni, Ini adalah Kitab (yang Kami turunkan kepadamu penuh dengan berkah supaya mereka memperhatikan) asal lafal Yaddabbaruu adalah Yatadabbaruu, kemudian huruf Ta diidghamkan kepada huruf Dal sehingga jadilah Yaddabbaruu (ayat-ayatnya) maksudnya supaya mereka memperhatikan makna-makna yang terkandung di dalamnya, lalu mereka beriman karenanya (dan supaya mendapat pelajaran) mendapat nasihat (orang-orang yang mempunyai pikiran) yaitu yang berakal.",[["كِتَـٰبٌ","(Ini adalah) sebuah Kitab"],["أَنزَلْنَـٰهُ","Kami telah mendedahkannya"],["إِلَيْكَ","kepada kamu"],["مُبَـٰرَكٌۭ","diberkati"],["لِّيَدَّبَّرُوٓا۟","supaya mereka renungkan"],["ءَايَـٰتِهِۦ","(di atas) Ayat-ayatnya"],["وَلِيَتَذَكَّرَ","dan boleh diingatkan"],["أُو۟لُوا۟","mereka yang memahami"],["ٱلْأَلْبَـٰبِ","mereka yang memahami"]]],"4000":["(Dan Kami karuniakan kepada Daud, Sulaiman) sebagai anaknya (dia adalah sebaik-baik hamba) maksudnya Sulaiman adalah sebaik-baik hamba. (Sesungguhnya dia amat taat) kepada Rabbnya, selalu bertasbih dan berzikir pada semua waktunya.",[["وَوَهَبْنَا","Dan Kami berikan"],["لِدَاوُۥدَ","kepada Dawud"],["سُلَيْمَـٰنَ ۚ","Sulaiman"],["نِعْمَ","yang cemerlang"],["ٱلْعَبْدُ ۖ","hamba"],["إِنَّهُۥٓ","Sesungguhnya dia"],["أَوَّابٌ","(adalah) seorang yang berulang kali berpaling"]]],"4001":["(Ingatlah ketika dipertunjukkan kepadanya di waktu sore) yakni sesudah matahari tergelincir (kuda-kuda yang tenang di waktu berhenti) lafal Ash-Shaafinaat adalah bentuk jamak dari lafal Shaafinah, artinya kuda yang kalau berhenti berdiri pada tiga kaki, sedangkan kaki yang keempatnya berdiri pada ujung teracaknya atau berjinjit. Lafal ini berasal dari kata Shafana Yashfinu Shufuunan (dan cepat pada waktu berlari) lafal Al-Jiyaad adalah bentuk jamak dari lafal Jawaadun, artinya kuda balap. Maksud ayat, bahwa kuda-kuda itu bila berhenti tenang, dan bila berlari sangat cepat. Tersebutlah bahwa Nabi Sulaiman memiliki seribu ekor kuda, kuda-kuda itu ditampilkan di hadapannya setelah ia selesai melakukan salat Zuhur, karena ia bermaksud untuk berjihad dengan memakai kuda sebagai kendaraannya untuk melawan musuh. Sewaktu penampilan kuda baru sampai sembilan ratus ekor ternyata waktu Magrib telah tiba, sedangkan ia belum melakukan salat asar. Hal ini membuatnya berduka cita.",[["إِذْ","Apabila"],["عُرِضَ","telah dipaparkan"],["عَلَيْهِ","kepadanya"],["بِٱلْعَشِىِّ","pada sebelah petang"],["ٱلصَّـٰفِنَـٰتُ","kuda baka yang sangat baik"],["ٱلْجِيَادُ","kuda baka yang sangat baik"]]],"4002":["(Maka ia berkata, \"Sesungguhnya aku menyukai) artinya, mempunyai maksud (bersenang-senang terhadap barang yang baik) yakni kuda (hingga aku lupa untuk berzikir kepada Rabbku) lupa melakukan salat asar (sehingga tertutuplah) matahari (dari pandangan mata.\") artinya sehingga matahari itu tenggelam dan tidak kelihatan lagi.",[["فَقَالَ","Dan dia berkata"],["إِنِّىٓ","Sesungguhnya aku"],["أَحْبَبْتُ","[Aku] lebih suka"],["حُبَّ","(yang) cinta"],["ٱلْخَيْرِ","(dari) kebaikan"],["عَن","atas"],["ذِكْرِ","(the) zikir"],["رَبِّى","(dari) Tuhanku"],["حَتَّىٰ","Sehinggalah"],["تَوَارَتْ","mereka disembunyikan"],["بِٱلْحِجَابِ","dalam tudung"]]],"4003":["(Ia berkata, \"Bawalah kuda-kuda itu kembali kepadaku\") yaitu kuda-kuda yang ditampilkan tadi kemudian mereka membawanya kepada Nabi Sulaiman (lalu ia membabat kuda-kuda itu) dengan pedangnya (pada kaki-kakinya) lafal As-Suuq ini adalah bentuk jamak dari lafal Saaqun (dan pada lehernya) artinya Nabi Sulaiman menyembelih semua kuda-kuda itu kemudian memotong kakinya sebagai kurban untuk mendekatkan diri kepada Allah swt. Karena kuda-kuda itu ternyata membuatnya lalai dari salat; kemudian ia menyedekahkan daging-dagingnya. Akhirnya Allah menggantikan kudanya dengan kendaraan yang jauh lebih baik dan lebih cepat larinya, yaitu kendaraan angin; angin dapat diperintah untuk bertiup dengan membawanya ke mana saja yang ia kehendaki.",[["رُدُّوهَا","Kembalikan mereka"],["عَلَىَّ ۖ","kepada aku"],["فَطَفِقَ","Kemudian dia mula"],["مَسْحًۢا","(untuk) lulus (tangannya)"],["بِٱلسُّوقِ","atas kaki"],["وَٱلْأَعْنَاقِ","dan leher"]]],"4004":["(Dan sesungguhnya Kami telah menguji Sulaiman) Kami telah mencobanya dengan suatu ujian, yaitu kerajaannya dirampas oleh orang lain. Demikian itu, karena ia pernah menikahi seorang perempuan yang ia sukai, hanya perempuan itu termasuk orang yang menyembah berhala, tanpa sepengetahuan Nabi Sulaiman. Dan tersebutlah bahwa kebesarannya itu terletak pada cincinnya kemudian pada suatu hari ketika ia bermaksud untuk pergi ke kamar mandi, ia melepaskan cincinnya itu. Lalu ia menitipkannya kepada salah seorang dari istrinya yang bernama Aminah, sebagaimana biasanya. Setelah ia pergi tiba-tiba datanglah makhluk jin yang menyerupai Nabi Sulaiman, kemudian jin itu mengambil cincin itu dari Aminah dan langsung memakainya (dan Kami dudukkan pada singgasananya sesosok jasad) yaitu jin tersebut, yang bernama Shakhr atau jin lainnya, kemudian jin itu menduduki singgasana Nabi Sulaiman. Ketika itu juga ia dikelilingi burung-burung dan lain-lainnya. Lalu muncullah Nabi Sulaiman dalam bentuk yang tidak seperti biasanya, yakni tanpa pakaian kebesaran, ia melihat bahwa di singgasananya telah duduk seseorang. Kemudian ia berkata kepada orang-orang yang ada di situ, \"Aku adalah Sulaiman.\" Akan tetapi orang-orang mengingkarinya (kemudian ia kembali) yakni kembali dapat merebut kebesarannya setelah selang beberapa hari; yaitu setelah ia berhasil merebut cincin kebesarannya, lalu memakainya dan duduk di atas singgasananya kembali.",[["وَلَقَدْ","Dan sungguh"],["فَتَنَّا","Kami cuba"],["سُلَيْمَـٰنَ","Sulaiman"],["وَأَلْقَيْنَا","dan Kami letakkan"],["عَلَىٰ","pada"],["كُرْسِيِّهِۦ","takhtanya"],["جَسَدًۭا","sebuah badan"],["ثُمَّ","kemudian"],["أَنَابَ","dia berpaling"]]],"4005":["(Ia berkata, \"Ya Rabbku! Ampunilah aku dan anugerahkanlah kepadaku kerajaan yang tidak patut dimiliki) maksudnya, belum pernah dimiliki (oleh seorang jua pun sesudahku) artinya, yang tidak layak dimiliki oleh orang selainku. Pengertian ungkapan ini sama dengan makna yang terkandung di dalam firman-Nya yang lain, yaitu, 'Maka siapakah yang akan memberinya petunjuk sesudah Allah?' (Q.S. Al-Jatsiyah, 23) yakni selain Allah (sesungguhnya Engkaulah Yang Maha Pemberi.\")",[["قَالَ","Dia berkata"],["رَبِّ","Wahai Tuhanku"],["ٱغْفِرْ","maafkan"],["لِى","aku"],["وَهَبْ","dan pemberian"],["لِى","aku"],["مُلْكًۭا","sebuah kerajaan"],["لَّا","tidak"],["يَنۢبَغِى","(akan) milik"],["لِأَحَدٍۢ","kepada sesiapa sahaja"],["مِّنۢ","selepas aku"],["بَعْدِىٓ ۖ","selepas aku"],["إِنَّكَ","Sesungguhnya, Engkau"],["أَنتَ","[Kamu]"],["ٱلْوَهَّابُ","(adalah) Yang Maha Pemberi"]]],"4006":["(Kemudian Kami tundukkan kepadanya angin yang berembus dengan baik menurut perintahnya) yakni berembus dengan lembut (ke mana saja yang ia kehendaki) sesuai dengan keinginan Nabi Sulaiman.",[["فَسَخَّرْنَا","Kemudian Kami tundukkan"],["لَهُ","kepadanya"],["ٱلرِّيحَ","angin"],["تَجْرِى","mengalir"],["بِأَمْرِهِۦ","dengan perintahnya"],["رُخَآءً","dengan lembut"],["حَيْثُ","di mana sahaja"],["أَصَابَ","dia mengarah"]]],"4007":["(Dan Kami tundukkan pula kepadanya setan-setan, semuanya ahli bangunan) yakni pandai membuat bangunan-bangunan yang menakjubkan dan aneh (dan penyelam) ahli menyelam di dalam laut untuk mengambil mutiara-mutiara yang terkandung di dalamnya.",[["وَٱلشَّيَـٰطِينَ","Dan syaitan"],["كُلَّ","setiap"],["بَنَّآءٍۢ","pembina"],["وَغَوَّاصٍۢ","dan penyelam"]]],"4008":["(Dan setan yang lain) setan-setan yang lainnya (yang terikat) dirantai (dalam belenggu) yaitu, tangan mereka masing-masing diikatkan ke kepalanya dengan memakai belenggu.",[["وَءَاخَرِينَ","Dan lain-lain"],["مُقَرَّنِينَ","terikat"],["فِى","dalam"],["ٱلْأَصْفَادِ","rantai"]]],"4009":["Dan Kami berfirman kepada Sulaiman (Inilah anugerah Kami; maka berikanlah) maksudnya, berikanlah sebagian daripadanya kepada orang yang kamu sukai (atau tahanlah) maksudnya, tidak memberikannya (dengan tiada pertanggungjawaban) tanpa ada hisab bagimu dalam hal ini.",[["هَـٰذَا","Ini"],["عَطَآؤُنَا","(ialah) hadiah kami"],["فَٱمْنُنْ","jadi beri"],["أَوْ","atau"],["أَمْسِكْ","menahan"],["بِغَيْرِ","tanpa"],["حِسَابٍۢ","akaun"]]],"4010":["(Dan sesungguhnya dia mempunyai kedudukan yang dekat pada sisi Kami dan tempat kembali yang baik) penafsiran ayat ini sebagaimana yang telah lalu.",[["وَإِنَّ","Dan sesungguhnya"],["لَهُۥ","baginya"],["عِندَنَا","dengan Kami"],["لَزُلْفَىٰ","pastinya adalah akses yang dekat"],["وَحُسْنَ","dan yang baik"],["مَـَٔابٍۢ","tempat pulang"]]],"4011":["(Dan ingatlah akan hamba Kami Ayub ketika ia menyeru Rabbnya, \"Sesungguhnya aku) bahwasanya aku (diganggu oleh setan dengan kepayahan) kemudaratan (dan siksaan\") yakni rasa sakit. Nabi Ayub menisbatkan atau mengaitkan hal tersebut kepada setan, sekalipun pada kenyataannya segala sesuatu itu berasal dari Allah swt. Dimaksud sebagai sopan santun Nabi Ayub terhadap Allah.",[["وَٱذْكُرْ","Dan ingat"],["عَبْدَنَآ","hamba kita"],["أَيُّوبَ","Ayyub"],["إِذْ","apabila"],["نَادَىٰ","dia panggil"],["رَبَّهُۥٓ","Tuhannya"],["أَنِّى","Itu [aku]"],["مَسَّنِىَ","(telah) menyentuh aku"],["ٱلشَّيْطَـٰنُ","Syaitan"],["بِنُصْبٍۢ","dengan kesusahan"],["وَعَذَابٍ","dan penderitaan"]]],"4012":["Dikatakan kepada Ayub (\"Hantamkanlah) maksudnya hentakkanlah (kakimu) ke bumi, lalu ia menghantamkannya, setelah itu tiba-tiba mengalirlah mata air dari bekas hentakan kakinya. Kemudian dikatakan pula kepadanya (inilah air untuk mandi) artinya, mandilah kamu dengan air ini (yang dingin, dan untuk minum\") minumlah kamu daripadanya. Segeralah Nabi Ayub mandi dan minum dan hilanglah semua penyakit yang ada di dalam dan di luar tubuhnya.",[["ٱرْكُضْ","mogok"],["بِرِجْلِكَ ۖ","dengan kaki kamu"],["هَـٰذَا","Ini"],["مُغْتَسَلٌۢ","(adalah mata air) untuk mandi"],["بَارِدٌۭ","sejuk"],["وَشَرَابٌۭ","dan minuman"]]],"4013":["(Dan Kami anugerahi dia dengan mengumpulkan kembali keluarganya dan Kami tambahkan kepada mereka sebanyak mereka) maksudnya, Allah menghidupkan kembali anak-anaknya yang telah mati itu, dan menambah pula kepadanya anak lain sejumlah anak yang telah mati itu (sebagai rahmat) sebagai nikmat dan karunia (dari Kami dan pelajaran) nasihat (bagi orang-orang yang mempunyai pikiran) yaitu bagi orang-orang yang berakal.",[["وَوَهَبْنَا","Dan Kami kabulkan"],["لَهُۥٓ","[kepada] dia"],["أَهْلَهُۥ","keluarganya"],["وَمِثْلَهُم","dan seumpama mereka"],["مَّعَهُمْ","bersama mereka"],["رَحْمَةًۭ","sebuah Rahmat"],["مِّنَّا","daripada Kami"],["وَذِكْرَىٰ","dan Peringatan"],["لِأُو۟لِى","bagi mereka yang faham"],["ٱلْأَلْبَـٰبِ","bagi mereka yang faham"]]],"4014":["(Dan ambillah dengan tanganmu seikat rumput) yakni seikat rumput lalang atau seikat ranting-ranting (maka pukullah dengan itu) istrimu, karena Nabi Ayub pernah bersumpah, bahwa ia sungguh akan memukul istrinya sebanyak seratus kali deraan, karena pada suatu hari ia pernah tidak menuruti perintahnya (dan janganlah kamu melanggar sumpah) dengan tidak memukulnya, lalu Nabi Ayub mengambil seratus tangkai kayu Idzkhir atau kayu lainnya, lalu ia memukulkannya sekali pukul kepada istrinya. (Sesungguhnya Kami dapati dia seorang yang sabar. Dialah sebaik-baik hamba) adalah Nabi Ayub. (Sesungguhnya dia amat taat) kepada Allah swt.",[["وَخُذْ","Dan ambil"],["بِيَدِكَ","di tangan kamu"],["ضِغْثًۭا","sekumpulan"],["فَٱضْرِب","dan mogok"],["بِّهِۦ","dengannya"],["وَلَا","dan jangan"],["تَحْنَثْ ۗ","melanggar sumpah (kamu)."],["إِنَّا","Sesungguhnya Kami"],["وَجَدْنَـٰهُ","[Kami] jumpa dia"],["صَابِرًۭا ۚ","sabar"],["نِّعْمَ","yang cemerlang"],["ٱلْعَبْدُ ۖ","hamba"],["إِنَّهُۥٓ","Sesungguhnya dia"],["أَوَّابٌۭ","berulang kali berpaling"]]],"4015":["(Dan ingatlah hamba-hamba Kami; Ibrahim, Ishak dan Yakub yang mempunyai kekuatan) dalam hal beribadah (dan pandangan) yang tajam dalam masalah agama. Menurut suatu qiraat lafal 'Ibaadanaa dibaca 'Abdanaa dalam bentuk Mufrad, sedangkan lafal Ibrahiim merupakan Athaf Bayan baginya, dan lafal-lafal yang sesudahnya diathafkan kepada lafal 'Abdanaa.",[["وَٱذْكُرْ","Dan ingat"],["عِبَـٰدَنَآ","hamba kita"],["إِبْرَٰهِيمَ","Ibrahim"],["وَإِسْحَـٰقَ","dan Ishak"],["وَيَعْقُوبَ","dan Ayyub"],["أُو۟لِى","pemilik"],["ٱلْأَيْدِى","(dari) kekuatan"],["وَٱلْأَبْصَـٰرِ","dan penglihatan"]]],"4016":["(Sesungguhnya Kami telah menyucikan mereka dengan menganugerahkan kepada mereka akhlak yang tinggi) yaitu (selalu mengingatkan manusia kepada negeri akhirat) atau alam akhirat; maksudnya mengingatkan manusia kepada hari akhirat dan menganjurkan mereka untuk beramal baik sebagai bekal untuk menghadapinya. Menurut suatu qiraat dibaca Bikhaalishati Dzikrad Daar yaitu dengan dimudhafkan untuk menunjukkan makna Bayan, atau keterangan.",[["إِنَّآ","Sesungguhnya Kami"],["أَخْلَصْنَـٰهُم","[Kami] memilih mereka"],["بِخَالِصَةٍۢ","untuk eksklusif (kualiti)"],["ذِكْرَى","zikir"],["ٱلدَّارِ","(dari) Rumah"]]],"4017":["(Dan sesungguhnya mereka pada sisi Kami benar-benar termasuk orang-orang pilihan) yakni orang-orang yang terpilih (yang paling baik) lafal Al-Akhyaar ini adalah bentuk jamak dari lafal Khayyirun, artinya paling baik.",[["وَإِنَّهُمْ","Dan sesungguhnya, mereka"],["عِندَنَا","kepada Kami"],["لَمِنَ","(adalah) daripada"],["ٱلْمُصْطَفَيْنَ","yang terpilih"],["ٱلْأَخْيَارِ","yang terbaik"]]],"4018":["(Dan ingatlah akan Ismail, Ilyasa') Ilyasa' adalah Yasu', dia seorang nabi; Huruf Alif dan lamnya adalah Zaidah atau tambahan (dan Zulkifli) yang masih diperselisihkan kenabiannya. Menurut suatu pendapat dikatakan, bahwa ia pernah menjamin seratus orang nabi yang berlindung kepadanya untuk menghindari pembunuhan. (Semuanya) artinya, masing-masing dari kesemuanya (termasuk orang-orang yang paling baik) lafal Al-Akhyaar adalah bentuk jamak dari lafal Khayyirun, artinya orang yang paling baik.",[["وَٱذْكُرْ","Dan ingat"],["إِسْمَـٰعِيلَ","Ismail"],["وَٱلْيَسَعَ","dan Elisa"],["وَذَا","dan Dzulkifli"],["ٱلْكِفْلِ ۖ","dan Dzulkifli"],["وَكُلٌّۭ","dan semua"],["مِّنَ","(adalah) daripada"],["ٱلْأَخْيَارِ","yang terbaik"]]],"4019":["(Ini adalah kehormatan) bagi mereka, yaitu mendapat pujian yang baik di sini. (Dan sesungguhnya bagi orang-orang yang bertakwa) antara lain adalah termasuk mereka (benar-benar disediakan tempat kembali yang baik) nanti di akhirat.",[["هَـٰذَا","Ini"],["ذِكْرٌۭ ۚ","(adalah) Peringatan"],["وَإِنَّ","Dan sesungguhnya"],["لِلْمُتَّقِينَ","untuk orang yang soleh"],["لَحُسْنَ","pasti, adalah satu kebaikan"],["مَـَٔابٍۢ","tempat pulang"]]],"4020":["(Yaitu surga Adn) menjadi Badal atau 'Athaf Bayan bagi lafal Lahusna Ma-aab (yang pintu-pintunya terbuka bagi mereka) artinya, pintu-pintu surga itu terbuka lebar-lebar buat mereka.",[["جَنَّـٰتِ","Taman-taman"],["عَدْنٍۢ","(dari) Keabadian"],["مُّفَتَّحَةًۭ","(akan) dibuka"],["لَّهُمُ","bagi mereka"],["ٱلْأَبْوَٰبُ","pintu pagar"]]],"4021":["(Di dalamnya mereka bertelekan) di atas dipan-dipan (sambil meminta buah-buahan yang banyak dan minuman di surga itu.)",[["مُتَّكِـِٔينَ","Berbaring"],["فِيهَا","di dalamnya"],["يَدْعُونَ","mereka akan memanggil"],["فِيهَا","di dalamnya"],["بِفَـٰكِهَةٍۢ","untuk buah"],["كَثِيرَةٍۢ","ramai"],["وَشَرَابٍۢ","dan minum"]]],"4022":["(Dan pada sisi mereka ada bidadari-bidadari yang tidak liar pandangannya) yakni mereka hanya memandang kepada suaminya dan menundukkan pandangan mata dari yang lainnya (dan sebaya umurnya) umur mereka sebaya, yaitu sekitar tiga puluh tiga tahunan. Lafal Atraabun adalah bentuk jamak dari lafal Turbun.",[["۞ وَعِندَهُمْ","Dan dengan mereka"],["قَـٰصِرَٰتُ","(akan menjadi) teman yang memandang rendah"],["ٱلطَّرْفِ","(akan menjadi) teman yang memandang rendah"],["أَتْرَابٌ","dipadankan dengan baik"]]],"4023":["(Inilah) hal-hal yang telah disebutkan itu (apa yang dijanjikan kepada kalian) dapat dibaca Yuu'aduuna atau Tuu'aduuna, kalau dibaca Tuu'aduna berarti Iltifat (pada hari berhisab) pada saat hari berhisab.",[["هَـٰذَا","Ini"],["مَا","(ialah) apa"],["تُوعَدُونَ","kamu dijanjikan"],["لِيَوْمِ","untuk (hari) itu"],["ٱلْحِسَابِ","(daripada) Akaun"]]],"4024":["(Sesungguhnya ini adalah benar-benar rezeki dari Kami yang tiada habis-habisnya) yang tak putus-putusnya; jumlah ayat ini menjadi Haal dari lafal Larizqunaa, atau sebagai Khabar kedua dari Inna, artinya selama-lamanya.",[["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["لَرِزْقُنَا","(adalah) sesungguhnya rezeki Kami"],["مَا","tidak"],["لَهُۥ","baginya"],["مِن","sebarang"],["نَّفَادٍ","kehabisan"]]],"4025":["(Beginilah) keadaan yang dialami oleh orang-orang yang beriman. (Dan sesungguhnya bagi orang-orang yang durhaka) kalimat ayat ini merupakan jumlah Isti'naf atau kalimat baru (benar-benar disediakan tempat kembali yang paling buruk.)",[["هَـٰذَا ۚ","Ini (begitu)"],["وَإِنَّ","Dan sesungguhnya"],["لِلطَّـٰغِينَ","bagi orang yang melampaui batas"],["لَشَرَّ","sesungguhnya (adalah) kejahatan"],["مَـَٔابٍۢ","tempat pulang"]]],"4026":["(Yaitu neraka Jahanam, yang mereka masuk ke dalamnya) mereka dimasukkan ke dalamnya (maka amat buruklah Jahanam itu sebagai tempat tinggal) artinya, hamparan yang paling buruk.",[["جَهَنَّمَ","Neraka"],["يَصْلَوْنَهَا","mereka akan terbakar di dalamnya"],["فَبِئْسَ","dan celaka (adalah)"],["ٱلْمِهَادُ","tempat berehat"]]],"4027":["(Inilah) azab neraka; pengertian ini disimpulkan dari lafal sesudahnya (biarlah mereka merasakannya, minuman mereka air yang sangat panas) lagi membakar (dan nanah ahli neraka) dapat dibaca Ghassaaqun atau Ghasaaqun artinya nanah yang meleleh dari penghuni neraka.",[["هَـٰذَا","Ini (begitu)"],["فَلْيَذُوقُوهُ","Kemudian biarkan mereka merasainya"],["حَمِيمٌۭ","cecair mendidih"],["وَغَسَّاقٌۭ","dan purulen"]]],"4028":["(Dan azab yang lain) dapat dibaca dalam bentuk jamak sehingga menjadi Ukharu atau dapat pula dibaca dalam bentuk Mufrad sehingga bacaannya menjadi Aakharu (yang serupa itu) serupa dengan azab yang telah disebutkan tadi, yaitu air yang sangat panas dan cairan nanah (berbagai macam) beraneka ragam siksaan, maksudnya, azab mereka bermacam-macam.",[["وَءَاخَرُ","Dan lain-lain"],["مِن","daripada"],["شَكْلِهِۦٓ","jenisnya"],["أَزْوَٰجٌ","(pelbagai) jenis"]]],"4029":["Dan dikatakan kepada mereka sewaktu mereka diseret ke dalam neraka bersama dengan para pengikutnya (\"Ini adalah suatu rombongan) suatu gelombang (yang masuk berdesak-desak) dijejalkan masuk (bersama kalian\") ke neraka. Kalimat itu dikatakan kepada mereka dengan nada yang keras; maka berkatalah pemimpin-pemimpin mereka yang durhaka, (\"Tiadalah ucapan selamat datang kepada mereka) artinya, tiada kelapangan buat mereka (karena sesungguhnya mereka akan masuk neraka.\")",[["هَـٰذَا","Ini"],["فَوْجٌۭ","(ialah) sebuah syarikat"],["مُّقْتَحِمٌۭ","pecah"],["مَّعَكُمْ ۖ","(dalam) dengan kamu"],["لَا","Tidak"],["مَرْحَبًۢا","selamat datang"],["بِهِمْ ۚ","bagi mereka"],["إِنَّهُمْ","Sesungguhnya mereka"],["صَالُوا۟","(akan) terbakar"],["ٱلنَّارِ","(dalam) api"]]],"4030":["(Pengikut-pengikut mereka berkata) atau mengatakan, (\"Sebenarnya kalianlah; tiada ucapan selamat datang bagi kalian, karena kalianlah yang menjerumuskan kami) ke dalam kekafiran (maka amat buruklah tempat tinggal\") bagi kami dan kalian, yaitu neraka.",[["قَالُوا۟","Mereka berkata"],["بَلْ","Bahkan"],["أَنتُمْ","kamu"],["لَا","tidak"],["مَرْحَبًۢا","selamat datang"],["بِكُمْ ۖ","bagi kamu"],["أَنتُمْ","kamu"],["قَدَّمْتُمُوهُ","membawa ini"],["لَنَا ۖ","atas kita"],["فَبِئْسَ","Sungguh celaka (adalah)"],["ٱلْقَرَارُ","penempatan itu"]]],"4031":["(Mereka berkata) lagi, (\"Ya Rabb kami! Barang siapa yang menjerumuskan kami ke dalam azab ini, maka tambahkanlah azab kepadanya dengan berlipat ganda) dua kali lipat azab yang diterimanya, sebagai balasan dari kekafirannya (di dalam neraka.\")",[["قَالُوا۟","Mereka akan berkata"],["رَبَّنَا","Wahai Tuhan kami"],["مَن","sesiapa sahaja"],["قَدَّمَ","dibawa"],["لَنَا","atas kita"],["هَـٰذَا","ini"],["فَزِدْهُ","bertambah untuknya"],["عَذَابًۭا","azab"],["ضِعْفًۭا","berganda"],["فِى","dalam"],["ٱلنَّارِ","neraka"]]],"4032":["(Dan mereka berkata,) yakni orang-orang kafir Mekah, sedang mereka berada dalam neraka, (\"Mengapa kami tidak melihat orang-orang yang dahulu kami anggap) sewaktu di dunia (sebagai orang-orang yang hina.\")",[["وَقَالُوا۟","Dan mereka (akan) berkata"],["مَا","Apakah (ada)"],["لَنَا","bagi kami"],["لَا","tidak"],["نَرَىٰ","kita nampak"],["رِجَالًۭا","lelaki"],["كُنَّا","kita dulu"],["نَعُدُّهُم","mengira mereka"],["مِّنَ","antara"],["ٱلْأَشْرَارِ","yang buruk"]]],"4033":["(Apakah kami dahulu menjadikan mereka olok-olokan) lafal Sukhriyyan dapat pula dibaca Sikhriyyan, yakni kami dahulu sewaktu di dunia menghina mereka. Huruf Ya pada lafal Sukhriyyan adalah Nasab; maksudnya apakah mereka tidak ada (ataukah karena tidak melihat) yakni terhalang (mata kami dari melihat mereka) sehingga mata kami tidak dapat melihat mereka. Yang mereka maksud adalah kaum muslimin yang miskin, seperti Ammar, Bilal, Shuhaib, dan Salman.",[["أَتَّخَذْنَـٰهُمْ","Adakah kita mengambil mereka"],["سِخْرِيًّا","(dalam) ejekan"],["أَمْ","atau"],["زَاغَتْ","telah berpaling"],["عَنْهُمُ","daripada mereka"],["ٱلْأَبْصَـٰرُ","penglihatan itu"]]],"4034":["(Sesungguhnya yang demikian itu pasti terjadi) sudah pasti terjadinya, yaitu (pertengkaran penghuni neraka) sebagaimana yang telah dijelaskan tadi.",[["إِنَّ","Sesungguhnya"],["ذَٰلِكَ","bahawa"],["لَحَقٌّۭ","sesungguhnya (adalah) kebenaran"],["تَخَاصُمُ","(yang) bergaduh"],["أَهْلِ","(daripada) orang ramai"],["ٱلنَّارِ","(dari) api"]]],"4035":["(Katakanlah) hai Muhammad kepada orang-orang kafir Mekah! (\"Sesungguhnya aku hanya seorang pemberi peringatan) seorang yang memperingatkan kalian dengan neraka (dan sekali-kali tidak ada Tuhan selain Allah Yang Maha Esa lagi Maha Mengalahkan) semua makhluk-Nya.",[["قُلْ","Katakanlah"],["إِنَّمَآ","Hanya"],["أَنَا۠","aku"],["مُنذِرٌۭ ۖ","seorang pemberi amaran"],["وَمَا","dan bukan"],["مِنْ","(ada) ada"],["إِلَـٰهٍ","tuhan"],["إِلَّا","kecuali"],["ٱللَّهُ","Allah"],["ٱلْوَٰحِدُ","yang Satu"],["ٱلْقَهَّارُ","yang tak tertahan"]]],"4036":["(Rabb langit dan bumi dan apa yang ada di antara keduanya Yang Maha Perkasa) yakni Maha Menang atas semua perkara-Nya (lagi Maha Pengampun\") terhadap kekasih-kekasih-Nya.",[["رَبُّ","Tuhan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَمَا","dan apa sahaja"],["بَيْنَهُمَا","(adalah) di antara mereka"],["ٱلْعَزِيزُ","Yang Maha Perkasa"],["ٱلْغَفَّـٰرُ","Yang Maha Pengampun"]]],"4037":["(Katakanlah) kepada mereka! (\"Berita itu adalah berita besar.)",[["قُلْ","Katakanlah"],["هُوَ","Ia (adalah)"],["نَبَؤٌا۟","sebuah berita"],["عَظِيمٌ","yang besar"]]],"4038":["(Yang kalian berpaling darinya) dari Alquran yang aku beritakan dan aku datangkan kepada kalian; di dalamnya terdapat hal-hal yang tidak dapat diketahui, melainkan hanya dengan jalan wahyu. Yang dimaksud dengan berita yang besar itu ialah:",[["أَنتُمْ","kamu"],["عَنْهُ","daripadanya"],["مُعْرِضُونَ","berpaling"]]],"4039":["(Aku tiada mempunyai pengetahuan sedikit pun tentang Al-Mala'ul A'la) yakni para malaikat itu (ketika mereka berbantah-bantahan) tentang perihal Nabi Adam, ketika Allah berfirman, 'Sesungguhnya Aku hendak menjadikan seorang khalifah di muka bumi...' (Q.S. Al-Baqarah, 30)",[["مَا","Tidak"],["كَانَ","ialah"],["لِىَ","untuk aku"],["مِنْ","sebarang"],["عِلْمٍۭ","pengetahuan"],["بِٱلْمَلَإِ","(dari) ketua-ketua"],["ٱلْأَعْلَىٰٓ","yang ditinggikan"],["إِذْ","apabila"],["يَخْتَصِمُونَ","mereka mempertikaikan"]]],"4040":["(Tidak) tiada (diwahyukan kepadaku, melainkan bahwa sesungguhnya aku) yakni aku ini (hanyalah seorang pemberi peringatan yang nyata\") artinya nyata peringatannya.",[["إِن","Tidak"],["يُوحَىٰٓ","telah didedahkan"],["إِلَىَّ","kepada aku"],["إِلَّآ","kecuali"],["أَنَّمَآ","itu sahaja"],["أَنَا۠","aku"],["نَذِيرٌۭ","seorang pemberi amaran"],["مُّبِينٌ","yang nyata"]]],"4041":["Ingatlah (ketika Rabbmu berfirman kepada malaikat, \"Sesungguhnya Aku akan menciptakan manusia dari tanah) yaitu Adam.",[["إِذْ","Apabila"],["قَالَ","berkata"],["رَبُّكَ","Tuhanmu"],["لِلْمَلَـٰٓئِكَةِ","kepada para Malaikat"],["إِنِّى","Sesungguhnya, Aku"],["خَـٰلِقٌۢ","akan mencipta"],["بَشَرًۭا","seorang manusia"],["مِّن","daripada"],["طِينٍۢ","tanah liat"]]],"4042":["(Maka apabila telah Kusempurnakan kejadiannya) telah sempurna kejadiannya (dan Kutiupkan) Kualirkan (kepadanya roh ciptaan-Ku) sehingga ia menjadi hidup. Dimudhafkannya lafal ruh kepada Allah dimaksud untuk memuliakan Nabi Adam. Roh adalah tubuh yang lembut dan tidak kelihatan oleh mata, yang membuat manusia dapat hidup karena memasuki tubuhnya (maka hendaklah kalian bersungkur dengan sujud kepadanya\") sujud penghormatan dengan cara membungkukkan badan.",[["فَإِذَا","Maka apabila"],["سَوَّيْتُهُۥ","Aku telah membahagikan dia"],["وَنَفَخْتُ","dan bernafas"],["فِيهِ","ke dalam dia"],["مِن","daripada"],["رُّوحِى","semangat aku"],["فَقَعُوا۟","kemudian jatuh ke bawah"],["لَهُۥ","kepadanya"],["سَـٰجِدِينَ","sujud"]]],"4043":["(Lalu seluruh malaikat itu sujud semuanya) di dalam ayat ini terdapat dua Taukid, yaitu lafal Kulluhum dan lafal Ajma 'uuna.",[["فَسَجَدَ","Jadi sujud"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["كُلُّهُمْ","kesemuanya"],["أَجْمَعُونَ","bersama-sama"]]],"4044":["(Kecuali iblis) dia adalah bapaknya jin yang dahulunya campur bersama dengan malaikat (dia menyombongkan diri dan adalah dia termasuk orang-orang yang kafir) menurut ilmu Allah.",[["إِلَّآ","Kecuali"],["إِبْلِيسَ","Iblis"],["ٱسْتَكْبَرَ","dia sombong"],["وَكَانَ","dan menjadi"],["مِنَ","daripada"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"4045":["(Allah berfirman, \"Hai iblis! Apakah yang menghalangi kamu sujud kepada yang telah Kuciptakan dengan kedua tangan kekuasaan-Ku?) maksudnya, yang telah Aku atur penciptaannya secara langsung; ungkapan ini dimaksud memuliakan kedudukan Nabi Adam, karena sesungguhnya setiap makhluk diciptakan oleh Allah secara langsung. (Apakah kamu menyombongkan diri) sekarang sehingga kamu tidak mau bersujud kepadanya; Istifham atau kata tanya di sini menunjukkan makna cemoohan (ataukah kamu merasa termasuk orang-orang yang lebih tinggi?\") merasa tinggi diri sehingga kamu bersikap takabur tidak mau bersujud.",[["قَالَ","Dia berkata"],["يَـٰٓإِبْلِيسُ","Wahai Iblis"],["مَا","Apa"],["مَنَعَكَ","menghalang kamu"],["أَن","bahawa"],["تَسْجُدَ","kamu (hendaklah) sujud"],["لِمَا","kepada (satu) siapa"],["خَلَقْتُ","aku cipta"],["بِيَدَىَّ ۖ","dengan Tangan-Ku"],["أَسْتَكْبَرْتَ","Adakah kamu sombong"],["أَمْ","atau"],["كُنتَ","adakah kamu"],["مِنَ","daripada"],["ٱلْعَالِينَ","yang ditinggikan"]]],"4046":["(Iblis berkata, \"Aku lebih baik daripadanya, karena Engkau ciptakan aku dari api, sedangkan dia Engkau ciptakan dari tanah.\")",[["قَالَ","Dia berkata"],["أَنَا۠","aku"],["خَيْرٌۭ","lebih baik"],["مِّنْهُ ۖ","daripada dia"],["خَلَقْتَنِى","Kamu cipta aku"],["مِن","daripada"],["نَّارٍۢ","kebakaran"],["وَخَلَقْتَهُۥ","dan Engkau ciptakan dia"],["مِن","daripada"],["طِينٍۢ","tanah liat"]]],"4047":["(Allah berfirman, \"Maka keluarlah kamu dari surga) menurut pendapat yang lain dari langit (sesungguhnya kamu adalah orang yang diusir) yang terusir.",[["قَالَ","Dia berkata"],["فَٱخْرُجْ","Lepas tu keluar"],["مِنْهَا","daripadanya"],["فَإِنَّكَ","kerana sesungguhnya, kamu"],["رَجِيمٌۭ","(adalah) terkutuk"]]],"4048":["(Sesungguhnya kutukan-Ku tetap atasmu sampai hari pembalasan\") yakni hari Allah melakukan pembalasan.",[["وَإِنَّ","Dan sesungguhnya"],["عَلَيْكَ","ke atas kamu"],["لَعْنَتِىٓ","(ialah) sumpahan aku"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["ٱلدِّينِ","(dari) Penghakiman"]]],"4049":["(Iblis berkata, \"Ya Rabbku! Berilah aku tenggang waktu sampai hari mereka dibangkitkan\") sampai manusia dibangkitkan.",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["فَأَنظِرْنِىٓ","Kemudian beri aku tangguh"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["يُبْعَثُونَ","mereka dibangkitkan"]]],"4050":["(Allah berfirman, \"Sesungguhnya kamu termasuk orang-orang yang diberi tangguh.)",[["قَالَ","Dia berkata"],["فَإِنَّكَ","Kemudian sesungguhnya, kamu"],["مِنَ","(adalah) daripada"],["ٱلْمُنظَرِينَ","mereka yang diberi kelonggaran"]]],"4051":["(Sampai kepada hari yang telah ditentukan waktunya\") yakni waktu tiupan sangkakala yang pertama atau hari kiamat.",[["إِلَىٰ","Sehinggalah"],["يَوْمِ","(the) Hari"],["ٱلْوَقْتِ","(dari) masa"],["ٱلْمَعْلُومِ","terkenal"]]],"4052":["(Iblis menjawab, \"Demi kekuasaan Engkau, aku akan menyesatkan mereka semuanya).",[["قَالَ","Dia berkata"],["فَبِعِزَّتِكَ","Kemudian dengan kuasa-Mu"],["لَأُغْوِيَنَّهُمْ","Aku pasti akan menyesatkan mereka"],["أَجْمَعِينَ","semua"]]],"4053":["(Kecuali hamba-hamba-Mu yang mukhlis di antara mereka\") yakni orang-orang yang beriman.",[["إِلَّا","Kecuali"],["عِبَادَكَ","hambamu"],["مِنْهُمُ","antara mereka"],["ٱلْمُخْلَصِينَ","yang terpilih"]]],"4054":["(Allah berfirman, \"Maka yang benar adalah sumpah-Ku dan hanya kebenaran itulah yang Kukatakan\") dapat dibaca Falhaqqa Wal Haqqa atau Falhaqqu Wal Haqqa; kalau dibaca Nashab berarti dinashabkan oleh Fi'il yang sesudahnya. Bila lafal pertama dinashabkan, menurut suatu pendapat dikatakan, bahwa dinashabkan oleh Fi'll yang telah disebutkan. Menurut pendapat yang lainnya lagi dinashabkan karena menjadi Mashdar, bentuk asalnya adalah Uhiqqal Haqqa. Menurut pendapat yang lainnya lagi karena huruf Qasamnya dicabut. Dibaca Rafa' atas dasar karena menjadi Mubtada yang dibuang Khabarnya, bentuk asalnya adalah Falhaqqu Minnii. Menurut pendapat yang lainnya lagi bentuk asalnya adalah, Falhaqqu Qasami, dan jawab Qasamnya ialah kalimat berikutnya, yaitu:",[["قَالَ","Dia berkata"],["فَٱلْحَقُّ","Maka (ialah) kebenaran"],["وَٱلْحَقَّ","dan kebenaran"],["أَقُولُ","aku cakap"]]],"4055":["(Sesungguhnya Aku pasti akan memenuhi neraka Jahanam dengan jenis kamu) berikut keturunanmu (dan dengan orang-orang yang mengikuti kamu di antara mereka) yakni umat manusia (semuanya.)",[["لَأَمْلَأَنَّ","Pasti aku akan penuhkan"],["جَهَنَّمَ","Neraka"],["مِنكَ","bersama kamu"],["وَمِمَّن","dan orang yang"],["تَبِعَكَ","ikut kamu"],["مِنْهُمْ","antara mereka"],["أَجْمَعِينَ","semua"]]],"4056":["(Katakanlah! \"Aku tidak meminta kepada kalian atas hal ini) atas penyampaian risalah ini (upah sedikit pun) persenan sedikit pun dari kalian (dan bukanlah aku termasuk orang-orang yang mengada-adakan) maksudnya, membuat-buat Alquran dari diriku sendiri.",[["قُلْ","Katakanlah"],["مَآ","Tidak"],["أَسْـَٔلُكُمْ","Aku bertanya kepada kamu"],["عَلَيْهِ","baginya"],["مِنْ","sebarang"],["أَجْرٍۢ","bayaran"],["وَمَآ","dan bukan"],["أَنَا۠","aku"],["مِنَ","daripada"],["ٱلْمُتَكَلِّفِينَ","mereka yang berpura-pura"]]],"4057":["(Tiada lain ini) Alquran ini (hanyalah peringatan) yakni nasihat dan peringatan (bagi semesta alam) maksudnya bagi jenis manusia, jin dan makhluk-makhluk yang berakal selain malaikat.",[["إِنْ","Tidak"],["هُوَ","ia (adalah)"],["إِلَّا","kecuali"],["ذِكْرٌۭ","satu Peringatan"],["لِّلْعَـٰلَمِينَ","kepada dunia"]]],"4058":["(Dan sesungguhnya kalian akan mengetahui) hai orang-orang kafir Mekah (berita Alquran) yaitu berita kebenarannya (setelah beberapa waktu lagi\") yakni pada hari kiamat nanti. Lafal 'Alima bermakna 'Arafa yakni mengetahui. Huruf Lam sebelumnya adalah Lam Qasam bagi lafal yang diperkirakan, bentuk asalnya adalah, Wallaahi Lata'lamunna.",[["وَلَتَعْلَمُنَّ","Dan pasti kamu akan tahu"],["نَبَأَهُۥ","maklumatnya"],["بَعْدَ","selepas"],["حِينٍۭ","suatu masa"]]],"4059":["(Turunnya Kitab ini) yakni Alquran; berkedudukan sebagai Mubtaba (dari Allah) berkedudukan sebagai Khabar dari Mubtada (Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) dalam tindakan-Nya.",[["تَنزِيلُ","(The) wahyu"],["ٱلْكِتَـٰبِ","Kitab"],["مِنَ","(adalah) daripada"],["ٱللَّهِ","Allah"],["ٱلْعَزِيزِ","Yang Maha Perkasa"],["ٱلْحَكِيمِ","Yang Maha Bijaksana"]]],"4060":["(Sesungguhnya Kami menurunkan kepadamu) hai Muhammad (Kitab Alquran dengan membawa kebenaran) lafal Bilhaqqi berta'alluq kepada lafal Anzalnaa. (Maka sembahlah Allah dengan memurnikan ketaatan kepada-Nya) yakni dari kemusyrikan, maksudnya mentauhidkan-Nya.",[["إِنَّآ","Sesungguhnya Kami"],["أَنزَلْنَآ","[Kami] telah mendedahkan"],["إِلَيْكَ","kepada kamu"],["ٱلْكِتَـٰبَ","Kitab"],["بِٱلْحَقِّ","dalam kebenaran"],["فَٱعْبُدِ","jadi ibadah"],["ٱللَّهَ","Allah"],["مُخْلِصًۭا","(bersifat) ikhlas"],["لَّهُ","kepada-Nya"],["ٱلدِّينَ","(dalam) agama"]]],"4061":["(Ingatlah, hanya kepada Allahlah ketaatan yang murni itu) tiada seorang pun yang berhak menerimanya selain-Nya. (Dan orang-orang yang mengambil selain-Nya) yang mengambil berhala-berhala (sebagai pelindung) mereka adalah orang-orang kafir Mekah yang mengatakan, (\"Kami tidak menyembah mereka melainkan supaya mereka mendekatkan kami kepada Allah dengan sedekat-dekatnya.\") yakni untuk mendekatkan diri kami kepada-Nya. Lafal Zulfaa adalah Mashdar yang maknanya sama dengan lafal Taqriiban/mendekatkan diri. (Sesungguhnya Allah akan memutuskan di antara mereka) dan kaum Muslimin (tentang apa yang mereka berselisih padanya) tentang masalah agama, maka kelak orang-orang yang beriman akan masuk surga dan orang-orang yang kafir akan masuk neraka. (Sesungguhnya Allah tidak menunjuki orang yang pendusta) yaitu orang yang mengatakan terhadap Allah, bahwa Dia mempunyai anak (lagi sangat ingkar) karena menyembah kepada selain-Nya.",[["أَلَا","Tidak dinafikan"],["لِلَّهِ","kerana Allah"],["ٱلدِّينُ","(ialah) agama"],["ٱلْخَالِصُ ۚ","yang suci"],["وَٱلَّذِينَ","Dan orang yang"],["ٱتَّخَذُوا۟","ambil"],["مِن","selain Dia"],["دُونِهِۦٓ","selain Dia"],["أَوْلِيَآءَ","pelindung"],["مَا","Tidak"],["نَعْبُدُهُمْ","kita menyembah mereka"],["إِلَّا","kecuali"],["لِيُقَرِّبُونَآ","supaya mereka mendekatkan kita"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["زُلْفَىٰٓ","(dalam) kedekatan"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَحْكُمُ","akan menilai"],["بَيْنَهُمْ","antara mereka"],["فِى","dalam"],["مَا","apa"],["هُمْ","mereka"],["فِيهِ","[di dalamnya]"],["يَخْتَلِفُونَ ۗ","berbeza"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["مَنْ","(satu) siapa"],["هُوَ","[dia]"],["كَـٰذِبٌۭ","(adalah) pembohong"],["كَفَّارٌۭ","dan seorang yang kafir"]]],"4062":["(Kalau sekiranya Allah hendak mengambil anak) seperti apa yang mereka katakan, yaitu sebagaimana yang disitir oleh firman-Nya, \"Tuhan Yang Maha Pemurah telah mengambil (mempunyai) anak...\" (Q.S. Al-Anbiya, 26) (tentu Dia akan memilih apa yang dikehendaki-Nya di antara ciptaan-ciptaan yang diciptakan-Nya) untuk dijadikan-Nya anak; bukan seperti apa yang telah mereka katakan, bahwa para malaikat itu adalah anak-anak perempuan Allah, Uzair itu putra Allah dan juga Al-Masih adalah putra Allah (Maha Suci Allah) kalimat ini memahasucikan-Nya dari mengambil anak (Dialah Allah Yang Maha Esa lagi Maha Mengalahkan) semua makhluk-Nya.",[["لَّوْ","Jika"],["أَرَادَ","Allah (telah) bermaksud"],["ٱللَّهُ","Allah (telah) bermaksud"],["أَن","kepada"],["يَتَّخِذَ","ambil"],["وَلَدًۭا","seorang anak lelaki"],["لَّٱصْطَفَىٰ","sesungguhnya Dia (boleh) memilih"],["مِمَّا","daripada apa"],["يَخْلُقُ","Dia mencipta"],["مَا","apa sahaja"],["يَشَآءُ ۚ","Dia berkehendak"],["سُبْحَـٰنَهُۥ ۖ","Maha Suci Dia"],["هُوَ","Dia"],["ٱللَّهُ","(ialah) Allah"],["ٱلْوَٰحِدُ","yang Satu"],["ٱلْقَهَّارُ","yang tak tertahan"]]],"4063":["(Dia menciptakan langit dan bumi dengan -tujuan- yang benar) lafal Bilhaqqi berta'alluq kepada lafal Khalaqa (Dia menutupkan) yakni memasukkan (malam atas siang) sehingga waktu malam bertambah. (dan menutupkan siang) memasukkannya (atas malam) sehingga waktu siang bertambah (dan Dia menundukkan matahari dan bulan, masing-masing berjalan) pada garis edarnya (hingga waktu yang ditentukan) yakni hari kiamat. (Ingatlah Dialah Yang Maha Perkasa) Yang Maha Menang atas semua perkara-Nya dan Yang Maha Membalas terhadap musuh-musuh-Nya (lagi Maha Pengampun) kepada kekasih-kekasih-Nya.",[["خَلَقَ","Dia cipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["بِٱلْحَقِّ ۖ","dalam kebenaran"],["يُكَوِّرُ","Dia membalut"],["ٱلَّيْلَ","malam"],["عَلَى","atas"],["ٱلنَّهَارِ","hari itu"],["وَيُكَوِّرُ","dan membungkus"],["ٱلنَّهَارَ","hari itu"],["عَلَى","atas"],["ٱلَّيْلِ ۖ","malam"],["وَسَخَّرَ","Dan Dia menundukkan"],["ٱلشَّمْسَ","matahari"],["وَٱلْقَمَرَ ۖ","dan bulan"],["كُلٌّۭ","setiap satu"],["يَجْرِى","berlari"],["لِأَجَلٍۢ","untuk satu penggal"],["مُّسَمًّى ۗ","ditentukan"],["أَلَا","Tidak dinafikan"],["هُوَ","Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْغَفَّـٰرُ","Yang Maha Pengampun"]]],"4064":["(Dia menciptakan kalian dari seorang diri) yaitu dari Nabi Adam (kemudian Dia jadikan daripadanya istrinya) yaitu Siti Hawa (dan Dia menurunkan untuk kalian binatang ternak) yakni unta, sapi, kambing, domba dan biri-biri (sebanyak delapan ekor yang berpasang-pasangan) yakni dari setiap jenis sepasang, yaitu jantan dan betina sebagaimana yang telah dijelaskan dalam surah Al-An'am (Dia menjadikan kalian dalam perut ibu kalian kejadian demi kejadian) yaitu mulai dari air mani, kemudian menjadi segumpal darah, lalu menjadi segumpal daging (dalam tiga kegelapan) yaitu gelapnya perut, gelapnya rahim dan gelapnya selaput pelindung bayi. (Yang berbuat demikian itu adalah Allah, Rabb kalian, Rabb Yang mempunyai kerajaan; tidak ada Tuhan selain Dia, maka bagaimanakah kalian dapat dipalingkan?) dari menyembah kepada-Nya, kemudian kalian menyembah yang lain-Nya.",[["خَلَقَكُم","Dia mencipta kamu"],["مِّن","daripada"],["نَّفْسٍۢ","sebuah jiwa"],["وَٰحِدَةٍۢ","bujang"],["ثُمَّ","Kemudian"],["جَعَلَ","Dia buat"],["مِنْهَا","daripadanya"],["زَوْجَهَا","jodohnya"],["وَأَنزَلَ","Dan Dia menurunkan"],["لَكُم","bagi kamu"],["مِّنَ","daripada"],["ٱلْأَنْعَـٰمِ","lembu itu"],["ثَمَـٰنِيَةَ","lapan"],["أَزْوَٰجٍۢ ۚ","macam-macam"],["يَخْلُقُكُمْ","Dia mencipta kamu"],["فِى","dalam"],["بُطُونِ","(rahim)."],["أُمَّهَـٰتِكُمْ","(dari) ibu kamu"],["خَلْقًۭا","ciptaan"],["مِّنۢ","selepas"],["بَعْدِ","selepas"],["خَلْقٍۢ","ciptaan"],["فِى","dalam"],["ظُلُمَـٰتٍۢ","kegelapan[es]"],["ثَلَـٰثٍۢ ۚ","tiga"],["ذَٰلِكُمُ","Itu"],["ٱللَّهُ","(ialah) Allah"],["رَبُّكُمْ","Tuhanmu"],["لَهُ","untuk Dia"],["ٱلْمُلْكُ ۖ","(ialah) kekuasaan"],["لَآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ ۖ","Dia"],["فَأَنَّىٰ","Kemudian bagaimana"],["تُصْرَفُونَ","adakah kamu berpaling"]]],"4065":["(Jika kalian kafir maka sesungguhnya Allah tidak memerlukan kalian dan Dia tidak meridai kekafiran bagi hamba-hamba-Nya) sekalipun ada di antara hamba-hamba-Nya yang menghendakinya (dan jika kalian bersyukur) kepada Allah, karenanya lalu kalian beriman (niscaya Dia meridai tasyakur) dapat dibaca Yardhah atau Yardhahu, artinya Dia pasti meridai tasyakur (kalian itu; dan tidaklah akan menanggung dosa) yakni seseorang (yang telah berbuat dosa akan dosa) orang (yang lain) maksudnya, seseorang yang berdosa tidak akan memikul dosa orang lain. (Kemudian kepada Rabb kalianlah kembali kalian lalu Dia memberitakan kepada kalian apa yang telah kalian kerjakan. Sesungguhnya Dia Maha Mengetahui apa yang tersimpan dalam dada) dalam kalbu kalian.",[["إِن","Jika"],["تَكْفُرُوا۟","kamu tidak beriman"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["غَنِىٌّ","(adalah) bebas daripada keperluan"],["عَنكُمْ ۖ","daripada kamu"],["وَلَا","Dan tidak"],["يَرْضَىٰ","Dia suka"],["لِعِبَادِهِ","pada hamba-Nya"],["ٱلْكُفْرَ ۖ","tidak bersyukur"],["وَإِن","Dan jika"],["تَشْكُرُوا۟","kamu bersyukur"],["يَرْضَهُ","Dia suka"],["لَكُمْ ۗ","dalam kamu"],["وَلَا","Dan tidak"],["تَزِرُ","akan menanggung"],["وَازِرَةٌۭ","pembawa beban"],["وِزْرَ","(yang) beban"],["أُخْرَىٰ ۗ","(dari) yang lain"],["ثُمَّ","Kemudian"],["إِلَىٰ","kepada"],["رَبِّكُم","Tuhanmu"],["مَّرْجِعُكُمْ","(adalah) kamu kembali"],["فَيُنَبِّئُكُم","kemudian Dia akan memberitahu kamu"],["بِمَا","tentang apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ ۚ","lakukan"],["إِنَّهُۥ","Sesungguhnya Dia"],["عَلِيمٌۢ","(ialah) Yang Maha Mengetahui"],["بِذَاتِ","daripada apa yang ada dalam dada"],["ٱلصُّدُورِ","daripada apa yang ada dalam dada"]]],"4066":["(Dan apabila manusia itu ditimpa) yakni orang yang kafir (kemudaratan, dia memohon -pertolongan- kepada Rabbnya) yakni merintih kepada-Nya meminta pertolongan (dengan kembali) maksudnya, bertobat (kepada-Nya; kemudian apabila Rabb memberikan nikmat kepadanya) Dia memberinya nikmat (dari-Nya lupalah dia) artinya, dia meninggalkan (akan apa yang pernah ia serukan) yaitu lupa akan rintihannya (kepada-Nya sebelum itu) lupa kepada Allah. Lafal Maa di sini bermakna Man (dan dia mengada-adakan sekutu-sekutu bagi Allah) tandingan-tandingan bagi-Nya (untuk menyesatkan) manusia; lafal liyudhilla dapat dibaca liyadhilla (dari jalan-Nya) dari agama Islam (Katakanlah, \"Bersenang-senanglah dengan kekafiranmu itu sementara waktu) selama sisa hidupmu (sesungguhnya kamu termasuk penghuni neraka.\")",[["۞ وَإِذَا","Dan apabila"],["مَسَّ","sentuhan"],["ٱلْإِنسَـٰنَ","lelaki itu"],["ضُرٌّۭ","kesusahan"],["دَعَا","dia panggil"],["رَبَّهُۥ","Tuhannya"],["مُنِيبًا","berpusing"],["إِلَيْهِ","kepada-Nya"],["ثُمَّ","kemudian"],["إِذَا","apabila"],["خَوَّلَهُۥ","Dia menganugerahkan kepadanya"],["نِعْمَةًۭ","suatu nikmat"],["مِّنْهُ","daripada diriNya sendiri"],["نَسِىَ","dia lupa"],["مَا","(untuk) apa"],["كَانَ","dia pernah telefon"],["يَدْعُوٓا۟","dia pernah telefon"],["إِلَيْهِ","[kepada] Dia"],["مِن","sebelum"],["قَبْلُ","sebelum"],["وَجَعَلَ","dan dia menetapkan"],["لِلَّهِ","kepada Allah"],["أَندَادًۭا","saingan"],["لِّيُضِلَّ","untuk mengelirukan"],["عَن","daripada"],["سَبِيلِهِۦ ۚ","Jalan-Nya"],["قُلْ","Katakanlah"],["تَمَتَّعْ","Nikmati"],["بِكُفْرِكَ","dalam ketidakpercayaan kamu"],["قَلِيلًا ۖ","(untuk) sedikit"],["إِنَّكَ","Sesungguhnya kamu"],["مِنْ","(adalah) daripada"],["أَصْحَـٰبِ","(para) sahabat"],["ٱلنَّارِ","(dari) api"]]],"4067":["(Apakah orang) dibaca Amman, dan dapat dibaca Aman (yang beribadah) yang berdiri melakukan amal ketaatan, yakni salat (di waktu-waktu malam) di saat-saat malam hari (dengan sujud dan berdiri) dalam salat (sedangkan ia takut kepada hari akhirat) yakni takut akan azab pada hari itu (dan mengharapkan rahmat) yakni surga (Rabbnya) apakah dia sama dengan orang yang durhaka karena melakukan kekafiran atau perbuatan-perbuatan dosa lainnya. Menurut qiraat yang lain lafal Amman dibaca Am Man secara terpisah, dengan demikian berarti lafal Am bermakna Bal atau Hamzah Istifham (Katakanlah, \"Adakah sama orang-orang yong mengetahui dengan orang-orang yong tidak mengetahui?\") tentu saja tidak, perihalnya sama dengan perbedaan antara orang yang alim dan orang yang jahil. (Sesungguhnya orang yang dapat menerima pelajaran) artinya, man menerima nasihat (hanyalah orang-orang yang berakal) yakni orang-orang yang mempunyai pikiran.",[["أَمَّنْ","Adakah (seorang) yang"],["هُوَ","[dia]"],["قَـٰنِتٌ","(adalah) taat setia"],["ءَانَآءَ","(semasa) jam"],["ٱلَّيْلِ","(dari) malam"],["سَاجِدًۭا","sujud"],["وَقَآئِمًۭا","dan berdiri"],["يَحْذَرُ","takut"],["ٱلْـَٔاخِرَةَ","akhirat"],["وَيَرْجُوا۟","dan berharap"],["رَحْمَةَ","(untuk) Rahmat"],["رَبِّهِۦ ۗ","(dari) Tuhannya"],["قُلْ","Katakanlah"],["هَلْ","Adakah"],["يَسْتَوِى","sama rata"],["ٱلَّذِينَ","orang yang"],["يَعْلَمُونَ","mengetahui"],["وَٱلَّذِينَ","dan orang yang"],["لَا","jangan"],["يَعْلَمُونَ ۗ","mengetahui"],["إِنَّمَا","Hanya"],["يَتَذَكَّرُ","akan mengambil iktibar"],["أُو۟لُوا۟","mereka yang memahami"],["ٱلْأَلْبَـٰبِ","mereka yang memahami"]]],"4068":["(Katakanlah, \"Hai hamba-hamba-Ku yang beriman, bertakwalah kalian kepada Rabb kalian\") takutlah kalian akan azab-Nya, yaitu dengan jalan menaati-Nya. (Orang-orang yang berbuat baik di dunia ini memperoleh) melalui jalan ketaatan kepada Rabbnya (kebaikan) yakni surga. (Dan bumi Allah itu adalah luas) maka hijrahlah ke negeri yang lain meninggalkan orang-orang kafir demi menghindarkan diri dari menyaksikan hal-hal yang mungkar. (Sesungguhnya orang-orang yang bersabarlah yang dicukupkan) yang sabar di dalam menjalankan ketaatan dan sabar di dalam menahan ujian yang menimpa diri mereka (pahala mereka tanpa batas) yakni tanpa memakai neraca dan timbangan lagi.",[["قُلْ","Katakanlah"],["يَـٰعِبَادِ","Wahai hamba-Ku"],["ٱلَّذِينَ","[mereka] yang"],["ءَامَنُوا۟","beriman"],["ٱتَّقُوا۟","Takut"],["رَبَّكُمْ ۚ","Tuhanmu"],["لِلَّذِينَ","Bagi mereka yang"],["أَحْسَنُوا۟","berbuat baik"],["فِى","dalam"],["هَـٰذِهِ","ini"],["ٱلدُّنْيَا","dunia"],["حَسَنَةٌۭ ۗ","(adalah) baik"],["وَأَرْضُ","dan bumi"],["ٱللَّهِ","(milik) Allah"],["وَٰسِعَةٌ ۗ","(adalah) luas"],["إِنَّمَا","Hanya"],["يُوَفَّى","akan dibayar balik sepenuhnya"],["ٱلصَّـٰبِرُونَ","yang sabar"],["أَجْرَهُم","ganjaran mereka"],["بِغَيْرِ","tanpa"],["حِسَابٍۢ","akaun"]]],"4069":["(Katakanlah sesungguhnya aku diperintahkan supaya menyembah Allah dengan memurnikan ketaatan kepada-Nya) dari perbuatan syirik.",[["قُلْ","Katakanlah"],["إِنِّىٓ","Sesungguhnya aku"],["أُمِرْتُ","[Aku] diperintahkan"],["أَنْ","bahawa"],["أَعْبُدَ","aku menyembah"],["ٱللَّهَ","Allah"],["مُخْلِصًۭا","(bersifat) ikhlas"],["لَّهُ","kepada-Nya"],["ٱلدِّينَ","(dalam) agama"]]],"4070":["(Dan aku diperintahkan supaya menjadi orang yang pertama-tama berserah diri) dari kalangan umat ini.",[["وَأُمِرْتُ","Dan aku diperintahkan"],["لِأَنْ","bahawa"],["أَكُونَ","aku jadi"],["أَوَّلَ","(yang) pertama"],["ٱلْمُسْلِمِينَ","(dari) orang-orang yang berserah diri"]]],"4071":["(Katakanlah, \"Sesungguhnya aku takut akan siksaan hari yang besar jika aku durhaka kepada Rabbku\").",[["قُلْ","Katakanlah"],["إِنِّىٓ","Sesungguhnya aku"],["أَخَافُ","[Aku] takut"],["إِنْ","jika"],["عَصَيْتُ","aku ingkar"],["رَبِّى","Tuhanku"],["عَذَابَ","azab"],["يَوْمٍ","(dari) sehari"],["عَظِيمٍۢ","yang besar"]]],"4072":["(Katakanlah, \"Hanya Allah saja yang aku sembah dengan memurnikan ketaatan kepada-Nya\") dari perbuatan syirik atau menyekutukan Allah.",[["قُلِ","Katakanlah"],["ٱللَّهَ","Aku menyembah Allah"],["أَعْبُدُ","Aku menyembah Allah"],["مُخْلِصًۭا","(bersifat) ikhlas"],["لَّهُۥ","kepada-Nya"],["دِينِى","(dalam) agamaku"]]],"4073":["(Maka sembahlah oleh kalian apa yang kalian kehendaki selain Dia) selain-Nya. Di dalam ungkapan ayat ini terkandung makna ancaman bagi orang-orang musyrik dan sekaligus sebagai pemberitahuan, bahwa mereka tidak menyembah Allah swt. (Katakanlah, \"Sesungguhnya orang-orang yang rugi ialah orang-orang yang merugikan diri mereka sendiri dan keluarganya pada hari kiamat\") karena mereka akan menjadi penghuni neraka yang abadi, dan karena mereka tidak memperoleh bidadari-bidadari yang disediakan buat mereka, jika mereka beriman.- (Ingatlah yang demikian itu adalah kerugian yang nyata) jelas sekali ruginya.",[["فَٱعْبُدُوا۟","Maka beribadahlah"],["مَا","apa"],["شِئْتُم","kamu akan"],["مِّن","selain Dia"],["دُونِهِۦ ۗ","selain Dia"],["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["ٱلْخَـٰسِرِينَ","yang rugi"],["ٱلَّذِينَ","(adalah) mereka yang"],["خَسِرُوٓا۟","(akan) kalah"],["أَنفُسَهُمْ","diri mereka"],["وَأَهْلِيهِمْ","dan keluarga mereka"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ ۗ","Kiamat"],["أَلَا","Tidak dinafikan"],["ذَٰلِكَ","itu"],["هُوَ","ia"],["ٱلْخُسْرَانُ","(ialah) kerugian"],["ٱلْمُبِينُ","yang jelas"]]],"4074":["(Bagi mereka gumpalan-gumpalan di atas mereka) lapisan-lapisan (dari api dan di bawah mereka pun gumpalan-gumpalan) lapisan-lapisan dari api. (Demikianlah Allah mempertakuti hamba-hamba-Nya dengan azab itu) yakni hamba-hamba-Nya yang beriman, supaya mereka bertakwa kepada-Nya; pengertian ini disimpulkan dari firman selanjutnya, yaitu, (Maka bertakwalah kepada-Ku hai hamba-hamba-Ku).",[["لَهُم","Untuk mereka"],["مِّن","daripada"],["فَوْقِهِمْ","di atas mereka"],["ظُلَلٌۭ","penutup"],["مِّنَ","daripada"],["ٱلنَّارِ","neraka"],["وَمِن","dan daripada"],["تَحْتِهِمْ","di bawah mereka"],["ظُلَلٌۭ ۚ","penutup"],["ذَٰلِكَ","(Dengan) itu"],["يُخَوِّفُ","mengancam"],["ٱللَّهُ","Allah"],["بِهِۦ","[dengannya]"],["عِبَادَهُۥ ۚ","hambanya"],["يَـٰعِبَادِ","Wahai hamba-Ku"],["فَٱتَّقُونِ","Maka takutlah kepada-Ku"]]],"4075":["(Dan orang-orang yang menjauhi thaghut) yakni berhala-berhala (yaitu tidak menyembahnya dan kembali) menghadap (kepada Allah, bagi mereka berita gembira) yaitu mendapatkan surga (sebab itu sampaikanlah berita itu kepada hamba-hamba-Ku).",[["وَٱلَّذِينَ","Dan orang yang"],["ٱجْتَنَبُوا۟","elakkan"],["ٱلطَّـٰغُوتَ","tuhan-tuhan palsu"],["أَن","jangan-jangan"],["يَعْبُدُوهَا","mereka menyembah mereka"],["وَأَنَابُوٓا۟","dan pusing"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["لَهُمُ","bagi mereka"],["ٱلْبُشْرَىٰ ۚ","(adalah) berita gembira"],["فَبَشِّرْ","Maka sampaikanlah berita gembira"],["عِبَادِ","(kepada) hamba-hamba-Ku"]]],"4076":["(Yaitu, orang-orang yang mendengarkan perkataan lalu mengikuti apa yang paling baik di antaranya) mengikuti sesuatu yang mengandung kemaslahatan bagi mereka. (Mereka itulah orang-orang yang telah diberi Allah petunjuk dan mereka itulah orang-orang yang mempunyai akal) yang mempunyai pikiran.",[["ٱلَّذِينَ","Orang yang"],["يَسْتَمِعُونَ","mereka mendengar (kepada)"],["ٱلْقَوْلَ","Firman"],["فَيَتَّبِعُونَ","kemudian ikuti"],["أَحْسَنَهُۥٓ ۚ","yang terbaik daripadanya"],["أُو۟لَـٰٓئِكَ","mereka"],["ٱلَّذِينَ","(adalah) mereka yang"],["هَدَىٰهُمُ","Allah telah memberi petunjuk kepada mereka"],["ٱللَّهُ ۖ","Allah telah memberi petunjuk kepada mereka"],["وَأُو۟لَـٰٓئِكَ","dan mereka"],["هُمْ","adakah [mereka]"],["أُو۟لُوا۟","orang yang berakal"],["ٱلْأَلْبَـٰبِ","orang yang berakal"]]],"4077":["(Apakah orang yang telah pasti ketentuan azab atasnya?) termasuk orang-orang yang digolongkan oleh firman-Nya, \"Sesungguhnya akan Aku penuhi neraka jahanam...\" (Q.S. As-Sajdah, 13). (Apakah kamu akan menyelamatkan) maksudnya, mengeluarkan (orang yang berada dalam neraka) kalimat ayat ini menjadi Jawab Syarath, kemudian di dalamnya terdapat Isim Zhahir yaitu lafal Man yang menduduki tempat Isim Mudhmar; dan Hamzah Istifham di sini menunjukkan makna ingkar, yakni, kamu tidak akan mampu memberikan hidayah kepadanya sehingga ia dapat kamu selamatkan dari neraka.",[["أَفَمَنْ","Kemudian, adakah (seorang) yang"],["حَقَّ","menjadi kena dibayar"],["عَلَيْهِ","pada dia"],["كَلِمَةُ","perkataan itu"],["ٱلْعَذَابِ","(dari) hukuman itu"],["أَفَأَنتَ","Kemudian bolehkah kamu"],["تُنقِذُ","jimat"],["مَن","(satu) siapa"],["فِى","(berada) dalam"],["ٱلنَّارِ","neraka"]]],"4078":["(Tetapi orang-orang yang bertakwa kepada Rabbnya) yaitu bertakwa melalui jalan taat kepada-Nya (mereka mendapat tempat-tempat yang tinggi, di atasnya dibangun pula tempat-tempat yang tinggi, di bawahnya mengalir sungai-sungai) artinya sungai-sungai yang mengalir, baik di bawah tempat-tempat yang teratas maupun di tempat-tempat yang terbawah (sebagai janji Allah) lafal Wa'dallaahi dinashabkan oleh Fi'il yang diperkirakan keberadaannya pada sebelumnya (Allah tidak akan memungkiri janji-Nya) atau mengingkarinya.",[["لَـٰكِنِ","Tetapi"],["ٱلَّذِينَ","orang yang"],["ٱتَّقَوْا۟","bertakwa"],["رَبَّهُمْ","Tuhan mereka"],["لَهُمْ","bagi mereka"],["غُرَفٌۭ","(adalah) rumah agam yang tinggi"],["مِّن","di atas mereka"],["فَوْقِهَا","di atas mereka"],["غُرَفٌۭ","rumah agam yang tinggi"],["مَّبْنِيَّةٌۭ","dibina tinggi"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ ۖ","sungai-sungai"],["وَعْدَ","(The) Janji"],["ٱللَّهِ ۖ","(milik) Allah"],["لَا","Tidak"],["يُخْلِفُ","Allah gagal"],["ٱللَّهُ","Allah gagal"],["ٱلْمِيعَادَ","(dalam) janji-Nya"]]],"4079":["(Apakah kamu tidak memperhatikan) maksudnya tidak mengetahui (bahwa sesungguhnya Allah menurunkan air dari langit, maka diatur-Nya menjadi sumber-sumber) yakni, dia memasukkan air itu ke tempat-tempat yang dapat menjadi sumber air (di bumi kemudian ditumbuhkan-Nya dengan air itu tanam-tanaman yang bermacam-macam warnanya, lalu ia menjadi kering) menjadi layu dan kering (lalu kamu melihatnya) sesudah hijau menjadi (kekuning-kuningan kemudian dijadikan-Nya hancur berderai) yakni rontok (Sesungguhnya pada yang demikian itu benar-benar terdapat pelajaran) peringatan (bagi orang-orang yang mempunyai akal) bagi orang-orang yang mau mengambil pelajaran darinya untuk menyimpulkan keesaan dan kekuasaan Allah swt.",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["أَنزَلَ","menghantar turun"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["فَسَلَكَهُۥ","dan Dia mengalirkannya"],["يَنَـٰبِيعَ","(sebagai) mata air"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["ثُمَّ","kemudian"],["يُخْرِجُ","Dia menghasilkan"],["بِهِۦ","dengannya"],["زَرْعًۭا","tanaman"],["مُّخْتَلِفًا","(daripada) berbeza"],["أَلْوَٰنُهُۥ","warna"],["ثُمَّ","kemudian"],["يَهِيجُ","mereka layu"],["فَتَرَىٰهُ","dan kamu melihatnya"],["مُصْفَرًّۭا","menjadi kuning"],["ثُمَّ","kemudian"],["يَجْعَلُهُۥ","Dia membuat mereka"],["حُطَـٰمًا ۚ","serpihan"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَذِكْرَىٰ","sesungguhnya, (adalah) peringatan"],["لِأُو۟لِى","bagi mereka yang faham"],["ٱلْأَلْبَـٰبِ","bagi mereka yang faham"]]],"4080":["(Maka apakah orang-orang yang dibukakan Allah hatinya untuk menerima Islam) sehingga ia mendapat petunjuk (lalu ia mendapat cahaya dari Rabbnya) sama dengan orang yang hatinya dikunci mati; pengertian ini tersimpul dari firman selanjutnya (Maka kecelakaan yang besarlah) artinya, azab yang besarlah (bagi mereka yang telah membatu hatinya untuk mengingat Allah) maksudnya, untuk menerima Alquran. (Mereka itu dalam kesesatan yang nyata) nyata sekali sesatnya.",[["أَفَمَن","Begitu juga (satu untuk) siapa"],["شَرَحَ","Allah telah meluaskan"],["ٱللَّهُ","Allah telah meluaskan"],["صَدْرَهُۥ","buah dadanya"],["لِلْإِسْلَـٰمِ","untuk Islam"],["فَهُوَ","jadi dia"],["عَلَىٰ","(ada) pada"],["نُورٍۢ","sebuah cahaya"],["مِّن","daripada"],["رَّبِّهِۦ ۚ","Tuhannya"],["فَوَيْلٌۭ","jadi celaka"],["لِّلْقَـٰسِيَةِ","kepada (mereka yang) keras"],["قُلُوبُهُم","hati mereka"],["مِّن","daripada"],["ذِكْرِ","(yang) mengingati Allah"],["ٱللَّهِ ۚ","(yang) mengingati Allah"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["فِى","(ada) dalam"],["ضَلَـٰلٍۢ","ralat"],["مُّبِينٍ","yang nyata"]]],"4081":["(Allah telah menurunkan perkataan yang paling baik yaitu Kitab) Alquran; lafal Kitaaban menjadi Badal lafal Ahsanal Hadiitsi (yang serupa) satu sama lainnya sama dalam hal Nuzhum dan hal-hal lainnya (lagi berulang-ulang) diulang-ulang di dalamnya janji dan ancaman serta hal-hal lainnya (gemetarlah karenanya) yakni gemetar karena takut di kala disebutkan ancaman-Nya (kulit orang-orang yang takut) yang merasa takut (kepada Rabbnya, kemudian menjadi tenang kulit dan kalbu mereka di waktu mengingat Allah) sewaktu ingat akan janji-Nya. (Itulah) kitab Alquran itu (petunjuk Allah, dengan Kitab itu Dia menunjuki siapa yang dikehendaki-Nya. Dan barang siapa yang disesatkan Allah, niscaya tak ada baginya seorang pemberi petunjuk.)",[["ٱللَّهُ","Allah"],["نَزَّلَ","telah mendedahkan"],["أَحْسَنَ","(yang) terbaik"],["ٱلْحَدِيثِ","(dari) [the] statement"],["كِتَـٰبًۭا","sebuah Buku"],["مُّتَشَـٰبِهًۭا","(bahagian-bahagiannya) menyerupai satu sama lain"],["مَّثَانِىَ","sering diulang"],["تَقْشَعِرُّ","Menggigil"],["مِنْهُ","daripadanya"],["جُلُودُ","(the) kulit"],["ٱلَّذِينَ","orang yang"],["يَخْشَوْنَ","bertakwa"],["رَبَّهُمْ","Tuhan mereka"],["ثُمَّ","kemudian"],["تَلِينُ","berehat"],["جُلُودُهُمْ","kulit mereka"],["وَقُلُوبُهُمْ","dan hati mereka"],["إِلَىٰ","di"],["ذِكْرِ","(the) zikir"],["ٱللَّهِ ۚ","(milik) Allah"],["ذَٰلِكَ","Itu"],["هُدَى","(adalah) petunjuk"],["ٱللَّهِ","(milik) Allah"],["يَهْدِى","Dia membimbing"],["بِهِۦ","dengannya"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَمَن","Dan sesiapa"],["يُضْلِلِ","Allah biarkan sesat"],["ٱللَّهُ","Allah biarkan sesat"],["فَمَا","maka tidak"],["لَهُۥ","baginya"],["مِنْ","sebarang"],["هَادٍ","panduan"]]],"4082":["(Maka apakah orang yang menghindarkan) supaya jangan dilemparkan (dirinya ke dalam azab yang paling buruk di hari kiamat), azab yang paling keras, seumpamanya ia dicampakkan ke dalam neraka dalam keadaan terbelenggu tangannya disatukan dengan kepalanya, sama dengan orang yang beriman kepadanya yang dimasukkan ke dalam surga? (Dan dikatakan kepada orang-orang yang aniaya) yakni orang-orang kafir Mekah (\"Rasakanlah oleh kalian balasan apa yang telah kalian kerjakan\") sebagai pembalasannya.",[["أَفَمَن","Maka (ialah) dia yang"],["يَتَّقِى","akan melindungi"],["بِوَجْهِهِۦ","dengan mukanya"],["سُوٓءَ","(yang) paling teruk"],["ٱلْعَذَابِ","hukuman"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ ۚ","Kiamat"],["وَقِيلَ","Dan ia akan dikatakan"],["لِلظَّـٰلِمِينَ","kepada orang-orang yang zalim"],["ذُوقُوا۟","rasa"],["مَا","apa"],["كُنتُمْ","kamu pernah"],["تَكْسِبُونَ","peroleh"]]],"4083":["(Orang-orang yang sebelum mereka telah mendustakan) rasul-rasulnya yang mengatakan bahwa azab pasti datang (maka datanglah kepada mereka azab dari arah yang tidak mereka sangka) yang tidak mereka duga sedikit pun.",[["كَذَّبَ","dinafikan"],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ","(ada) sebelum mereka"],["فَأَتَىٰهُمُ","maka datanglah kepada mereka"],["ٱلْعَذَابُ","azab"],["مِنْ","daripada"],["حَيْثُ","di mana"],["لَا","tidak"],["يَشْعُرُونَ","mereka rasa"]]],"4084":["(Maka Allah merasakan kepada mereka kehinaan) artinya, mereka dihina dan direndahkan dengan berupa kutukan, pembunuhan dan lain sebagainya (pada kehidupan dunia. Dan sesungguhnya azab pada hari akhirat lebih besar kalau mereka) yakni orang-orang yang mendustakannya (mengetahui) azab akhirat, dan niscaya kalau mereka mengetahuinya maka mereka tidak akan mendustakannya.",[["فَأَذَاقَهُمُ","Maka Allah menjadikan mereka"],["ٱللَّهُ","Maka Allah menjadikan mereka"],["ٱلْخِزْىَ","aib itu"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا ۖ","dunia"],["وَلَعَذَابُ","dan sesungguhnya azab"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["أَكْبَرُ ۚ","(adalah) lebih besar"],["لَوْ","jika"],["كَانُوا۟","mereka"],["يَعْلَمُونَ","tahu"]]],"4085":["(Sesungguhnya telah Kami buatkan) telah Kami jadikan (bagi manusia dalam Alquran ini setiap macam perumpamaan supaya mereka dapat pelajaran) maksudnya, supaya mereka mau menerima nasihatnya.",[["وَلَقَدْ","Dan sesungguhnya"],["ضَرَبْنَا","Kami telah menetapkan"],["لِلنَّاسِ","untuk orang"],["فِى","dalam"],["هَـٰذَا","ini"],["ٱلْقُرْءَانِ","Quran"],["مِن","daripada"],["كُلِّ","setiap"],["مَثَلٍۢ","contoh"],["لَّعَلَّهُمْ","supaya mereka boleh"],["يَتَذَكَّرُونَ","ambil iktibar"]]],"4086":["(Ialah Alquran dalam bahasa Arab) ayat ini berkedudukan menjadi Hal Muakkidah atau kata keterangan yang mengukuhkan (yang tidak ada kebengkokan di dalamnya) tidak ada kekeliruan dan pertentangan (supaya mereka bertakwa) maksudnya, menghindarkan diri dari kekafiran.",[["قُرْءَانًا","Al-Quran"],["عَرَبِيًّا","(dalam) bahasa Arab"],["غَيْرَ","tanpa"],["ذِى","sebarang"],["عِوَجٍۢ","kebengkokan"],["لَّعَلَّهُمْ","supaya mereka boleh"],["يَتَّقُونَ","(menjadi) soleh"]]],"4087":["(Allah telah membuat) bagi orang yang musyrik dan orang yang bertauhid (perumpamaan yaitu seorang laki-laki) lafal Rajulan ini menjadi Badal dari lafal Matsalan (yang menjadi budak milik beberapa orang yang berserikat dalam perselisihan) yaitu mereka terlihat di dalam persengketaan dan akhlak mereka sangat buruk (dan seorang budak laki-laki yang menjadi milik penuh) milik sepenuhnya (dari seorang laki-laki saja; adakah kedua budak itu sama halnya?) lafal Matsalan berkedudukan menjadi Tamyiz maksudnya, tentu saja tidak sama antara seorang budak yang menjadi milik suatu kelompok dengan seorang budak yang menjadi milik penuh seorang saja. Sesungguhnya, budak yang pertama tadi apabila disuruh oleh masing-masing dari pemilik dirinya secara sekaligus; ia bingung, siapakah yang harus ia layani di antara mereka. Ini adalah perumpamaan orang yang musyrik sedangkan budak yang kedua adalah perumpamaan bagi orang yang bertauhid. (Segala puji bagi Allah) semata (tetapi kebanyakan mereka) penduduk Mekah (tidak mengetahui) azab apakah yang akan menimpa mereka akibat kemusyrikannya, oleh karena itu mereka berbuat kemusyrikan.",[["ضَرَبَ","Allah menetapkan"],["ٱللَّهُ","Allah menetapkan"],["مَثَلًۭا","satu contoh"],["رَّجُلًۭا","seorang lelaki"],["فِيهِ","tentang dia"],["شُرَكَآءُ","rakan kongsi"],["مُتَشَـٰكِسُونَ","bergaduh"],["وَرَجُلًۭا","dan seorang lelaki"],["سَلَمًۭا","(kepunyaan) secara eksklusif"],["لِّرَجُلٍ","kepada seorang lelaki"],["هَلْ","adalah"],["يَسْتَوِيَانِ","mereka berdua sama"],["مَثَلًا ۚ","(dalam) perbandingan"],["ٱلْحَمْدُ","Segala puji"],["لِلَّهِ ۚ","bagi Allah"],["بَلْ","Bahkan"],["أَكْثَرُهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"4088":["(Sesungguhnya kamu) khithab ini ditujukan kepada Nabi saw. (akan mati dan mereka akan mati pula) kelak kamu akan mati dan mereka kelak akan mati pula, maka tidak usah ditunggu-tunggu datangnya mati itu. Ayat ini diturunkan sewaktu mereka merasa lambat akan kematian Nabi saw.",[["إِنَّكَ","Sesungguhnya kamu"],["مَيِّتٌۭ","akan mati"],["وَإِنَّهُم","dan sesungguhnya, mereka"],["مَّيِّتُونَ","(juga akan) mati"]]],"4089":["(Kemudian sesungguhnya kalian) hai manusia tentang kelaliman-kelaliman yang telah terjadi di antara kalian (pada hari kiamat akan berbantah-bantahan di hadapan Rabb kalian.)",[["ثُمَّ","Kemudian"],["إِنَّكُمْ","sesungguhnya kamu"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["عِندَ","sebelum"],["رَبِّكُمْ","Tuhanmu"],["تَخْتَصِمُونَ","akan mempertikaikan"]]]});